1	// The earliest unmet gate of one work item: what the item needs next, which earlier stage results are still valid
2	// (reused, never paid for twice), which are stale (and why), and, for a genuinely blocked item, the blocker, the
3	// responsible role and the condition for resuming. Pure: every input is passed in.
4	//
5	// The lifecycle (work-ledger.mjs STAGES): plan -> implement -> review -> validate -> outcome.
6	//   plan       an item with no ticket is planned from its requirement (mode `author`); an item with a ticket has
7	//              that ticket's assumptions, scope, dependencies and acceptance re-checked (mode `revalidate`).
8	//   implement  consumes the approved plan.        review    the coordinated three-lab cycle review of the change.
9	//   validate   the exact change against the original requirement and the approved acceptance criteria.
10	//   outcome    the unsigned status transition for the owner, who alone signs the status ledger.
11	// A stage result is valid only while the chain it rests on holds: a passed stage is reused only if its handoff
12	// reaches back, stage by stage, to a plan that is still valid for the current requirement, dependencies, ticket
13	// bytes and evidence bytes. A change to any of those makes the plan stale and everything after it with it.
14	//
15	// Must never: treat a published issue, a ticket, a green CI run or a Resolved label as evidence that a stage ran;
16	// read issue text as authority; or route a blocked item to execution.
17	import {STAGES, outputsDigest} from './work-ledger.mjs';
18	import {digest} from '../../packages/ledger/canonical.mjs';
19	
20	/** The original requirement of an item: its id and title with the basis of its latest Ready status (else latest). */
21	export function requirementOf(history) {
22	  if (!history?.length) return null;
23	  const ready = [...history].reverse().find(s => s.state === 'Ready') ?? history.at(-1);
24	  return {item: ready.item, title: ready.title, basis: ready.basis, entry: ready.entry};
25	}
26	export const requirementDigest = req => 'sha256:' + digest({item: req.item, title: req.title, basis: req.basis});
27	
28	/** Is the cited completion evidence on a Resolved status applicable: bound to a ticket, a commit and a 3-lab close? */
29	export function completionEvidence(status) {
30	  const ev = status?.evidence ?? null;
31	  if (!ev) return {ok: false, why: 'Resolved without recorded completion evidence (an attested basis only)'};
32	  const labs = new Set((ev.review?.reviewers ?? []).map(r => r.lab));
33	  if (!ev.ticket) return {ok: false, why: 'the completion evidence names no ticket'};
34	  if (!ev.commit) return {ok: false, why: 'the completion evidence names no commit'};
35	  if (!ev.review?.close_entry || ev.review.outcome !== 'verified') return {ok: false, why: 'the completion evidence has no verified review close'};
36	  if (labs.size < 3) return {ok: false, why: `the completion evidence names ${labs.size} review lab(s); three are required`};
37	  return {ok: true};
38	}
39	
40	/**
41	 * Validity of a passed plan record against the present: requirement, dependency statuses, ticket bytes and the
42	 * bytes of the evidence the plan rests on. `bytesOf(path)` returns the current sha256 of a repository path or null.
43	 */
44	export function planValidity(plan, {requirement, deps, ticket, bytesOf = () => null}) {
45	  const why = [];
46	  if (plan.identity.requirement !== requirementDigest(requirement)) why.push('the original requirement changed');
47	  for (const [d, entry] of Object.entries(plan.outputs.deps ?? {})) if ((deps[d]?.entry ?? null) !== entry) why.push(`dependency ${d} changed`);
48	  for (const d of Object.keys(deps)) if (!(d in (plan.outputs.deps ?? {}))) why.push(`dependency ${d} was added`);
49	  const planned = plan.outputs.ticket ?? null;
50	  if (planned && ticket && planned.digest !== ticket.digest) why.push('the ticket was changed after the plan approved it');
51	  if (planned && !ticket) why.push('the ticket the plan wrote is missing');
52	  for (const ev of plan.outputs.evidence ?? []) if (ev.path && ev.sha256 && bytesOf(ev.path) !== ev.sha256) why.push(`evidence ${ev.path} changed`);
53	  return {valid: why.length === 0, why};
54	}
55	
56	/** The chain of passed stages that rests on `plan`, in order, following handoffs (each must be the next stage). */
57	function chainFrom(plan, stages, usable = () => true) {
58	  const chain = [plan];
59	  for (;;) {
60	    const last = chain.at(-1);
61	    const nextName = STAGES[STAGES.indexOf(last.stage) + 1];
62	    if (!nextName) break;
63	    const after = stages.filter(s => s.handoff?.from === last.hash && s.stage === nextName);
64	    const passed = after.filter(s => s.status === 'passed' && s.inputs.upstream === outputsDigest(last.outputs) && usable(s)).at(-1);
65	    if (!passed) break;
66	    chain.push(passed);
67	  }
68	  return chain;
69	}
