71	/**
72	 * The earliest unmet gate. `item` is the latest status (with `entry`, `evidence`); `history` its statuses in order;
73	 * `depStatus(id)` the latest status of a dependency or null; `ticket` the readTicket result ({spec, digest, path}
74	 * or {why}) or null; `stages` this item's work.stage records in ledger order; `activeClaim` the live claim or null.
75	 */
76	export function earliestGate({item, history, depStatus, ticket = null, stages = [], activeClaim = null, bytesOf, now = Date.now(), recovery = null, evidenceStable = null, reassessments = []}) {
77	  const base = {item: item.item, state: item.state};
78	  // REASSESSMENT (work.reassessment): a later identity policy found that a recorded review of a cycle would not
79	  // qualify. That is evidence against reusing the approval: a stage whose approval came from such a cycle, and every
80	  // stage resting on it, is not reused. Nothing recorded is changed; the cycle still verifies under its own policy.
81	  const disqualified = new Map(reassessments.filter(r => (r.findings ?? []).length).map(r => [r.cycle, r]));
82	  const cyclesOf = s => (s.stage === 'plan' ? [s.outputs?.plan_review?.cycle] : s.stage === 'review' ? [s.outputs?.cycle] : []).filter(Boolean);
83	  const hit = s => cyclesOf(s).map(c => disqualified.get(c)).find(Boolean) ?? null;
84	  if (activeClaim) return {...base, gate: 'claimed', reason: `claimed: ${activeClaim.stage}, attempt ${activeClaim.attempt} (lease)`, claim: activeClaim.hash};
85	  if (item.state === 'Resolved') {
86	    const ev = completionEvidence(item);
87	    // A Resolved item whose completion evidence rests on a disqualified review NEEDS RE-VERIFICATION. The owner's signed
88	    // status is not rewritten and the item is not reopened: the need is recorded here, for the owner.
89	    const again = ev.ok ? disqualified.get(item.evidence?.review?.cycle) ?? null : null;
90	    if (again) {
91	      const what = `the review this Resolved status rests on was disqualified by a reassessment (${again.hash.slice(0, 19)}): ${again.findings.map(x => x.why).join('; ')}`;
92	      return {...base, gate: 'reverification-needed', reason: what, reassessment: again.hash,
93	        blocker: {what, role: 'decision-authority', resume_when: 'the owner records the item Ready to re-verify it through the lifecycle, or records why the status stands'}};
94	    }
95	    if (ev.ok) return {...base, gate: 'complete', reason: 'Resolved with completion evidence bound to its ticket, commit and a three-lab verified review'};
96	    // Evidence recovery (evidence-recovery.mjs) for THIS status entry: recovered evidence waits for the owner's
97	    // signature; a search that found none says what it searched. The status itself is never changed here.
98	    if (recovery?.outcome === 'recovered') {
99	      return {...base, gate: 'awaiting-owner', reason: `${ev.why}; completion evidence was recovered from a retained run (proposal ${recovery.proposal.digest.slice(0, 19)})`,
100	        recovery: {outcome: recovery.outcome, record: recovery.hash, proposal: recovery.proposal.digest},
101	        blocker: {what: 'an unsigned proposal re-recording Resolved with recovered, structurally re-checked completion evidence', role: 'decision-authority',
102	          resume_when: 'the owner applies the proposal (node packages/ledger/status.mjs apply <file>) or declines it'}};
103	    }
104	    const searched = recovery ? `; evidence recovery searched ${recovery.searched.length} source(s) and none applies (${recovery.searched.map(x => `${x.ref}: ${x.result}`).join('; ')})`
105	      : '; evidence recovery has not searched yet';
106	    return {...base, gate: 'evidence-gap', reason: ev.why + searched, ...(recovery ? {recovery: {outcome: recovery.outcome, record: recovery.hash}} : {}),
107	      blocker: {what: ev.why + searched, role: 'decision-authority',
108	        resume_when: 'applicable retained evidence appears (searched again automatically when the item\'s sources change), or the owner records the item Ready to re-verify it through the lifecycle'}};
109	  }
110	  if (item.state === 'On Hold') {
111	    const what = item.waiting_on ? `waiting on ${item.waiting_on}: ${item.basis}` : `held: ${item.basis}`;
112	    return {...base, gate: 'blocked', reason: what, blocker: {what, role: item.owner_role ?? 'decision-authority',
113	      resume_when: item.waiting_on ? `the ${item.waiting_on} is supplied and the owner records the item Ready` : 'the owner records the item Ready'}};
114	  }
115	  const deps = Object.fromEntries((item.depends_on ?? []).map(d => [d, depStatus(d)]));
116	  const open = Object.entries(deps).filter(([, s]) => s?.state !== 'Resolved').map(([d]) => d);
117	  if (open.length) {
118	    return {...base, gate: 'blocked', reason: `depends on ${open.join(', ')}`, blocker: {what: `unresolved dependencies: ${open.join(', ')}`,
119	      role: 'lead@orch', resume_when: `${open.join(', ')} Resolved`}};
120	  }
121	  const requirement = requirementOf(history);
122	  const t = ticket && !ticket.why ? ticket : null;
123	  const stale = [];
124	  // A plan attempt that is pending or blocked on the present requirement decides, as a later attempt does after a
125	  // valid chain below: a structural block waits (it is not re-dispatched on identical inputs), and a transient one is
126	  // retried once due. A changed requirement makes it stale and the item is planned again.
127	  const lastPlan = stages.filter(s => s.stage === 'plan').at(-1) ?? null;
128	  if (lastPlan && (lastPlan.status === 'pending' || lastPlan.status === 'blocked') && lastPlan.identity?.requirement === requirementDigest(requirement)) {
129	    const returnedBy = lastPlan.inputs?.returned_by ?? null;
130	    if (lastPlan.status === 'pending' && lastPlan.blocker?.transient && Date.parse(lastPlan.blocker.retry_at ?? '') <= now) {
131	      return {...base, gate: 'plan', mode: lastPlan.outputs?.mode ?? (t ? 'revalidate' : 'author'), requirement, retry_of: lastPlan.hash, stale,
132	        ...(returnedBy ? {returned_by: returnedBy, findings: stages.find(x => x.hash === returnedBy)?.findings ?? []} : {}),
133	        reason: `plan was pending on a transient failure (${lastPlan.blocker.what}); its retry is due`};
134	    }
135	    // A plan that waited for evidence is planned again when the evidence changed (the dossier's stable digest), within
136	    // the scheduler's attempt bound; unchanged evidence is not paid for twice.
137	    if (lastPlan.blocker?.code === 'EVIDENCE_INSUFFICIENT' && evidenceStable && evidenceStable !== lastPlan.outputs?.context?.dossier?.stable) {
138	      return {...base, gate: 'plan', mode: lastPlan.outputs?.mode ?? (t ? 'revalidate' : 'author'), requirement, retry_of: lastPlan.hash, stale,
139	        ...(returnedBy ? {returned_by: returnedBy, findings: stages.find(x => x.hash === returnedBy)?.findings ?? []} : {}),
140	        reason: 'the plan waited for evidence, and the evidence available to it has changed'};
141	    }
142	    return {...base, gate: 'blocked', stage: 'plan', requirement, blocker: lastPlan.blocker, stale,
143	      reason: `plan is ${lastPlan.status}: ${lastPlan.blocker?.what ?? lastPlan.next?.why ?? ''}`};
144	  }
145	  const passedPlans = stages.filter(s => s.stage === 'plan' && s.status === 'passed');
146	  let valid = null, planReassessed = null;
147	  for (const p of [...passedPlans].reverse()) {
148	    const v = planValidity(p, {requirement, deps: Object.fromEntries(Object.entries(deps).map(([d, s]) => [d, s ? {entry: s.entry} : null])), ticket: t, bytesOf});
149	    const bad = hit(p);
150	    if (bad) { planReassessed ??= bad; stale.push({stage: 'plan', record: p.hash, why: [`its plan review was disqualified by reassessment ${bad.hash.slice(0, 19)}`]}); continue; }
151	    if (v.valid) { valid = p; break; }
152	    stale.push({stage: 'plan', record: p.hash, why: v.why});
153	  }
154	  if (!valid) {
155	    return {...base, gate: 'plan', mode: t ? 'revalidate' : 'author', requirement, stale,
156	      ...(planReassessed ? {rereview: {stage: 'plan', cycle: planReassessed.cycle, reassessment: planReassessed.hash, policy_rules: planReassessed.policy_rules ?? null}} : {}),
157	      reason: planReassessed ? 'the plan\'s review was disqualified by a reassessment: the plan is re-checked and reviewed again'
158	        : t ? 'a ticket exists; its assumptions, scope, dependencies and acceptance criteria need re-checking' : 'no approved plan and no ticket: evaluation and planning'};
159	  }
160	  const chain = chainFrom(valid, stages, s => !hit(s));
161	  const reuse = Object.fromEntries(chain.map(s => [s.stage, s.hash]));
162	  const last = chain.at(-1);
163	  // A later attempt of the next stage that returned work to an earlier stage, or is pending/blocked, decides.
164	  const nextName = STAGES[STAGES.indexOf(last.stage) + 1] ?? null;
165	  // Follow the explicit handoff only: a record with equal output bytes from another chain is not this attempt.
166	  const tried = stages.filter(s => s.handoff?.from === last.hash);
167	  const latestTry = tried.at(-1) ?? null;
168	  // The stage after `last` passed, but on a review that a reassessment disqualified: it is done again, in its own
169	  // bounded re-review, and validation and the outcome that rested on it are not reused.
170	  const voided = latestTry?.status === 'passed' ? hit(latestTry) : null;
171	  if (voided) {
172	    return {...base, gate: latestTry.stage, mode: 'rereview', requirement, reuse, from: last.hash, stale: [...stale, {stage: latestTry.stage, record: latestTry.hash, why: [`disqualified by reassessment ${voided.hash.slice(0, 19)}`]}],
173	      rereview: {stage: latestTry.stage, cycle: voided.cycle, reassessment: voided.hash, policy_rules: voided.policy_rules ?? null, replaces: latestTry.hash},
174	      reason: `the ${latestTry.stage} of this work was disqualified by a reassessment (${voided.findings.map(x => x.why).join('; ')}): it is reviewed again`};
175	  }
176	  if (latestTry?.status === 'returned') {
177	    const to = latestTry.next.stage;
178	    const back = chain.find(s => s.stage === STAGES[STAGES.indexOf(to) - 1]) ?? null;
179	    return {...base, gate: to, mode: 'revise', requirement, reuse: Object.fromEntries(chain.filter(s => STAGES.indexOf(s.stage) < STAGES.indexOf(to)).map(s => [s.stage, s.hash])),
180	      from: back?.hash ?? null, findings: latestTry.findings, returned_by: latestTry.hash, stale, reason: `${latestTry.stage} returned the work to ${to}: ${latestTry.next.why}`};
181	  }
182	  // A transient pending whose retry is due goes back to its stage (the executor resumes its open cycle; the scheduler
183	  // bounds the retries on the same inputs). Before it is due, or for a structural pending, the item is blocked.
184	  if (latestTry?.status === 'pending' && latestTry.blocker?.transient && Date.parse(latestTry.blocker.retry_at ?? '') <= now) {
185	    return {...base, gate: latestTry.stage, mode: 'resume', requirement, reuse, from: last.hash, retry_of: latestTry.hash, stale,
186	      reason: `${latestTry.stage} was pending on a transient failure (${latestTry.blocker.what}); its retry is due`};
187	  }
188	  if (latestTry && (latestTry.status === 'pending' || latestTry.status === 'blocked')) {
189	    return {...base, gate: 'blocked', stage: latestTry.stage, requirement, reuse, from: last.hash, blocker: latestTry.blocker, stale,
190	      reason: `${latestTry.stage} is ${latestTry.status}: ${latestTry.blocker?.what ?? latestTry.next?.why ?? ''}`};
191	  }
192	  if (!nextName) return {...base, gate: 'awaiting-owner', requirement, reuse, stale, reason: 'the outcome is recorded; the owner signs the status transition',
193	    blocker: {what: 'an unsigned status transition', role: 'decision-authority', resume_when: 'the owner applies (or declines) the proposal'}};
194	  return {...base, gate: nextName, requirement, reuse, from: last.hash, stale, reason: `${last.stage} passed and is reused; ${nextName} is next`};
195	}
