1	// One work identity per item. Reconciliation joins every representation of the same work -- the status ledger
2	// item (authoritative), its published GitHub issue (by the `<!-- ophanim:item=ID -->` marker the public record
3	// writes), its ticket (tickets/<item>.json), its retained runs (evidence bundles naming the item), and its work
4	// ledger records (claims, stage results, findings, usage) -- so an issue and its ticket are never two jobs.
5	//
6	// Counts are read, never assumed. An issue with no marker is an intake CANDIDATE: recorded, classified for the
7	// owner, never executed (issue text and comments are task data, not authority). A ticket for an item that is not
8	// on the ledger is an orphan, reported. Two issues carrying the same item marker are reported as a duplicate.
9	//
10	// Inputs: repo, statusRoot, workLedger (openWorkLedger), issues (a snapshot array {number, title, body, state,
11	// labels}) or null, bundlesDir or null. Output: {items: [{item, status, history, ticket, issues, runs, gate,
12	// stages}], candidates, orphans, duplicates, counts}. Pure apart from reading those files.
13	import fs from 'node:fs';
14	import path from 'node:path';
15	import {createHash} from 'node:crypto';
16	import {openStatusLedger} from '../../packages/ledger/status.mjs';
17	import {readTicket} from '../../pantheon/src/board/operate.mjs';
18	import {buildDossier} from './context.mjs';
19	import {earliestGate} from './gates.mjs';
20	
21	export const MARKER = /<!--\s*ophanim:item=([a-z0-9][a-z0-9.-]{0,63})\s*-->/;
22	
23	/** Every status entry of every item, in ledger order, with its entry hash. */
24	export function statusHistory(statusRoot) {
25	  const S = openStatusLedger({root: statusRoot, create: false});
26	  const L = S.ledger, byItem = new Map();
27	  for (const e of L.read()) {
28	    if (e.kind !== 'status') continue;
29	    const p = L.payloadOf(e);
30	    (byItem.get(p.item) ?? byItem.set(p.item, []).get(p.item)).push({...p, entry: L.hashOf(e)});
31	  }
32	  return {board: S.board(), byItem};
33	}
34	
35	/** Retained runs: evidence bundles under `dir` (any depth), by the item they name. */
36	export function retainedRuns(dir) {
37	  const out = new Map();
38	  if (!dir || !fs.existsSync(dir)) return out;
39	  const walk = d => {
40	    for (const e of fs.readdirSync(d, {withFileTypes: true})) {
41	      const p = path.join(d, e.name);
42	      if (e.isDirectory()) walk(p);
43	      else if (e.name === 'evidence.json') {
44	        try {
45	          const b = JSON.parse(fs.readFileSync(p, 'utf8'));
46	          if (b.item) (out.get(b.item) ?? out.set(b.item, []).get(b.item)).push({file: p, shipped: b.run?.shipped ?? null, commit: b.commit ?? null,
47	            review: b.review ? {status: b.review.status ?? (b.review.close ? 'closed' : 'open'), outcome: b.review.outcome ?? null} : null, ticket: b.ticket?.digest ?? null});
48	        } catch { /* an unreadable bundle is not evidence */ }
49	      }
50	    }
51	  };
52	  walk(dir);
53	  return out;
54	}
55	
56	/** The current sha256 of a repository path, or null. */
57	export const bytesOfRepo = repo => p => {
58	  const f = path.resolve(repo, p);
59	  return fs.existsSync(f) && fs.statSync(f).isFile() ? 'sha256:' + createHash('sha256').update(fs.readFileSync(f)).digest('hex') : null;
60	};
61	
62	export function reconcile({repo, statusRoot, workLedger, issues = null, bundlesDir = null, now = Date.now()}) {
63	  const {board, byItem} = statusHistory(statusRoot);
64	  const latest = new Map(board.items.map(i => [i.item, i]));
65	  const runs = retainedRuns(bundlesDir);
66	  const ticketsDir = path.join(repo, 'tickets');
67	  const ticketItems = fs.existsSync(ticketsDir) ? fs.readdirSync(ticketsDir).filter(f => f.endsWith('.json')).map(f => f.slice(0, -5)) : [];
68	  const issueByItem = new Map(), candidates = [], duplicates = [];
69	  for (const issue of issues ?? []) {
70	    const m = MARKER.exec(issue.body ?? '');
71	    if (!m) { candidates.push({number: issue.number, title: issue.title, state: issue.state, why: 'no item marker: an intake candidate for the owner to classify; never executed on its own'}); continue; }
72	    const list = issueByItem.get(m[1]) ?? issueByItem.set(m[1], []).get(m[1]);
73	    list.push(issue.number);
74	    if (list.length === 2) duplicates.push({item: m[1], issues: list});
75	  }
76	  const bytesOf = bytesOfRepo(repo);
77	  const items = board.items.map(s => {
78	    const ticketFile = path.join(ticketsDir, `${s.item}.json`);
79	    const ticket = fs.existsSync(ticketFile) ? readTicket({repo, item: s.item}) : null;
80	    const stages = workLedger ? workLedger.stages(s.item) : [];
81	    const activeClaim = workLedger ? workLedger.activeClaim(s.item, now) : null;
82	    const gate = earliestGate({item: s, history: byItem.get(s.item) ?? [s], depStatus: d => latest.get(d) ?? null, ticket, stages, activeClaim, bytesOf, now,
83	      recovery: workLedger ? workLedger.recoveries(s.item).filter(r => r.status_entry === s.entry).at(-1) ?? null : null,
84	      reassessments: workLedger?.reassessments ? workLedger.reassessments(s.item) : [],
85	      // Only for a plan waiting on evidence: what the evidence looks like now (context.mjs), so a change wakes it.
86	      evidenceStable: stages.filter(x => x.stage === 'plan').at(-1)?.blocker?.code === 'EVIDENCE_INSUFFICIENT'
87	        ? (() => { try { return buildDossier({repo, statusRoot, item: s.item, work: workLedger, issues, bundlesDir}).stable; } catch { return null; } })() : null});
88	    return {item: s.item, title: s.title, status: s.state, entry: s.entry, depends_on: s.depends_on ?? [], history: (byItem.get(s.item) ?? []).length,
89	      ticket: ticket ? (ticket.why ? {invalid: ticket.why} : {path: ticket.path, digest: ticket.digest}) : null,
90	      issues: issueByItem.get(s.item) ?? [], runs: runs.get(s.item) ?? [], stages: stages.length, gate};
91	  });
92	  const orphans = ticketItems.filter(i => !latest.has(i)).map(i => ({ticket: `tickets/${i}.json`, why: 'a ticket for an item that is not on the status ledger'}));
93	  const gateCounts = {};
94	  for (const i of items) gateCounts[i.gate.gate] = (gateCounts[i.gate.gate] ?? 0) + 1;
95	  return {at: new Date(now).toISOString(), ledger: {head: board.head, entries: board.entries}, items, candidates, orphans, duplicates,
96	    counts: {items: items.length, issues: (issues ?? []).length, linked_issues: [...issueByItem.values()].flat().length, candidates: candidates.length,
97	      tickets: ticketItems.length, orphans: orphans.length, items_with_runs: items.filter(i => i.runs.length).length, by_gate: gateCounts}};
98	}
