108	/** A metered `turn`: every call (failed ones included) counts; a call past the limit is refused, not made. */
109	// The stage's call meter. With the scheduler's ctx ({charge, signal}), every call is CHARGED on the work ledger
110	// before it is made (a call that leaves the process is counted even if the process dies), and no call is admitted
111	// once the stage's elapsed budget is spent (the cooperative stop). A refused charge is a refused call.
112	function meter(turn, limit, ctx = {}) {
113	  const m = {made: 0, refused: 0, limit};
114	  m.turn = args => {
115	    if (ctx.signal?.aborted) { m.refused++; return Promise.reject(Object.assign(new Error(`STAGE_ELAPSED: ${ctx.signal.reason?.message ?? 'the stage was stopped'}`), {code: 'STAGE_ELAPSED'})); }
116	    if (m.made >= m.limit) { m.refused++; return Promise.reject(Object.assign(new Error(`PROVIDER_CALL_LIMIT: ${m.made} of ${m.limit} stage provider call(s) used`), {code: 'PROVIDER_CALL_LIMIT'})); }
117	    if (typeof ctx.charge === 'function') { try { ctx.charge(1); } catch (e) { m.refused++; return Promise.reject(e); } }
118	    m.made++;
119	    return Promise.resolve().then(() => turn(args));
120	  };
121	  m.left = () => m.limit - m.made;
122	  return m;
123	}
