38	/**
39	 * Provider calls spent according to the work ledger, per claim:
40	 *   - a claim with a stage record: the larger of the record's usage (unknown usage counts at the claim's budget) and
41	 *     what was charged under it (work.spend);
42	 *   - a claim with no stage record (released, expired or interrupted): what was charged under it, so calls that left a
43	 *     process which then died are still counted (independent review, assignment 3, question 8);
44	 *   - a claim still live at `now` with no stage record: its charges so far, plus the REST OF ITS BUDGET as `reserved`
45	 *     (an in-flight reservation: a concurrent stage cannot spend what this one may still use; questions 1-3).
46	 * The budget check is total - calls - reserved.
47	 */
48	export function spent(work, {now = Date.now()} = {}) {
49	  const charged = new Map();
50	  for (const x of work.spends()) { const h = x.derived_from[0]; charged.set(h, Math.max(charged.get(h) ?? 0, x.provider_calls)); }
51	  const byClaim = new Map();
52	  for (const s of work.stages()) byClaim.set(s.derived_from[0], s);
53	  const released = new Set(work.releases().map(r => r.derived_from[0]));
54	  let calls = 0, unknown = 0, reserved = 0, chargedTotal = 0;
55	  for (const c of work.claims()) {
56	    const ch = charged.get(c.hash) ?? 0, s = byClaim.get(c.hash);
57	    chargedTotal += ch;
58	    if (s) {
59	      const u = s.usage?.provider_calls;
60	      if (Number.isInteger(u)) calls += Math.max(u, ch);
