250	/** Items in dependency order (a dependency before its dependents), then by id. */
251	export function dependencyOrder(items) {
252	  const by = new Map(items.map(i => [i.item, i])), out = [], seen = new Set();
253	  const visit = i => { if (seen.has(i.item)) return; seen.add(i.item); for (const d of i.depends_on ?? []) if (by.has(d)) visit(by.get(d)); out.push(i); };
