258	/**
259	 * The trigger: tick whenever the input signature changes. `once` runs a single check (for tests and cron);
260	 * otherwise it polls every `interval_ms` until `signal` aborts. Returns the ticks it ran.
261	 */
262	export async function watch({repo, statusRoot, workRoot, fetchIssues = async () => null, interval_ms = 60_000, once = false, signal = null, state = {last: null}, ...rest}) {
263	  const ticks = [];
264	  for (;;) {
265	    const issues = await fetchIssues();
266	    const sig = inputSignature({repo, statusRoot, workRoot, issues});
267	    // A tick runs when an input changed, or when a transient pending's retry is due (time is not an input).
268	    const now = (rest.clock ?? Date.now)();
269	    if (sig !== state.last || (state.due !== null && state.due !== undefined && now >= state.due)) {
270	      const t = await tick({repo, statusRoot, workRoot, issues, ...rest});
271	      ticks.push(t);
272	      state.last = inputSignature({repo, statusRoot, workRoot, issues});
273	      const dues = t.blocked.map(b => Date.parse(b.blocker?.retry_at ?? '')).filter(Number.isFinite);
