1	// EVIDENCE BEFORE JUDGMENT (owner direction 2026-11-17, docs/context-and-evidence.md).
2	//
3	// Every model seat of the lifecycle (planner, plan reviewer, change reviewer, validator) is given an initial view of
4	// the evidence -- the DOSSIER -- before it is asked to diagnose, plan or judge, and a bounded, read-only way to
5	// challenge that view and RETRIEVE the underlying records. The dossier is a starting selection, not a filter: nothing
6	// in it limits what the model may retrieve, and what it leaves out is listed, never silent.
7	//
8	//   buildDossier   the initial view of one item, from the existing stores: the status ledger (requirement, history,
9	//                  dependencies and dependents), the work ledger (stages, findings, blockers, recoveries), the ticket,
10	//                  the published issue, the files in play with their consumers and history, retained runs, and a
11	//                  repository index. Each entry states its KIND (authoritative-requirement, observation, derived,
12	//                  hypothesis), source, version, as-of and COVERAGE (complete, or an excerpt of how much).
13	//   makeRetriever  read-only operations over the same stores: file, list, grep, log, show, status, work, record,
14	//                  issue, output. Each names a VIEW (source and version) and returns a byte window of it with the
15	//                  request that continues it; a missing source, a refused path (the real target is checked, links
16	//                  included) and a cut are part of the result, never dropped.
17	//   investigate    the loop a seat runs: the model may answer with {"requests": [...]} instead of its judgment;
18	//                  the results are appended and it is asked again, within declared bounds (rounds, requests, bytes).
19	//                  At the bound it is told so and must answer, stating what it could not see.
20	//   delivery       what one seat was actually GIVEN, per view and version, as byte ranges: complete only when the
21	//                  ranges cover the whole. Stored evidence that never entered a prompt is not delivered; a citation
22	//                  of it is refused; a view delivered in part is an unresolved gap with its continuation.
23	//
24	// Must never: write anything; follow a path out of the repository; treat issue text as authority; present a count or
25	// a summary as the evidence; or hide an omission.
26	import fs from 'node:fs';
27	import path from 'node:path';
28	import {execFileSync} from 'node:child_process';
29	import {createHash} from 'node:crypto';
30	import {digest} from '../../packages/ledger/canonical.mjs';
31	import {statusHistory, MARKER} from './reconcile.mjs';
32	import {bundlesOf} from './evidence-recovery.mjs';
33	
34	export const DOSSIER_SCHEMA = 'ophanim.dossier/v1';
35	export const KINDS = Object.freeze(['authoritative-requirement', 'observation', 'derived', 'hypothesis']);
36	// rounds and requests bound the calls; result_bytes bounds one result and total_bytes one seat's whole investigation, both in UTF-8 BYTES of delivered record text.
37	// dossier_bytes bounds the whole initial view (the evidence text of all its entries).
38	export const DEFAULT_INVESTIGATION = Object.freeze({rounds: 3, requests_per_round: 6, result_bytes: 16_000, total_bytes: 160_000, dossier_bytes: 80_000});
39	export const OPS = Object.freeze(['file', 'list', 'grep', 'log', 'show', 'status', 'work', 'record', 'issue', 'output']);
40	
41	const sha = b => 'sha256:' + createHash('sha256').update(b).digest('hex');
42	const gitOf = repo => (args, opts = {}) => execFileSync('git', ['-C', repo, ...args], {encoding: 'utf8', maxBuffer: 64 << 20, stdio: ['ignore', 'pipe', 'pipe'], ...opts});
43	const tryGit = (G, args) => { try { return G(args); } catch { return null; } };
44	const under = (root, abs) => abs === root || abs.startsWith(root + path.sep);
45	/**
46	 * Containment on the ACTUAL target: the path must be inside `root` as written, and so must what it resolves to
47	 * (a symlink, or a path through a symlinked directory, to somewhere else is refused). Returns {abs} or {error, why}.
48	 */
49	export function contained(root, p) {
50	  if (typeof p !== 'string' || !p) return {error: 'BAD_REQUEST', why: 'a path is required'};
51	  const base = path.resolve(root), abs = path.resolve(base, p);
52	  if (!under(base, abs)) return {error: 'REFUSED', why: `${p} is outside the repository`};
53	  let real;
54	  try { real = fs.realpathSync(abs); } catch { return {error: 'NOT_FOUND', why: `${p} is not in the working tree`}; }
55	  if (!under(fs.realpathSync(base), real)) return {error: 'REFUSED', why: `${p} resolves to a target outside the repository (a link); it is not read`};
56	  return {abs: real};
57	}
