59	/**
60	 * A window of `text` in BYTES (UTF-8), never splitting a character: [from, to) of total. Every bounded delivery --
61	 * a dossier excerpt and a retrieval result alike -- is made here, so what was delivered is always a byte range of a
62	 * known whole.
63	 */
64	export function windowBytes(text, offset = 0, cap = Infinity) {
65	  const b = Buffer.from(text ?? '', 'utf8'), total = b.length;
66	  let from = Math.min(Math.max(0, Number.isFinite(offset) ? Math.floor(offset) : 0), total);
67	  while (from < total && (b[from] & 0xC0) === 0x80) from++;
68	  let to = Math.min(total, from + Math.max(0, Math.floor(cap)));
69	  while (to > from && to < total && (b[to] & 0xC0) === 0x80) to--;
70	  return {text: b.subarray(from, to).toString('utf8'), from, to, total};
71	}
