73	// --- the retriever ---------------------------------------------------------------------------------------------
74	/**
75	 * Read-only retrieval over the repository and the ledgers. `run(request, {cap})` never throws for a bad request: the
76	 * failure is the result ({ok: false, error}), so the model sees it.
77	 *
78	 * Every operation names a VIEW: a source (what it is, including any selection such as a match or a path) and a
79	 * version, whose whole body has a known size in bytes. A result is a byte window of that body, at most `cap` bytes
80	 * (default limits.result_bytes): coverage {unit: 'bytes', from, to, total, complete} and, when more remains,
81	 * `next`: the complete request that continues it. So any cut source -- a long history, a large record, a file that is
82	 * one line -- can be continued, and deliveries of the same view and version can be added up.
83	 */
84	export function makeRetriever({repo, statusRoot, work = null, issues = null, outputsDir = null, limits = {}}) {
