93	    file({path: p, start, lines}) {
94	      const c = contained(repo, p);
95	      if (c.error) return no(c.error, c.why);
96	      if (!fs.statSync(c.abs).isFile()) return no('NOT_FOUND', `${p} is not a file in the working tree`);
97	      // Evidence is the project's files: tracked, or untracked and not ignored. Git's own directory and anything
