105	      if (b.includes(0)) return no('BINARY', `${p} is binary (${b.length} bytes, ${sha(b)})`);
106	      const body = b.toString('utf8');
107	      // `start` (a line number) and `lines` are a convenience: they become a byte range of the same file body.
108	      let range = null;
109	      if (Number.isInteger(start) && start > 1 || Number.isInteger(lines)) {
110	        const all = body.split('\n'), from = Math.max(1, start ?? 1), to = Math.min(all.length, from + Math.max(1, lines ?? all.length) - 1);
