119	      return {source: `list:${prefix || '.'}`, version: sha(files.join('\n')), body: files.join('\n'), rows: files.length};
120	    },
121	    grep({pattern, path: p = '.'}) {
122	      if (typeof pattern !== 'string' || !pattern) return no('BAD_REQUEST', 'grep needs {pattern} (a fixed string)');
123	      if (contained(repo, p).error === 'REFUSED') return no('REFUSED', `${p} is outside the repository`);
124	      let out = '';
125	      try { out = G(['grep', '-n', '-I', '-F', '-e', pattern, '--', p]); } catch (e) { if (e.status !== 1) return no('GREP_FAILED', String(e.stderr ?? e.message).slice(0, 300)); }
