127	      // The search reads the working tree, so HEAD does not identify what it returned: the version is the body's own digest.
128	      return {source: `grep:${pattern}@${p}`, version: sha(rows.join('\n')), body: rows.join('\n') || '(no match)', rows: rows.length};
129	    },
130	    log({path: p = null, grep: g = null}) {
