151	    },
152	    work({item, match = null}) {
153	      if (!work) return no('UNAVAILABLE', 'there is no work ledger here');
154	      const all = work.stages(item).map(s => JSON.stringify({record: s.hash, stage: s.stage, attempt: s.attempt, status: s.status, next: s.next, blocker: s.blocker ?? null, findings: s.findings ?? []}));
155	      const rows = keep(all, match);
156	      return {source: `work:${item}#records${sel({match})}`, version: work.stages(item).at(-1)?.hash ?? null, body: rows.join('\n') || '(no stage recorded)', rows: rows.length, of: all.length};
157	    },
158	    record({hash}) {
159	      if (!work) return no('UNAVAILABLE', 'there is no work ledger here');
