161	      if (!s) return no('NOT_FOUND', `${hash} is not a stage record on the work ledger`);
162	      return {source: `record:${hash}`, version: hash, body: JSON.stringify({stage: s.stage, status: s.status, identity: s.identity, outputs: s.outputs, findings: s.findings, contributions: s.contributions}, null, 1)};
163	    },
164	    issue({number}) {
165	      if (!issues) return no('UNAVAILABLE', 'no issue snapshot was supplied to this run');
