173	      if (c.error) return no(c.error === 'REFUSED' ? 'REFUSED' : 'NOT_FOUND', `no stored output "${id}"`);
174	      const all = fs.readFileSync(c.abs, 'utf8');
175	      return {source: `output:${id}`, version: sha(all), body: all};
176	    },
177	  };
178	  /**
179	   * Window a view's body: at most `cap` bytes from `offset` (within the view's own range, when it has one). `tail`
180	   * takes the LAST `cap` bytes instead, starting on a whole row. An offset is a non-negative integer inside the body;
181	   * a window that cannot hold one character is refused, never returned empty.
182	   */
183	  const finish = (req, v, cap, tail) => {
184	    const total = Buffer.byteLength(v.body, 'utf8');
185	    const lo = v.range?.from ?? 0, hi = v.range?.to ?? total;
186	    let off = null;
187	    if (req.offset !== undefined && req.offset !== null) {
188	      off = typeof req.offset === 'string' && /^\d+$/.test(req.offset) ? Number(req.offset) : req.offset;
189	      if (!(Number.isSafeInteger(off) && off >= 0)) return no('BAD_REQUEST', `offset is a non-negative whole number of bytes, got ${JSON.stringify(req.offset)}`);
190	      if (off > total || (off === total && total > 0)) return no('OUT_OF_RANGE', `offset ${off} is past the end of ${v.source} (${total} bytes)`);
191	    }
192	    let start = Math.max(lo, off ?? lo);
193	    if (tail && off === null && hi - lo > cap) {
194	      const b = Buffer.from(v.body, 'utf8'), nl = b.indexOf(0x0A, hi - cap);
195	      start = nl !== -1 && nl + 1 < hi ? nl + 1 : hi - cap;
196	    }
197	    const w = windowBytes(v.body, start, Math.min(cap, Math.max(0, hi - start)));
