200	    const more = w.to < hi;
201	    // The continuation is a whole request: the same view, from the first byte not yet delivered.
202	    const {start: _s, lines: _l, offset: _o, ...rest} = req;
203	    const next = more ? {...(v.range && hi < w.total ? {...rest, ...(req.start !== undefined ? {start: req.start} : {}), ...(req.lines !== undefined ? {lines: req.lines} : {})} : rest), offset: w.to}
204	      : w.from > lo && tail ? {...rest, offset: 0} : null;
205	    const note = complete ? null : tail && w.from > lo ? `the most recent bytes ${w.from}-${w.to} of ${w.total}; bytes 0-${w.from} are earlier and retrievable with next`
