210	  };
211	  return {limits: L, run(req, {cap = L.result_bytes, tail = false} = {}) {
212	    if (!req || typeof req !== 'object' || !OPS.includes(req.op)) return no('BAD_REQUEST', `op is one of ${OPS.join(', ')}`);
