239	  // that does not fit at all is an omission, with the request that retrieves it.
240	  const LIM = R.limits;
241	  let spent = 0;
242	  const left = () => LIM.dossier_bytes - spent;
243	  const push = (kind, title, source, version, as_of, text, coverage, request = null) => {
244	    spent += Buffer.byteLength(text, 'utf8');
245	    entries.push({id: `S${entries.length + 1}`, kind, title, source, version, as_of, coverage, text, ...(request ? {request} : {})});
246	  };
247	  /** A small entry made here (a view of its own). `cap` bounds it; a cut list says so. The requirement is never cut. */
248	  const add = (kind, title, source, version, as_of, text, cap = 4000) => {
249	    const room = kind === 'authoritative-requirement' ? Infinity : Math.min(cap, left());
250	    if (room < 200) { omissions.push(`"${title.slice(0, 80)}" is NOT shown: the initial view's ${LIM.dossier_bytes}-byte budget is spent`); return; }
251	    const w = windowBytes(text, 0, room);
252	    push(kind, title, source, version, as_of, w.text, {complete: w.to === w.total, unit: 'bytes', from: 0, to: w.to, total: w.total,
253	      ...(w.to < w.total ? {note: `the first ${w.to} of ${w.total} bytes of this list; the rest is not in this view (use list, grep or status to see it)`} : {})});
254	  };
255	  /** An entry that IS a retrieval result: same source, version, byte window and continuation. Returns its bytes, or why not. */
