257	    const room = Math.min(cap, left());
258	    if (room < 200) { omissions.push(`"${title.slice(0, 80)}" is NOT shown: the initial view's ${LIM.dossier_bytes}-byte budget is spent; retrieve it with ${JSON.stringify(req)}`); return {error: 'BUDGET', why: 'the initial view\'s budget is spent'}; }
