338	  // `stable` leaves out the work ledger's own records, so recording an attempt does not itself look like new evidence.
339	  const outside = core.filter(e => !e.source.startsWith('work:')).map(({id, ...e}) => e);
340	  return {schema: DOSSIER_SCHEMA, item, head, entries, omissions, digest: 'sha256:' + digest({item, head, core, omissions}),
