344	const coverageLine = c => (!c || c.complete ? 'complete' : `PARTIAL (${c.note ?? `bytes ${c.from}-${c.to} of ${c.total}`})`) + (c?.next ? ` | next: ${JSON.stringify(c.next)}` : '');
345	/** The dossier as prompt text. A partial entry shows the request that continues it. */
346	export function renderDossier(d) {
347	  return [`## Evidence dossier for ${d.item} (an initial selection made by code, at ${d.head ? d.head.slice(0, 12) : 'no commit'}; it may be incomplete or wrong: challenge it)`,
348	    ...d.entries.map(e => `\n### [${e.id}] ${e.title}\nkind: ${e.kind} | source: ${e.source} | version: ${e.version ?? 'n/a'}${e.as_of ? ` | as of: ${e.as_of}` : ''} | coverage: ${coverageLine(e.coverage)}\n${e.text}`),
