352	export const RETRIEVAL_HELP = limits => [
353	  '## Retrieving more evidence',
354	  `Before you answer you may retrieve underlying records. Answer with ONLY {"requests": [...]} in a \`\`\`json block (at most ${limits.requests_per_round} per round, ${limits.rounds} round(s),`,
355	  `${limits.result_bytes} bytes per result and ${limits.total_bytes} bytes in all); the results come back and you are asked again.`,
356	  'Operations (all read-only): {"op":"file","path":P,"start":LINE?,"lines":N?} | {"op":"list","prefix":DIR?} | {"op":"grep","pattern":FIXED_STRING,"path":DIR?} |',
357	  ' {"op":"log","path":P?,"grep":TEXT?} | {"op":"show","commit":ID,"path":P?} | {"op":"status","item":ID,"match":TEXT?,"entry":HASH?} | {"op":"work","item":ID,"match":TEXT?} |',
358	  ' {"op":"record","hash":RECORD} | {"op":"issue","number":N} | {"op":"output","id":ID}. Any of them takes "offset": BYTE to continue a cut result.',
359	  'Each result states its source, version and coverage in bytes. A PARTIAL result or dossier entry gives "next": the request that continues it; "match" selects rows instead of',
360	  'paging through them. A missing source, an error, a cut or a request that did not fit the budget is shown as such: do not assume what you were not given.',
361	].join('\n');
