363	const merge = ranges => { const out = []; for (const [a, b] of [...ranges].sort((x, y) => x[0] - y[0])) { const l = out.at(-1); if (l && a <= l[1]) l[1] = Math.max(l[1], b); else out.push([a, b]); } return out; };
364	/**
365	 * What a seat was GIVEN, per evidence view: Map of ref -> {source, version, via, portions, total, complete, next}.
366	 * Identity is the view (its source, including any selection) AND its version: byte ranges are added up only within
367	 * one version, and a view is complete only when its ranges cover the whole. A complete delivery of one view says
368	 * nothing about another view of the same ledger or file. Dossier ids resolve to their entry's view.
369	 */
370	export function deliveryOf(dossier, log = null) {
371	  const views = new Map(), refs = new Map();
372	  const deliver = (how, source, version, c, request = null) => {
373	    if (!source) return null;
374	    let v = views.get(source);
375	    // Another version of the same view: what was delivered of the earlier one is not part of this one.
376	    if (!v || v.version !== version) { v = {source, version, via: new Set(v ? ['superseded'] : []), ranges: [], total: null, base: null, earlier: v ? [...(v.earlier ?? []), v.version] : []}; views.set(source, v); }
377	    v.via.add(how);
378	    // The request that names this view, without its window: the gap's continuation is built from it.
379	    const {offset: _o, start: _s, lines: _l, ...base} = request ?? c?.next ?? {};
380	    if (base.op) v.base = base;
381	    if (c && Number.isFinite(c.from) && Number.isFinite(c.to)) { v.ranges.push([c.from, c.to]); v.total = c.total; } else if (c?.complete !== false) { v.ranges.push([0, 0]); v.total = 0; }
382	    return v;
383	  };
384	  for (const e of dossier?.entries ?? []) { deliver('supplied', e.source, e.version, e.coverage, e.request ?? null); refs.set(e.id, e.source); }
385	  for (const r of log?.requests ?? []) if (r.ok) deliver('retrieved', r.source, r.version, r.coverage, r.request ?? null);
386	  const out = new Map();
387	  const view = v => {
388	    const portions = merge(v.ranges), complete = v.total !== null && portions.length === 1 && portions[0][0] === 0 && portions[0][1] >= v.total;
389	    const via = ['supplied', 'retrieved'].filter(x => v.via.has(x)).join('+');
390	    // The continuation starts at the first byte NOT delivered, computed from the ranges (never a remembered cut).
391	    const gap = !portions.length || portions[0][0] > 0 ? 0 : portions[0][1];
392	    return {source: v.source, version: v.version, via, portions, total: v.total, complete, next: complete || !v.base ? null : {...v.base, offset: gap}, ...(v.earlier.length ? {earlier_versions: v.earlier} : {})};
393	  };
394	  for (const v of views.values()) out.set(v.source, view(v));
395	  for (const [id, source] of refs) out.set(id, out.get(source));
396	  return out;
397	}
398	/** The views a seat was given only in part: what it has, and how the rest can be retrieved. Unresolved until it is. */
399	export const gapsOf = delivery => [...new Map([...delivery.values()].map(v => [v.source, v])).values()].filter(v => !v.complete)
400	  .map(v => ({source: v.source, version: v.version, delivered: v.portions, total: v.total, next: v.next}));
401	/** Normalize a citation: a dossier id, a `kind:ref` source, or a bare repository path. */
402	export const refOf = r => (typeof r === 'string' && !/^S\d+$/.test(r) && !/^[a-z]+:/.test(r) ? `file:${r}` : r);
403	
404	const jsonOf = text => {
405	  const fenced = /```json\s*([\s\S]*?)```/.exec(text ?? '');
406	  for (const c of [fenced?.[1], text]) { if (!c) continue; try { const j = JSON.parse(c.trim()); if (j && typeof j === 'object') return j; } catch { /* next */ } }
407	  return null;
408	};
