410	/**
411	 * Run one seat's judgment with retrieval. `ask(prompt)` makes one provider call and returns {text, ...}. The model
412	 * either answers, or asks for records ({"requests": [...]}, with no verdict or plan beside it); results are appended
413	 * and it is asked again. Returns {reply, prompt (the last one), log: {rounds, calls, requests, bytes, limit_reached}}.
414	 */
415	export async function investigate({ask, prompt, retriever, limits = {}, canAsk = () => true}) {
416	  const L = {...retriever.limits, ...limits};
417	  const log = {rounds: 0, calls: 0, requests: [], bytes: 0, limit_reached: null};
418	  let current = prompt, reply = null;
419	  for (;;) {
420	    reply = await ask(current);
421	    log.calls++;
422	    const j = jsonOf(reply?.text);
423	    const asks = j && Array.isArray(j.requests) && !('verdict' in j) && !('problem' in j) ? j.requests : null;
424	    if (!asks) return {reply, prompt: current, log};
425	    const round = log.rounds + 1;
426	    const out = of => `${current}\n\n## Retrieved (round ${round})\n${of}`;
427	    if (log.rounds >= L.rounds || log.bytes >= L.total_bytes || !canAsk()) {
428	      // Told once already and it asked again: no judgment was given within the bounds.
429	      if (log.limit_reached) return {reply: null, prompt: current, log};
430	      log.limit_reached = log.rounds >= L.rounds ? `the ${L.rounds}-round investigation limit` : log.bytes >= L.total_bytes ? `the ${L.total_bytes}-byte retrieval limit` : 'the stage\'s provider-call budget';
431	      if (!canAsk()) return {reply: null, prompt: current, log};
432	      for (const req of asks) log.requests.push({round, request: req, ok: false, error: 'NOT_RUN', why: log.limit_reached});
433	      current = out(`NOTHING WAS RETRIEVED: ${log.limit_reached} is reached. ${asks.length} request(s) were not run: ${JSON.stringify(asks).slice(0, 600)}\n`
434	        + 'Answer now with what you have. State what you could not see (context.gaps for a plan; a finding or reason otherwise); do not assume its content.');
435	      log.rounds++;
436	      continue;
437	    }
438	    log.rounds++;
439	    const parts = [];
440	    for (const [i, req] of asks.entries()) {
441	      if (i >= L.requests_per_round) { parts.push(`- request ${i + 1} NOT RUN: at most ${L.requests_per_round} requests per round`); log.requests.push({round: log.rounds, request: req, ok: false, error: 'OVER_ROUND_LIMIT'}); continue; }
442	      // The total is enforced BEFORE the result enters the prompt: a result is cut to what is left, and when nothing
443	      // is left the request is not run. Both are recorded, with how to continue.
444	      const left = L.total_bytes - log.bytes;
445	      if (left < 4) {   // fewer bytes than one UTF-8 character may need: nothing more can be delivered
446	        log.requests.push({round: log.rounds, request: req, ok: false, error: 'OVER_TOTAL_BUDGET', why: `the ${L.total_bytes}-byte retrieval budget is spent`});
447	        parts.push(`### ${JSON.stringify(req)}\nNOT RUN: the ${L.total_bytes}-byte retrieval budget of this investigation is spent. This record was NOT delivered; it remains retrievable in a later investigation.`);
448	        continue;
449	      }
450	      const r = retriever.run(req, {cap: Math.min(L.result_bytes, left)});
451	      log.bytes += r.ok ? r.bytes : 0;
452	      log.requests.push({round: log.rounds, request: req, ok: r.ok, ...(r.ok ? {source: r.source, version: r.version, coverage: r.coverage, bytes: r.bytes, sha256: sha(r.text)} : {error: r.error, why: r.why})});
453	      parts.push(r.ok ? `### ${JSON.stringify(req)}\nsource: ${r.source} | version: ${r.version ?? 'n/a'} | coverage: ${coverageLine(r.coverage)}\n${r.text}`
454	        : `### ${JSON.stringify(req)}\nRETRIEVAL FAILED: ${r.error} -- ${r.why}. This record was NOT delivered.`);
455	    }
456	    current = out(parts.join('\n\n'));
457	  }
458	}
