1	// AUTOMATIC EVIDENCE RECOVERY for items the status ledger records as Resolved without completion evidence (an
2	// attested basis only: the `evidence-gap` gate). The status ledger stays the owner's: this module never signs, never
3	// appends to it, and never writes to a run or review-cycle ledger. What it does:
4	//
5	//   1. Finds every retained run of the item: evidence bundles (<board>/operating/evidence.json, as Pantheon's board
6	//      and this lifecycle's outcome stage write them) under the retained-runs directory, and the bundles the work
7	//      ledger's own outcome stages recorded.
8	//   2. For each, decides whether it is completion evidence for the item's CURRENT Resolved status:
9	//        - the bundle is the item's and carries a proposal (made when its three-lab review cycle closed);
10	//        - that proposal is well formed, proposes Resolved, and was made against a status of this item whose
11	//          requirement (title and Ready basis) is still the item's requirement;
12	//        - rebuilt against the current Resolved entry, it passes the status ledger's own proposal rules (bound to the
13	//          item's ticket, a verified close by three labs) and the STRUCTURAL check of everything it cites (run ledger,
14	//          review-cycle ledger, run.json, the ticket bytes), as `apply` will re-check them;
15	//        - its commit exists in this repository (whether it is reachable from HEAD is reported, not assumed).
16	//   3. Writes the first applicable one as an UNSIGNED proposal for the owner, and records the attempt -- every source
17	//      searched with its result -- on the work ledger (work.recovery). An item with nothing applicable is recorded as
18	//      `not-found`, with what was searched; it is searched again only when its sources or its status change.
19	//
20	// The owner applies a recovered proposal with `node packages/ledger/status.mjs apply <file>` (their keys); a
21	// Resolved item with nothing recoverable is re-verified only if the owner records it Ready again, which puts it
22	// through the lifecycle. Must never: treat a basis, a label, a green CI run or an open review as evidence; widen a
23	// proposal's claims; or record a status.
24	import fs from 'node:fs';
25	import path from 'node:path';
26	import {execFileSync} from 'node:child_process';
27	import {createHash} from 'node:crypto';
28	import {propose, proposalRefusal, proposalDigest, checkEvidenceLedgers} from '../../packages/ledger/status.mjs';
29	import {digest} from '../../packages/ledger/canonical.mjs';
30	import {requirementOf, requirementDigest} from './gates.mjs';
31	import {statusHistory} from './reconcile.mjs';
32	
33	const sha = bytes => 'sha256:' + createHash('sha256').update(bytes).digest('hex');
34	const fileSha = f => (fs.existsSync(f) ? sha(fs.readFileSync(f)) : null);
35	const readJson = f => { try { return JSON.parse(fs.readFileSync(f, 'utf8')); } catch { return null; } };
36	
37	/** Every evidence bundle of `item`: under `bundlesDir`, and the ones the work ledger's outcome stages recorded. */
38	export function bundlesOf({item, bundlesDir = null, work = null}) {
39	  const out = [];
40	  const walk = (dir, origin) => {
41	    if (!dir || !fs.existsSync(dir)) return;
42	    for (const e of fs.readdirSync(dir, {withFileTypes: true}).sort((a, b) => a.name.localeCompare(b.name))) {
43	      const p = path.join(dir, e.name);
44	      if (e.isDirectory()) walk(p, origin);
45	      else if (e.name === 'evidence.json' && readJson(p)?.item === item) out.push({dir: path.dirname(p), origin, ref: `${origin}:${path.relative(origin === 'retained' ? bundlesDir : dir, path.dirname(p)) || '.'}`});
46	    }
47	  };
48	  walk(bundlesDir, 'retained');
49	  for (const s of work ? work.stages(item).filter(x => x.stage === 'outcome' && x.outputs?.bundle) : []) {
50	    if (!out.some(b => path.resolve(b.dir) === path.resolve(s.outputs.bundle))) out.push({dir: s.outputs.bundle, origin: 'work', ref: `work:${s.hash}`});
51	  }
52	  return out;
53	}
54	
55	/**
56	 * The digest of what a recovery searches and re-checks: each bundle's evidence and proposal bytes, the bytes its
57	 * proposal cites (run.json, the run and cycle ledger chains), and the item's ticket. A change to any of them makes
58	 * the item due for another search; nothing else does.
59	 */
60	export function sourcesDigest({repo, item, bundles}) {
61	  const cited = dir => {
62	    const loc = readJson(path.join(dir, 'proposal.json'))?.locations ?? {};
63	    const chain = d => (typeof d === 'string' ? fileSha(path.join(d, 'chain.jsonl')) : null);
64	    return {run_json: typeof loc.run_json === 'string' ? fileSha(loc.run_json) : null, run_ledger: chain(loc.run_ledger), cycle_ledger: chain(loc.cycle_ledger)};
65	  };
66	  return 'sha256:' + digest({ticket: fileSha(path.join(repo, 'tickets', `${item}.json`)),
67	    bundles: bundles.map(b => ({ref: b.ref, evidence: fileSha(path.join(b.dir, 'evidence.json')), proposal: fileSha(path.join(b.dir, 'proposal.json')), cited: cited(b.dir)}))
68	      .sort((a, b) => a.ref.localeCompare(b.ref))});
69	}
70	
71	const commitIn = (repo, commit) => {
72	  try { execFileSync('git', ['-C', repo, 'cat-file', '-e', `${commit}^{commit}`], {stdio: 'ignore'}); } catch { return {present: false, in_head: false}; }
73	  try { execFileSync('git', ['-C', repo, 'merge-base', '--is-ancestor', commit, 'HEAD'], {stdio: 'ignore'}); return {present: true, in_head: true}; }
74	  catch { return {present: true, in_head: false}; }
75	};
