77	/** Whether one bundle is completion evidence for the item's current status; the rebuilt proposal when it is. */
78	function examine({repo, board, history, current, bundle, checked}) {
79	  const row = (result, why, extra = {}) => ({source: bundle.origin, ref: bundle.ref, result, why, ...extra});
80	  const old = readJson(path.join(bundle.dir, 'proposal.json'));
81	  if (!old) {
82	    const b = readJson(path.join(bundle.dir, 'evidence.json'));
83	    return row('not-evidence', `no proposal: the run ${b?.run?.shipped ? 'shipped' : 'did not ship'} and its review is ${b?.review?.close ? 'closed' : b?.review ? 'open' : 'absent'}; only a closed review's proposal is completion evidence`);
84	  }
85	  const malformed = proposalRefusal(old);
86	  if (malformed) return row('refused', `its proposal is malformed: ${malformed}`);
87	  if (old.item !== current.item) return row('refused', `its proposal is for "${old.item}"`);
88	  if (old.to.state !== 'Resolved') return row('not-evidence', `its proposal proposes ${old.to.state}, not Resolved`);
89	  // The requirement it was made against must still be the item's requirement.
90	  const upTo = history.findIndex(s => s.entry === old.from.entry);
91	  if (upTo < 0) return row('refused', 'its proposal was made against a status that is not in this item\'s history');
92	  const then = requirementOf(history.slice(0, upTo + 1)), now = requirementOf(history);
93	  if (requirementDigest(then) !== requirementDigest(now)) return row('stale', 'the item\'s requirement changed after that run (title or Ready basis)');
94	  let p;
95	  try {
96	    p = propose(board, {item: current.item, to: {state: 'Resolved', basis: `Completion evidence recovered from a retained run (${bundle.ref}): ${old.to.basis}`.slice(0, 2000), checked},
97	      evidence: old.evidence, ...(old.accept_unverified_reason ? {accept_unverified_reason: old.accept_unverified_reason} : {}), locations: old.locations});
98	  } catch (e) { return row('refused', e.message); }
99	  let checks;
100	  try { checks = checkEvidenceLedgers(p); } catch (e) { return row('refused', `the cited evidence does not re-check: ${e.message}`); }
101	  if (checks.checked !== 'structural') {
102	    const missing = Object.entries(checks).filter(([k, v]) => k !== 'checked' && !v).map(([k]) => k);
103	    return row('unverifiable-here', `not everything it cites is on this machine to re-check (${missing.join(', ')})`);
104	  }
105	  const c = commitIn(repo, p.evidence.commit);
106	  if (!c.present) return row('refused', `its commit ${p.evidence.commit.slice(0, 12)} is not in this repository`);
107	  return row('recovered', `a verified three-lab review of ${p.evidence.commit.slice(0, 12)} bound to tickets/${current.item}.json, re-checked structurally`,
108	    {commit: p.evidence.commit, in_head: c.in_head, proposal: p});
109	}
110	
111	/**
112	 * Search, decide and (when evidence applies) write the unsigned proposal. Pure of ledger writes: the caller records
113	 * the result with work.recordRecovery. Returns {item, status_entry, sources, outcome, searched, proposal?}.
114	 */
115	export function recoverEvidence({repo, statusRoot, item, bundlesDir = null, work = null, outDir, now = Date.now()}) {
116	  const {board, byItem} = statusHistory(statusRoot);
117	  const current = board.items.find(i => i.item === item);
118	  if (!current) throw new Error(`"${item}" is not on the status board`);
119	  if (current.state !== 'Resolved') throw new Error(`"${item}" is ${current.state}: evidence recovery is for Resolved items`);
120	  const history = byItem.get(item) ?? [];
121	  const bundles = bundlesOf({item, bundlesDir, work});
122	  const sources = sourcesDigest({repo, item, bundles});
123	  const checked = new Date(now).toISOString().slice(0, 10);
124	  const searched = bundles.map(bundle => examine({repo, board, history, current, bundle, checked}));
125	  if (!bundlesDir) searched.push({source: 'retained', ref: 'retained', result: 'not-searched', why: 'no retained-runs directory was given (--bundles)'});
126	  else if (!bundles.some(b => b.origin === 'retained')) searched.push({source: 'retained', ref: 'retained', result: 'none', why: 'no evidence bundle of the item in the retained runs'});
127	  if (!bundles.some(b => b.origin === 'work')) searched.push({source: 'work', ref: 'work', result: 'none', why: 'no outcome of the item on the work ledger'});
128	  const hit = searched.find(r => r.result === 'recovered');
129	  const base = {item, status_entry: current.entry, sources, searched: searched.map(({proposal, ...r}) => r)};
130	  if (!hit) return {...base, outcome: 'not-found'};
131	  const file = path.join(outDir, item, `proposal-${proposalDigest(hit.proposal).slice(7, 19)}.json`);
132	  fs.mkdirSync(path.dirname(file), {recursive: true});
133	  fs.writeFileSync(file, JSON.stringify(hit.proposal, null, 2) + '\n');
134	  return {...base, outcome: 'recovered', proposal: {digest: proposalDigest(hit.proposal), file, commit: hit.commit, in_head: hit.in_head}};
135	}
