57	const HERE = path.dirname(fileURLToPath(import.meta.url));
58	export const REPO_ROOT = path.resolve(HERE, '../..');
59	const refuse = (why, code = 'REFUSED') => { throw Object.assign(new Error(why), {code}); };
60	const usage = why => { throw Object.assign(new Error(why), {usage: true}); };
