62	const BOOLEAN = new Set(['json', 'github', 'once', 'init']);
63	export function parseArgs(argv) {
64	  const [first, ...rest] = argv;
65	  if (!first || first.startsWith('--')) usage('a verb is required: reconcile, tick, watch, serve, context, reassess or report');
66	  const opts = {}, pos = [];
67	  for (let i = 0; i < rest.length; i++) {
68	    if (!rest[i].startsWith('--')) { pos.push(rest[i]); continue; }
69	    const k = rest[i].slice(2);
70	    if (BOOLEAN.has(k)) opts[k] = true;
71	    else if (i + 1 >= rest.length) usage(`--${k} needs a value`);
72	    else opts[k] = rest[++i];
73	  }
74	  return {verb: first, opts, pos};
75	}
