87	/** The work ledger, verified against its ANCHOR, or null when there is none. Never creates one. */
88	export function openWorkReadOnly(workRoot) {
89	  if (!fs.existsSync(path.join(workRoot, 'ANCHOR'))) return {work: null, ledger: {state: 'absent', root: workRoot}};
90	  const work = openWorkLedger({root: workRoot, create: false});      // throws unless it verifies in full
91	  const v = work.verify();
92	  return {work, ledger: {state: 'verified', root: workRoot, anchor: work.anchor, head: v.head, entries: v.entries}};
93	}
