95	/** Whether this machine holds the controller's keys (an operator and the orderer of the work ledger). */
96	// `keys` is reported relative to the repository (`shown`), so a report or projection never carries a machine path.
97	export function authorityOf(work, workRoot, repo = null) {
98	  const keys = path.join(workRoot, 'keys');
99	  const shown = repo ? (path.relative(repo, keys) || keys) : keys;
100	  if (!work) return {held: false, keys: shown, why: 'there is no work ledger here'};
101	  const auth = work.ledger.verify().authority;
102	  const has = id => fs.existsSync(path.join(keys, encodeURIComponent(id) + '.json'));
103	  const op = auth.operators.find(has);
104	  if (!op || !has(auth.orderer)) {
105	    return {held: false, keys: shown, why: `no controller key is held at ${shown} (operator ${auth.operators.join('|')}, orderer ${auth.orderer}): the work ledger can be verified, not changed`};
106	  }
107	  return {held: true, keys: shown, operator: op};
108	}
