110	/** The NO_AUTHORITY block: what is missing, who supplies it, and when the run resumes. */
111	export const noAuthority = (auth, ledger) => ({
112	  blocked: 'NO_AUTHORITY', what: auth.why, role: 'decision-authority',
113	  resume_when: 'run on the machine that holds the controller key (status/work/keys), or the owner provisions one there',
114	  verified: ledger.state === 'verified' ? {anchor: ledger.anchor, head: ledger.head, entries: ledger.entries} : ledger.state,
115	  recorded: 'nothing', dispatched: 'nothing',
116	});
