118	/** Issues from --issues FILE or --github, with a label naming where they came from; null with neither. */
119	export async function loadIssues(opts, {fetchImpl, env = process.env} = {}) {
120	  if (opts.issues && opts.github) usage('pass --issues FILE or --github, not both');
121	  if (opts.issues) return {issues: readIssuesFile(path.resolve(opts.issues)), source: opts['issues-label'] ?? `snapshot file ${opts.issues}`};
122	  if (opts.github) {
123	    return {issues: await fetchIssues({repo: env.GITHUB_REPOSITORY ?? null, token: env.GITHUB_TOKEN ?? null, fetchImpl}),
124	      source: opts['issues-label'] ?? `GitHub issues of ${env.GITHUB_REPOSITORY}, read at run time`};
125	  }
