129	/**
130	 * The full reconciliation view, read-only: the core's reconcile plus what only the issue snapshot shows (markers
131	 * naming no ledger item, open/closed drift), the work ledger's state and the authority held here.
132	 */
133	export function reconcileView({repo, statusRoot, workRoot, bundlesDir = null, issues = null, issuesSource = null, now = Date.now()}) {
134	  const {work, ledger} = openWorkReadOnly(workRoot);
135	  const rec = reconcile({repo, statusRoot, workLedger: work, issues, bundlesDir, now});
136	  const onBoard = new Map(rec.items.map(i => [i.item, i]));
137	  const unknownMarkers = [], drift = [];
138	  for (const issue of issues ?? []) {
139	    const id = MARKER.exec(issue.body ?? '')?.[1];
140	    if (!id) continue;
141	    const it = onBoard.get(id);
142	    if (!it) { unknownMarkers.push({number: issue.number, item: id, why: 'the issue carries the marker of an item that is not on the status ledger'}); continue; }
143	    const want = it.status === 'Resolved' ? 'closed' : 'open';
144	    if (issue.state !== want) drift.push({number: issue.number, item: id, status: it.status, issue_state: issue.state, want});
145	  }
146	  const byStatus = {};
147	  for (const i of rec.items) byStatus[i.status] = (byStatus[i.status] ?? 0) + 1;
148	  return {...rec, work: {...ledger, root: path.relative(repo, workRoot) || workRoot}, authority: authorityOf(work, workRoot, repo),
149	    status: {root: path.relative(repo, statusRoot) || statusRoot}, issues_source: issuesSource, unknown_markers: unknownMarkers, drift,
150	    counts: {...rec.counts, duplicates: rec.duplicates.length, unknown_markers: unknownMarkers.length, drift: drift.length, by_status: byStatus}};
151	}
