153	// Gates in lifecycle order, then the waiting and terminal ones; with what each means.
154	export const GATE_ORDER = ['claimed', ...STAGES, 'awaiting-owner', 'blocked', 'reverification-needed', 'evidence-gap', 'complete'];
155	const GATE_MEANS = {
156	  claimed: 'a stage is claimed under a live lease: in progress, not dispatched twice',
157	  plan: 'evaluation and planning: author a ticket from the requirement, or re-check the existing one',
158	  implement: 'the approved plan is reused; implementation is next',
159	  review: 'implementation passed; the coordinated three-lab cycle review is next',
160	  validate: 'review passed; validation against the original requirement is next',
161	  outcome: 'validation passed; the unsigned status transition is next',
162	  'awaiting-owner': 'the outcome is recorded; only the owner signs the status transition',
163	  blocked: 'waits on something outside the work or on an unresolved dependency; never dispatched',
164	  'evidence-gap': 'Resolved on the ledger without completion evidence bound to a ticket, a commit and a three-lab verified review',
165	  'reverification-needed': 'Resolved with evidence, but a reassessment disqualified the review it rests on: the owner decides; the status is not changed',
166	  complete: 'Resolved with completion evidence',
167	};
168	const cell = s => String(s ?? '').replace(/\|/g, '\\|').replace(/\r?\n/g, ' ');
169	const issueRefs = (nums, byNumber) => (nums.length ? nums.map(n => `#${n}${byNumber.get(n) ? ` (${byNumber.get(n).state})` : ''}`).join(', ') : '—');
170	const gatesPresent = counts => [...GATE_ORDER, ...Object.keys(counts).filter(g => !GATE_ORDER.includes(g)).sort()].filter(g => counts[g]);
171	
172	/** The reconciliation as plain text (the `reconcile` verb). */
173	export function reconcileText(v) {
174	  const out = [];
175	  out.push(`status ledger ${v.status.root}: head ${v.ledger.head}, ${v.ledger.entries} entries, ${v.counts.items} items (verified)`);
176	  out.push(v.work.state === 'verified' ? `work ledger ${v.work.root}: anchor ${v.work.anchor}, ${v.work.entries} entries (verified)` : `work ledger ${v.work.root}: absent`);
177	  out.push(v.authority.held ? `controller authority: held (${v.authority.operator})` : `controller authority: NO_AUTHORITY -- ${v.authority.why} (reconcile needs none)`);
178	  out.push(`issues: ${v.issues_source ?? 'not read'}${v.counts.issues ? ` (${v.counts.issues})` : ''}`);
179	  out.push(`by gate: ${gatesPresent(v.counts.by_gate).map(g => `${g} ${v.counts.by_gate[g]}`).join(', ')}`);
180	  out.push(`counts: ${Object.entries(v.counts).filter(([, n]) => typeof n === 'number').map(([k, n]) => `${k} ${n}`).join(', ')}`);
181	  for (const g of gatesPresent(v.counts.by_gate)) {
182	    out.push('', `[${g}] ${GATE_MEANS[g] ?? ''}`);
183	    for (const i of v.items.filter(x => x.gate.gate === g)) {
184	      const b = i.gate.blocker;
185	      out.push(`  ${i.item} (${i.status})${i.issues.length ? ` issues ${i.issues.map(n => `#${n}`).join(',')}` : ''}${i.ticket ? ` ticket ${i.ticket.path ?? 'INVALID'}` : ''}: ${i.gate.reason ?? ''}`
186	        + (b && g !== 'evidence-gap' ? ` | role ${b.role}; resumes when ${b.resume_when}` : ''));
187	    }
188	  }
189	  if (v.candidates.length) out.push('', '[intake candidates] recorded, never executed', ...v.candidates.map(c => `  #${c.number} (${c.state}) ${c.title}`));
190	  if (v.orphans.length) out.push('', '[orphans]', ...v.orphans.map(o => `  ${o.ticket}: ${o.why}`));
191	  if (v.duplicates.length) out.push('', '[duplicate markers]', ...v.duplicates.map(d => `  ${d.item}: issues ${d.issues.map(n => `#${n}`).join(', ')}`));
192	  if (v.unknown_markers.length) out.push('', '[markers naming no ledger item]', ...v.unknown_markers.map(u => `  #${u.number}: ${u.item}`));
193	  if (v.drift.length) out.push('', '[projection drift]', ...v.drift.map(d => `  #${d.number} ${d.item}: ${d.status} on the ledger, issue ${d.issue_state}`));
194	  return out.join('\n');
195	}
