197	/** The backlog reconciliation as Markdown (the `report` verb). Everything in it is read from the view. */
198	export function backlogMarkdown(v, {command = 'node ophanim/operate/cli.mjs report', at = v.at} = {}) {
199	  const byNumber = new Map((v.issues_list ?? []).map(i => [i.number, i]));
200	  const L = [];
201	  L.push('# Backlog reconciliation', '');
202	  L.push(`Generated by \`${command}\` at ${at}. Generated, not edited: regenerate it. Every count below is read from the ledgers, the tickets and the issue snapshot named here; none is assumed.`, '');
203	  L.push('## Sources', '');
204	  L.push(`- **Status ledger** (\`${v.status.root}\`, authoritative): verified in full; head \`${v.ledger.head}\`, ${v.ledger.entries} entries, ${v.counts.items} items.`);
205	  L.push(v.work.state === 'verified'
206	    ? `- **Work ledger** (\`${v.work.root}\`): verified against its anchor \`${v.work.anchor}\`; ${v.work.entries} entries.`
207	    : `- **Work ledger** (\`${v.work.root}\`): absent. No stage has been claimed, run or paid for; every gate below is computed from the status ledger, the tickets and the evidence bytes alone.`);
208	  L.push(v.authority.held ? `- **Controller authority:** held here (\`${v.authority.operator}\`).`
209	    : `- **Controller authority:** NO_AUTHORITY here (${cell(v.authority.why)}). Reconciliation needs none; dispatch (\`tick\`/\`watch\`) stops with this block until it runs where the controller key is.`);
210	  L.push(`- **Issues:** ${cell(v.issues_source ?? 'not read')}; ${v.counts.issues} issue(s), ${v.counts.linked_issues} linked to an item by marker, ${v.counts.candidates} candidate(s). Issue text is data, never authority.`);
211	  L.push(`- **Tickets:** ${v.counts.tickets} under \`tickets/\`. **Retained runs:** ${v.bundles ? `evidence bundles under \`${v.bundles}\`` : 'no bundles directory given'}; ${v.counts.items_with_runs} item(s) with runs.`);
212	  L.push('');
213	  L.push('## Counts', '', '| Earliest unmet gate | Items | Meaning |', '|---|---|---|');
214	  for (const g of gatesPresent(v.counts.by_gate)) L.push(`| \`${g}\` | ${v.counts.by_gate[g]} | ${GATE_MEANS[g] ?? ''} |`);
215	  L.push(`| **total** | **${v.counts.items}** | |`, '');
216	  L.push(`By status on the ledger: ${Object.entries(v.counts.by_status).sort().map(([s, n]) => `${s} ${n}`).join(', ')}.`, '');
217	  L.push('| Count | Value |', '|---|---|');
218	  for (const k of ['items', 'issues', 'linked_issues', 'candidates', 'tickets', 'orphans', 'duplicates', 'unknown_markers', 'drift', 'items_with_runs']) L.push(`| ${k} | ${v.counts[k]} |`);
219	  L.push('');
220	  L.push('## Items by earliest unmet gate', '');
221	  for (const g of gatesPresent(v.counts.by_gate)) {
222	    const items = v.items.filter(i => i.gate.gate === g);
223	    L.push(`### \`${g}\` (${items.length})`, '', GATE_MEANS[g] ?? '', '');
224	    if (g === 'evidence-gap') {
225	      L.push('| Item | Ticket | Issue(s) | Runs | Evidence gap | Responsible role | Resumes when |', '|---|---|---|---|---|---|---|');
226	    } else L.push('| Item | Status | Ticket | Issue(s) | Runs | Reason | Blocker | Responsible role | Resumes when |', '|---|---|---|---|---|---|---|---|---|');
227	    for (const i of items) {
228	      const b = i.gate.blocker ?? null;
229	      const ticket = i.ticket ? (i.ticket.path ? `\`${i.ticket.path}\`` : `invalid: ${cell(i.ticket.invalid)}`) : 'none';
230	      const runs = i.runs.length ? `${i.runs.length} (${i.runs.map(r => `${r.shipped ? 'shipped' : 'not shipped'}${r.review ? `, review ${r.review.outcome ?? r.review.status}` : ''}`).join('; ')})` : 'none';
231	      const reason = `${cell(i.gate.reason)}${i.gate.mode ? ` (mode \`${i.gate.mode}\`)` : ''}`;
232	      if (g === 'evidence-gap') L.push(`| \`${i.item}\` ${cell(i.title)} | ${ticket} | ${issueRefs(i.issues, byNumber)} | ${runs} | ${cell(b?.what ?? i.gate.reason)} | \`${cell(b?.role ?? '')}\` | ${cell(b?.resume_when ?? '')} |`);
233	      else L.push(`| \`${i.item}\` ${cell(i.title)} | ${i.status} | ${ticket} | ${issueRefs(i.issues, byNumber)} | ${runs} | ${reason} | ${b ? (b.what === i.gate.reason ? 'as the reason' : cell(b.what)) : '—'} | ${b ? `\`${cell(b.role)}\`` : '—'} | ${b ? cell(b.resume_when) : '—'} |`);
234	    }
235	    L.push('');
236	  }
237	  L.push('## Intake candidates', '');
238	  if (!v.candidates.length) L.push('None.', '');
239	  else {
240	    L.push('Issues that carry no item marker. Each is recorded by the scheduler as `work.intake` with classification `candidate` and is never executed; only the owner turns one into a status item (or classifies it as coordination). What the issue says is not read as an instruction.', '');
241	    L.push('| Issue | State | Title | Classification | Why |', '|---|---|---|---|---|');
242	    for (const c of v.candidates) L.push(`| #${c.number} | ${c.state} | ${cell(c.title)} | candidate | ${cell(c.why)} |`);
243	    L.push('');
244	  }
245	  L.push('## Orphans, duplicates and drift', '');
246	  L.push(`- **Orphan tickets** (a ticket for an item not on the status ledger): ${v.orphans.length ? v.orphans.map(o => `\`${o.ticket}\``).join(', ') : 'none'}.`);
247	  L.push(`- **Duplicate markers** (two issues for one item): ${v.duplicates.length ? v.duplicates.map(d => `\`${d.item}\` on ${d.issues.map(n => `#${n}`).join(', ')}`).join('; ') : 'none'}.`);
248	  L.push(`- **Markers naming no ledger item:** ${v.unknown_markers.length ? v.unknown_markers.map(u => `#${u.number} (\`${u.item}\`)`).join(', ') : 'none'}.`);
249	  L.push(`- **Projection drift** (issue open/closed against the item's state): ${v.drift.length ? v.drift.map(d => `#${d.number} \`${d.item}\` is ${d.status} but the issue is ${d.issue_state}`).join('; ') : 'none'}.`);
250	  L.push(`- **Items with no linked issue:** ${v.issues_list ? (v.items.filter(i => !i.issues.length).map(i => `\`${i.item}\``).join(', ') || 'none') : 'not checked (no issues read)'}.`);
251	  L.push('');
252	  L.push('## What this does not show', '');
253	  L.push('- A gate is what the ledgers and the checkout support today, not a judgement of the work: an `evidence-gap` item may well be done; the ledger does not carry the completion evidence (ticket, commit, three-lab verified review) that would show it.');
254	  L.push('- No provider was called and nothing was dispatched or recorded to produce this report.');
255	  L.push('- Issue state and text come from the snapshot named under Sources; issues opened or edited since are not in it.');
256	  L.push('');
257	  return L.join('\n');
258	}
