260	/** Scheduler limits from flags; --total-provider-calls defaults to 0 (nothing that may call a provider runs). */
261	export function limitsOf(opts) {
262	  const flags = {'total-provider-calls': 'total_provider_calls', 'stage-provider-calls': 'stage_provider_calls', iterations: 'iterations',
263	    concurrency: 'concurrency', 'elapsed-ms': 'elapsed_ms', 'lease-ms': 'lease_ms', 'stage-attempts': 'stage_attempts'};
264	  const out = {total_provider_calls: 0};
265	  for (const [flag, key] of Object.entries(flags)) {
266	    if (opts[flag] === undefined) continue;
267	    if (!/^\d+$/.test(opts[flag])) usage(`--${flag} is a non-negative integer`);
268	    out[key] = Number(opts[flag]);
269	  }
270	  if (out.concurrency === 0) usage('--concurrency is at least 1');
