330	export async function main(argv = process.argv.slice(2), {log = console.log, err = console.error, env = process.env, fetchImpl, stagesFile} = {}) {
331	  try {
332	    const {verb, opts} = parseArgs(argv);
333	    const paths = pathsOf({opts, env});
334	    if (verb === 'reconcile' || verb === 'report') {
