336	      const {issues, source} = await loadIssues(opts, {fetchImpl, env});
337	      const v = {...reconcileView({...paths, issues, issuesSource: source}), issues_list: issues, bundles: paths.bundlesDir ? path.relative(paths.repo, paths.bundlesDir) : null};
338	      if (verb === 'reconcile') { log(opts.json ? JSON.stringify(v, null, 2) : reconcileText(v)); return 0; }
339	      const out = path.resolve(opts.out), json = out.replace(/\.md$/, '') + '.json';
340	      fs.mkdirSync(path.dirname(out), {recursive: true});
341	      // The command as run, with the issues file named by its basename (a local path means nothing to a reader).
342	      const shown = argv.map((a, i) => (argv[i - 1] === '--issues' ? path.basename(a) : argv[i - 1] === '--out' ? path.relative(paths.repo, out) : a));
