344	      // The JSON keeps each issue's number, title, state and labels, not its body (the body is data, and large).
345	      fs.writeFileSync(json, JSON.stringify({...v, issues_list: issues?.map(({body, ...rest}) => rest) ?? null}, null, 2) + '\n');
346	      log(`${path.relative(process.cwd(), out)}\n${path.relative(process.cwd(), json)}`);
347	      return 0;
348	    }
349	    if (verb === 'tick' || verb === 'watch') {
350	      const limits = limitsOf(opts);
351	      const progress = e => err(JSON.stringify(e));
352	      const prep = await prepareDispatch({paths, opts, limits, stagesFile, progress});
353	      if (prep.blocked) { log(JSON.stringify(prep.blocked, null, 2)); return 3; }
354	      const holder = opts.holder ?? 'controller';
355	      if (opts.item !== undefined && !/^[a-z0-9][a-z0-9.-]{0,63}$/.test(opts.item)) usage('--item names one status item id');
356	      const common = {repo: paths.repo, statusRoot: paths.statusRoot, workRoot: paths.workRoot, bundlesDir: paths.bundlesDir, executors: prep.executors, limits, holder, progress,
357	        ...(opts.item !== undefined ? {only: opts.item} : {})};
358	      if (verb === 'tick') {
359	        const {issues} = await loadIssues(opts, {fetchImpl, env});
360	        const t = await tick({...common, issues});
361	        log(JSON.stringify(tickSummary(t, limits), null, 2));
362	        return 0;
363	      }
364	      if (opts.interval !== undefined && !/^\d+$/.test(opts.interval)) usage('--interval is a whole number of seconds');
365	      const ac = new AbortController();
366	      const stop = () => ac.abort();
367	      process.once('SIGINT', stop); process.once('SIGTERM', stop);
368	      const fetchIssuesNow = async () => (await loadIssues(opts, {fetchImpl, env})).issues;
369	      const ticks = await watch({...common, fetchIssues: fetchIssuesNow, interval_ms: Number(opts.interval ?? 60) * 1000, once: !!opts.once, signal: ac.signal});
370	      process.off('SIGINT', stop); process.off('SIGTERM', stop);
371	      log(JSON.stringify({ticks: ticks.map(t => tickSummary(t, limits))}, null, 2));
372	      return 0;
373	    }
374	    if (verb === 'context') {
375	      // Read-only investigation of ANY item, a Resolved one included: the dossier a judging seat would be given, and
376	      // optionally one retrieval. Nothing is recorded, claimed, reopened or signed.
377	      const item = opts.item ?? usage('context needs --item ID');
378	      const {buildDossier, renderDossier, makeRetriever} = await import('./context.mjs');
379	      const {issues} = await loadIssues(opts, {fetchImpl, env});
380	      const {work} = openWorkReadOnly(paths.workRoot);
381	      const d = buildDossier({repo: paths.repo, statusRoot: paths.statusRoot, item, work, issues, bundlesDir: paths.bundlesDir});
382	      if (opts.retrieve) {
383	        let req; try { req = JSON.parse(opts.retrieve); } catch { usage('--retrieve is one JSON request, e.g. {"op":"file","path":"x"}'); }
384	        log(JSON.stringify(makeRetriever({repo: paths.repo, statusRoot: paths.statusRoot, work, issues}).run(req), null, 2));
385	        return 0;
386	      }
387	      log(opts.json ? JSON.stringify(d, null, 2) : renderDossier(d));
