389	    }
390	    if (verb === 'reassess') {
391	      // Reassess an item's recorded model-rule reviews under the CURRENT identity policy and record what is found
392	      // (reassess.mjs). It writes only to the work ledger, with the controller key; no review ledger or status changes.
393	      const item = opts.item ?? usage('reassess needs --item ID');
394	      const opened = openWorkReadOnly(paths.workRoot);
395	      const auth = authorityOf(opened.work, paths.workRoot);
396	      if (!auth.held) { log(JSON.stringify(noAuthority(auth, opened.ledger), null, 2)); return 3; }
397	      const {reassessItem} = await import('./reassess.mjs');
398	      const r = reassessItem({work: openWorkLedger({root: paths.workRoot}), item});
399	      log(JSON.stringify({item: r.item, policy: r.policy, recorded: r.recorded.map(x => ({stage: x.stage, cycle: x.cycle, reassessment: x.reassessment, findings: x.findings})),
400	        skipped: r.skipped.map(x => ({stage: x.stage, cycle: x.cycle, why: x.why}))}, null, 2));
401	      return 0;
402	    }
403	    if (verb === 'serve') {
404	      // The execution service (service.mjs): watch, with a config, a single-instance lock, status and log files.
405	      if (!opts.config) usage('serve needs --config FILE (see ophanim/operate/service/service.example.json)');
406	      const {readServiceConfig, runService} = await import('./service.mjs');
407	      const config = readServiceConfig(opts.config);
408	      const ac = new AbortController();
409	      const stop = () => ac.abort();
410	      process.once('SIGINT', stop); process.once('SIGTERM', stop);
411	      const r = await runService({config, signal: ac.signal, fetchImpl, env, ...(opts['max-ticks'] ? {maxTicks: Number(opts['max-ticks'])} : {})});
412	      process.off('SIGINT', stop); process.off('SIGTERM', stop);
413	      log(JSON.stringify({code: r.code, stopped: r.stopped ?? null, refused: r.refused ?? null, blocked: r.blocked ?? null, ticks: r.ticks.length,
414	        status: path.relative(paths.repo, path.join(config.stateDir, 'service-status.json'))}, null, 2));
415	      return r.code;
416	    }
417	    usage(`unknown verb: ${verb}`);
418	  } catch (e) {
419	    err(e.usage ? `${e.message}\nusage: cli.mjs reconcile|tick|watch|report ... (see the header of ophanim/operate/cli.mjs)` : `refused: ${e.message}`);
420	    return e.usage ? 2 : 1;
421	  }
422	}
