1	// The status board as a projection of a ledger.
2	//
3	// Every status change is a `status` entry, signed by an operator and citing that item's previous status,
4	// so the board's history is the chain and the board itself (docs/STATUS.md) is generated from it, never
5	// edited by hand. The standing rule is enforced on append, not left to review:
6	//   - Resolved      done; names its basis
7	//   - In progress   being worked
8	//   - Ready         its dependencies have converged and nothing external is awaited: start it
9	//   - On Hold       waits on something OUTSIDE the work: governance, a credential, evidence from real
10	//                   runs, a fact a vendor has not published, or a decision only a person can make.
11	//                   "Not started yet" is never a hold; such an item is Ready.
12	// A hold also names when it was last re-checked, because a hold is re-evaluated for a change in
13	// circumstances before a loop concludes.
14	//
15	// Layout (committed): status/ledger/{chain.jsonl, objects/, ANCHOR}. Private keys live in
16	// status/ledger/keys/ by default, which is never committed: anyone can verify the board, only a key
17	// holder can change it. The owner keeps them off the repository (e.g. ~/.local/share/ophanim/status-ledger/keys)
18	// and names that directory with --keys or OPHANIM_STATUS_KEYS.
19	import fs from 'node:fs';
20	import path from 'node:path';
21	import {createHash} from 'node:crypto';
22	import {fileURLToPath} from 'node:url';
23	import {openLedger, createLedger, defineKinds, generateSigner} from './chain.mjs';
24	import {keyStore} from './home.mjs';
25	import {canonical, digest} from './canonical.mjs';
26	
27	export const STATUS_SCHEMA = 'ophanim.status/v1';
28	export const STATES = ['Resolved', 'In progress', 'Ready', 'On Hold'];
29	export const EXTERNAL = ['governance', 'credential', 'evidence', 'fact', 'decision'];
30	// Optional: who owns the item. One of Pantheon's five chairs (model seats, not people), or
31	// `decision-authority`: an item only the human owner decides. Absent on entries recorded before it existed.
32	export const OWNER_ROLES = ['impl@build', 'check@review', 'lead@orch', 'scout@opt', 'arbiter@judge', 'decision-authority'];
33	const ID = /^[a-z0-9][a-z0-9.-]{0,63}$/;
34	const DATE = /^\d{4}-\d{2}-\d{2}$/;
35	const fail = why => { throw Object.assign(new Error(why), {code: 'STATUS_REFUSED'}); };
36	
37	function statusKind({operators}) {
38	  return {
39	    status: {
40	      authors: a => operators.includes(a.key_id),
41	      validate: p => {
42	        if (p?.schema !== STATUS_SCHEMA || !ID.test(p.item ?? '') || typeof p.title !== 'string' || !p.title) return 'a status names its item id and title';
43	        if (!STATES.includes(p.state)) return `state must be one of ${STATES.join(', ')}`;
44	        if (typeof p.basis !== 'string' || !p.basis) return 'a status names its basis';
45	        if (!DATE.test(p.checked ?? '')) return 'a status names the date it was checked';
46	        if (p.depends_on !== undefined && !(Array.isArray(p.depends_on) && p.depends_on.every(d => ID.test(d)))) return 'depends_on lists item ids';
47	        if (p.owner_role !== undefined && !OWNER_ROLES.includes(p.owner_role)) return `owner_role must be one of ${OWNER_ROLES.join(', ')}`;
48	        if (p.evidence !== undefined) return evidenceRefusal(p.evidence, p.state);
49	        return null;
50	      },
51	      rederive: (e, view) => {
52	        const p = e.payload;
53	        // The standing rule: a hold waits on something outside the work, or on an item that itself waits.
54	        if (p.state === 'On Hold') {
55	          const external = EXTERNAL.includes(p.waiting_on);
56	          const blocked = (p.depends_on ?? []).some(d => {
57	            const s = latest(view, d);
58	            return s && s.state !== 'Resolved';
59	          });
60	          if (!external && !blocked) return `"${p.item}" is held on nothing external and no unresolved dependency: it is Ready, not On Hold`;
61	        } else if (p.waiting_on != null) return 'only a hold waits on something';
62	        // An item's statuses chain: a change cites the item's previous status, and a first status cites none.
63	        const prev = latestHash(view, p.item);
64	        const cited = e.derived_from.filter(h => view.entry(h)?.kind === 'status' && view.payload(h).item === p.item);
65	        if (prev ? !(cited.length === 1 && cited[0] === prev) : cited.length !== 0) return `a status for "${p.item}" cites its previous status, and only that`;
66	        return null;
67	      },
68	    },
69	  };
70	}
71	
72	function latestHash(view, item) {
73	  let found = null;
74	  for (const h of view.entries()) if (view.entry(h).kind === 'status' && view.payload(h).item === item) found = h;
75	  return found;
76	}
77	function latest(view, item) { const h = latestHash(view, item); return h ? view.payload(h) : null; }
