79	/** Open (or create on first use) the status ledger at `root`. */
80	//   create  false: refuse, rather than create, when no ledger is there (every reader but the first set)
81	//   keys    the directory holding the operator and orderer private keys (default <root>/keys). It is only
82	//           read: an apply on the owner's machine names the owner's key directory here, and nothing is
83	//           ever written to it or printed from it.
84	export function openStatusLedger({root, anchor = null, create = true, keys = null}) {
85	  if (!root || !path.isAbsolute(root)) fail('an absolute status ledger root is required');
86	  if (keys !== null && !path.isAbsolute(keys)) fail('an absolute key directory is required');
87	  const anchorFile = path.join(root, 'ANCHOR');
88	  if (!create && !fs.existsSync(anchorFile)) fail(`no status ledger at ${root}`);
89	  fs.mkdirSync(root, {recursive: true});
90	  let pinned = fs.existsSync(anchorFile) ? fs.readFileSync(anchorFile, 'utf8').trim() : null;
91	  const keysDir = keys ?? path.join(root, 'keys');
92	  if (!pinned) {
93	    if (fs.existsSync(path.join(root, 'chain.jsonl'))) fail('a status ledger without its ANCHOR is not opened');
94	    const keys = keyStore(keysDir);
95	    const operator = keys.put(generateSigner('operator')), orderer = keys.put(generateSigner('status-orderer'));
96	    pinned = createLedger({dir: root, operator, order: orderer,
97	      authority: {keyring: {operator: operator.publicJwk, 'status-orderer': orderer.publicJwk}, orderer: 'status-orderer', operators: ['operator']}});
98	    fs.writeFileSync(anchorFile, pinned + '\n');
99	  }
100	  if (anchor && anchor !== pinned) fail('this status ledger is not the one the caller pinned');
101	  // The kind is bound to whoever the chain's authority names as operators: opened once to read the
102	  // authority, then again with the operators it names.
103	  let operators = ['operator'];
104	  const L = () => openLedger({dir: root, kinds: defineKinds(statusKind({operators})), anchor: pinned});
105	  let ledger = L();
106	  const state = ledger.verify();
107	  if (!state.ok) fail(`status ledger does not verify: ${state.why}`);
108	  operators = state.authority.operators;
109	  ledger = L();
110	
111	  const view = () => {
112	    const at = new Map(ledger.read().map(e => [ledger.hashOf(e), e]));
113	    return {entry: h => at.get(h) ?? null, payload: h => (at.has(h) ? ledger.payloadOf(at.get(h)) : null), entries: () => [...at.keys()]};
114	  };
115	  const signers = () => {
116	    // Read only: a missing key directory is refused, never created.
117	    if (!fs.existsSync(keysDir)) fail('no operator or orderer key is held here: the board can be verified, not changed');
118	    const keys = keyStore(keysDir);
119	    const op = operators.map(id => keys.get(id)).find(Boolean), order = keys.get(state.authority.orderer);
120	    if (!op || !order) fail('no operator or orderer key is held here: the board can be verified, not changed');
121	    return {op, order};
122	  };
123	  return {
124	    ledger, anchor: pinned, root,
125	    /** Record a status for an item (a change cites the item's previous status). */
126	    set({item, title, state: s, basis, checked, waiting_on = null, depends_on = undefined, owner_role = undefined, evidence = undefined, cites = []}) {
127	      const {op, order} = signers();
128	      const prev = latestHash(view(), item);
129	      const payload = {schema: STATUS_SCHEMA, item, title, state: s, basis, checked, waiting_on, ...(depends_on ? {depends_on} : {}), ...(owner_role !== undefined ? {owner_role} : {}),
130	        ...(evidence !== undefined ? {evidence} : {})};
131	      return ledger.append({kind: 'status', payload, author: {key_id: op.key_id}, signer: op, order, derivedFrom: [...(prev ? [prev] : []), ...cites]}).hash;
132	    },
133	    /** The board: the latest status of every item, from a ledger that verifies. */
134	    board() {
135	      const v = ledger.verify();
136	      if (!v.ok) fail(`status ledger does not verify: ${v.why}`);
137	      const vw = view(), items = new Map();
138	      for (const h of vw.entries()) if (vw.entry(h).kind === 'status') items.set(vw.payload(h).item, {...vw.payload(h), entry: h});
139	      return {head: v.head, anchor: pinned, entries: v.entries, items: [...items.values()]};
140	    },
141	  };
142	}
