80	/**
81	 * A ticket for `item`, validated: {ticket, spec, path, digest} or {why}. `spec` is what runOpenItem
82	 * takes, with repo_root resolved against the repository (a ticket names it relative, so it is portable).
83	 */
84	export function readTicket({ repo, item }) {
85	  const file = ticketPath(repo, item), rel = relative(repo, file);
86	  if (!existsSync(file)) return { why: `no ticket at ${rel}` };
87	  let t;
88	  try { t = JSON.parse(readFileSync(file, "utf8")); } catch (e) { return { why: `${rel} is not JSON: ${e.message}` }; }
89	  const why = ticketRefusal(t, { repo, item });
90	  if (why) return { why: `${rel}: ${why}` };
91	  const spec = Object.fromEntries(RUN_FIELDS.filter(k => t[k] !== undefined).map(k => [k, t[k]]));
92	  spec.key ??= item;
93	  spec.repo_root = resolve(repo, t.repo_root ?? ".");
94	  return { ticket: t, spec, path: rel, digest: "sha256:" + digest(t) };
95	}
