97	function ticketRefusal(t, { repo, item }) {
98	  if (!t || typeof t !== "object" || Array.isArray(t) || t.schema !== TICKET_SCHEMA) return `a ticket is an ${TICKET_SCHEMA} object`;
99	  const extra = Object.keys(t).filter(k => !TICKET_FIELDS.includes(k));
100	  if (extra.length) return `unknown ticket field(s): ${extra.join(", ")}`;
101	  if (t.item !== item) return `the ticket names item "${t.item}", not "${item}"`;
102	  if (!str(t.slice)) return "a ticket names the slice of the item it does (slice)";
103	  const p = t.proposes;
104	  if (!p || !["Resolved", "Ready", "In progress"].includes(p.state) || !str(p.basis) || Object.keys(p).some(k => !["state", "basis"].includes(k))) {
105	    return "proposes names the state the item takes when the slice ships and its review closes (Resolved, Ready or In progress) and its basis";
106	  }
107	  for (const k of ["title", "goal", "question", "acceptance_cmd"]) if (!str(t[k])) return `the ticket names its ${k}`;
108	  if (t.repo_root !== undefined && (typeof t.repo_root !== "string" || isAbsolute(t.repo_root))) return "repo_root is relative to the repository, so the ticket is portable";
109	  const root = resolve(repo, t.repo_root ?? ".");
110	  if (!isUnder(repo, root)) return "repo_root is outside the repository";
111	  if (t.difficulty !== undefined && !Object.hasOwn(TOKEN_TIERS, t.difficulty)) return `difficulty is one of ${Object.keys(TOKEN_TIERS).join(", ")}`;
112	  try { taskProfile(t); } catch (e) { return e.message; }
113	  for (const k of ["constraints", "forbidden"]) if (t[k] !== undefined && !(Array.isArray(t[k]) && t[k].every(str))) return `${k} lists strings`;
114	  const spec = { ...t, key: t.key ?? item, repo_root: root };
115	  const refused = ticketRuntimeRefusal(spec) ?? ticketContainmentRefusal(spec);
116	  if (refused) return refused;
117	  for (const c of t.copy) if (!existsSync(join(root, c))) return `copy names ${c}, which is not in the repository`;
118	  return null;
119	}
