131	export function seatTeam({ pools = [], overrides = {}, spec = null, profile = "argo", scouts: scoutVendors = ["xai"], planTitle = "model" } = {}) {
132	  const slots = spec ? normalizeSlots(spec) : [{ slot: "file", path: null }];
133	  const difficulty = spec?.difficulty ?? "medium";
134	  const task = profile === "fit" ? taskProfile(spec ?? {}, { paths: slots.map(s => s.path).filter(Boolean), mode: "batch" }) : null;
135	  const choose = (role, extra = {}) => selectSeat(role, { profile, difficulty, pools, needsContext: 1, roleOverride: overrides[role] ?? null,
136	    ...(task ? { task } : {}), ...extra });
137	  const seatOf = c => ({ vendor: c.vendor, model: c.model, lab: labOf(c.vendor, c.model), pool: c.pool ?? c.vendor, source: c.selection?.source ?? null,
138	    ...(["operator-override", "slot-override"].includes(c.selection?.source) ? { operator: true } : {}),
139	    ...(profile === "fit" ? { class: c.selection?.class?.value ?? null, effort: c.selection?.effort?.value ?? null } : {}) });
140	  const ladder = choice => [...new Map(choice.candidates.map(c => [`${c.vendor}/${c.model}`, seatOf(c)])).values()];
141	  const notes = [];
142	  // Scouts, as the dispatch's intake seats them.
143	  const scoutLadders = [];
144	  if (profile === "fit") {
145	    const width = requirementsOf(task).explorer_width.value, avoid = [], avoidLabs = [];
146	    for (let k = 0; k < width; k++) {
147	      const l = ladder(choose("scout", { avoid, avoidLabs, ...(k ? { roleOverride: null } : {}) }));
148	      scoutLadders.push(l); avoid.push(l[0].vendor); avoidLabs.push(l[0].lab);
149	    }
150	  } else {
151	    const intake = profile === "legacy" ? seatingPlan({ roles: ["scout"], seating: INTAKE }) : null;
152	    for (const vendor of scoutVendors) {
153	      if (profile === "argo") { scoutLadders.push(ladder(choose("scout")).filter(c => c.vendor === vendor)); continue; }
154	      const model = intake.assigned.scout.vendor === vendor ? intake.assigned.scout.model : (vendor === "xai" ? modelId("xai", "grok-4.3") : modelId("google", "argon"));
155	      scoutLadders.push(ladder(choose("scout", { explicit: { seat: { vendor, model, basis: "QUOTA" }, source: "intake", reason: `intake fan-out vendor ${vendor}` } })));
156	    }
157	  }
158	  const reviewLabs = task ? requirementsOf(task).review_labs.value : 1;
159	  if (reviewLabs > 1) notes.push(`stakes need ${reviewLabs} review labs: the dispatch checks that capacity before any work call and is pending when it is short`);
160	  // planTitle `ticket`: the plan is the ticket's own title and no planner model runs or contributes.
161	  const planner = planTitle === "ticket" ? [] : ladder(choose("planner"));
162	  const implementers = slots.map((sl, i) => ladder(choose("implementer", { pin: sl.model ?? null,
163	    slotOverride: overrides[`implementer.${i}`] ?? overrides[`implementer.${sl.slot}`] ?? null })));
164	  const p = planner[0] ?? null;
165	  const reviewPanels = implementers.map(im => {
166	    const m = im[0];
167	    const contributors = [m, ...(p ? [p] : [])];
168	    const avoid = [...new Set(contributors.flatMap(c => [c.vendor, ...vendorsOfLab(c.lab)]))], avoidLabs = [...new Set(contributors.map(c => c.lab))];
169	    const panel = [], usedVendors = [], usedLabs = [];
170	    for (let k = 0; k < reviewLabs; k++) {
171	      const l = ladder(choose("reviewer", { avoid: [...avoid, ...usedVendors], avoidLabs: [...avoidLabs, ...usedLabs], ...(k ? { roleOverride: null } : {}) }));
172	      panel.push(l); usedVendors.push(l[0].vendor); usedLabs.push(l[0].lab);
173	    }
174	    return panel;
175	  });
176	  const team = { profile, scout: scoutLadders[0] ?? [], scouts: scoutLadders.map(l => l[0]), planner, implementer: implementers[0], implementers,
177	    reviewer: reviewPanels[0][0], review_panels: reviewPanels.map(panel => panel.map(l => l[0])), ...(notes.length ? { notes } : {}) };
178	  return { ...team, plan_title: planTitle, cycle_reviewers: cycleReviewers({ planLabs: p ? [p.lab] : [], workLabs: [...new Set(implementers.map(l => l[0].lab))] }) };
