181	/**
182	 * The cycle's reviewers: n labs outside every lab that contributed to the reviewed change (review/scope.mjs, scope
183	 * `change`). The scope is never narrowed to make a panel possible (owner direction 2026-11-17: enforce the existing
184	 * independence requirement; do not drop the planner's contribution or weaken the scope). When the configured pool
185	 * cannot supply n labs outside the contributors, the result is pending, with no seats, and says why.
186	 */
187	export function cycleReviewers({ scope = null, planLabs = [], workLabs = [], n = 3, seating = undefined, facts = undefined, independence = "lab", policy = undefined }) {
188	  const full = scope ?? { kind: "change", contributions: [...planLabs.map(lab => ({ purpose: "plan", lab })), ...workLabs.map(lab => ({ purpose: "work", lab }))],
189	    author_labs: [...new Set([...workLabs, ...planLabs])].sort() };
190	  const base = { author_labs: full.author_labs, planner_excluded: true, scope: full };
191	  // MODEL-level independence (pantheon.cycle/v3), only when asked for: the contributing models are excluded, three
192	  // distinct labs are still required, labs that did not contribute are seated first, and a seat that shares a lab with
193	  // a contributor says so. The default is the lab rule below, unchanged.
194	  if (independence === "model") {
195	    const keys = contributorKeys(full.contributions ?? [], ...(policy ? [policy] : []));
196	    const by = { ...base, independence: "model", author_models: keys.models, excluded_labs: keys.labs, author_labs: keys.contributing_labs, contributions: full.contributions ?? [] };
197	    try {
198	      const seats = reviewSeatsByModel({ n, excluded: keys, ...(policy ? { policy } : {}), ...(seating ? { seating } : {}), ...(facts ? { facts } : {}) });
199	      return { ...by, seats, shared_labs: seats.filter(s => s.shared_lab).map(s => s.lab) };
200	    } catch (e) {
201	      if (e.code !== "NO_SEATS") throw e;
202	      if (e.unresolved) return { ...by, seats: null, pending: { code: "REVIEW_CAPACITY_PENDING", need: n, eligible_labs: [], unresolved: e.unresolved,
203	        why: `a contributor's identity is unresolved (${e.unresolved.map(u => `${u.vendor}/${u.model}`).join(", ")}): no reviewer can be shown not to be it; produced work and evidence are kept and the review is pending until the name is declared` } };
204	      return { ...by, seats: null, pending: { code: "REVIEW_CAPACITY_PENDING", need: n, eligible_labs: e.eligible_labs,
205	        why: `fewer than ${n} labs have a model that did not contribute to the change (eligible: ${e.eligible_labs.join(", ") || "none"}; contributing models: ` +
206	          `${keys.models.join(", ") || "none"}${keys.labs.length ? `; labs excluded outright: ${keys.labs.join(", ")}` : ""}); produced work and evidence are kept and the review is pending` } };
207	    }
208	  }
209	  try {
210	    return { ...base, seats: reviewSeats({ n, avoidLabs: full.author_labs, ...(seating ? { seating } : {}), ...(facts ? { facts } : {}) }) };
211	  } catch (e) {
212	    if (e.code !== "NO_SEATS") throw e;
213	    return { ...base, seats: null, pending: { code: "REVIEW_CAPACITY_PENDING", need: n,
214	      why: `the configured cycle reviewer pool offers fewer than ${n} labs outside the labs that contributed to the change ` +
215	        `(${full.author_labs.join(", ")}); produced work and evidence are kept and the review is pending` } };
216	  }
