226	/** Items ordered so that an item's dependencies come before it (cycles broken by id order). */
227	export function dependencyOrder(items) {
228	  const byId = new Map(items.map(i => [i.item, i])), out = [], seen = new Set();
229	  const visit = (i, stack) => {
230	    if (seen.has(i.item) || stack.has(i.item)) return;
231	    stack.add(i.item);
232	    for (const d of [...(i.depends_on ?? [])].sort()) if (byId.has(d)) visit(byId.get(d), stack);
233	    stack.delete(i.item);
234	    seen.add(i.item);
235	    out.push(i);
236	  };
237	  for (const i of [...items].sort((a, b) => a.item.localeCompare(b.item))) visit(i, new Set());
238	  return out;
239	}
