241	/** Why `item` is not dispatchable on `board`, or null; with its ticket when it is. */
242	export function dispatchable(board, item, { repo }) {
243	  const byId = new Map(board.items.map(i => [i.item, i]));
244	  const it = byId.get(item);
245	  if (!it) return { why: `"${item}" is not on the status board` };
246	  if (it.state !== "Ready") return { why: `its latest status is ${it.state}, not Ready` };
247	  const open = (it.depends_on ?? []).filter(d => byId.get(d)?.state !== "Resolved");
248	  if (open.length) return { why: `depends on unresolved ${open.join(", ")}` };
249	  const t = readTicket({ repo, item });
250	  if (t.why) return { why: t.why };
251	  if (it.evidence?.ticket?.digest === t.digest) return { why: `${t.path} (${t.ticket.slice}) is already recorded on its latest status; write the next slice's ticket` };
252	  return { ticket: t };
253	}
