255	/** `next`: the dispatchable items, in dependency order, each with its ticket and the team it would seat. */
256	export function boardNext({ repo, statusRoot = defaultStatusRoot(repo), anchor = null, pools = null, overrides = {}, profile = "argo", planTitle = "ticket" }) {
257	  const board = readBoard({ statusRoot, anchor });
258	  const poolList = pools ?? readPools();
259	  const items = [], skipped = [];
260	  for (const it of dependencyOrder(board.items)) {
261	    if (it.state !== "Ready") continue;
262	    const d = dispatchable(board, it.item, { repo });
263	    if (d.why) { skipped.push({ item: it.item, why: d.why }); continue; }
264	    const t = d.ticket;
265	    // The team this ticket's run will seat: the same selector, on this ticket, under the run's profile.
266	    const team = seatTeam({ pools: poolList, overrides, spec: t.spec, profile, planTitle });
267	    items.push({ item: it.item, title: it.title, entry: it.entry, basis: it.basis,
268	      ticket: { path: t.path, digest: t.digest, slice: t.ticket.slice, proposes: t.ticket.proposes, key: t.spec.key,
269	        files: normalizeSlots(t.spec).map(s => s.path), acceptance_cmd: t.spec.acceptance_cmd, difficulty: t.spec.difficulty ?? "medium" },
270	      team });
271	  }
272	  return { board: { anchor: board.anchor, head: board.head, entries: board.entries, root: statusRoot }, items, skipped };
273	}
