283	/**
284	 * Commit the shipped artifacts on `branch`, from `base`, without touching the working tree or the index:
285	 * every file's base version must be the baseline the implementer was shown (else something changed it
286	 * since the run started, and the commit is refused).
287	 */
288	export function commitShipped({ repo, base, files, branch, message }) {
289	  const git = gitIn(repo);
290	  const ref = `refs/heads/${branch}`;
291	  let exists = true;
292	  try { git(["rev-parse", "--verify", "--quiet", ref]); } catch { exists = false; }
293	  if (exists) fail(`branch ${branch} already exists; delete it or name another with --branch`);
294	  for (const f of files) {
295	    let at = null;
296	    try { at = git(["show", `${base}:${f.path}`], { encoding: "buffer" }); } catch { at = null; }
297	    if ((at !== null) !== f.baseline.exists || (at !== null && cidOf("blob", at) !== f.baseline.bytes)) {
298	      fail(`${f.path} at ${base.slice(0, 12)} is not what the implementer was shown; the change is not committed over it`);
299	    }
300	  }
301	  const index = join(tmpdir(), `pantheon-board-index-${process.pid}-${Date.now()}`);
302	  const env = { GIT_INDEX_FILE: index };
303	  try {
304	    git(["read-tree", base], { env });
305	    for (const f of files) {
306	      const mode = git(["ls-tree", base, "--", f.path]).split(/\s/)[0] || "100644";
307	      const blob = git(["hash-object", "-w", "--stdin"], { input: f.contents }).trim();
308	      git(["update-index", "--add", "--cacheinfo", `${mode},${blob},${f.path}`], { env });
309	    }
310	    const tree = git(["write-tree"], { env }).trim();
311	    const commit = git(["commit-tree", tree, "-p", base, "-F", "-"], { input: message }).trim();
312	    git(["update-ref", ref, commit, "0".repeat(commit.length)]);
313	    return commit;
314	  } finally { rmSync(index, { force: true }); }
315	}
