707	  checkBound(maxProviderCalls);
708	  const file = join(dir, "evidence.json");
709	  if (!existsSync(file)) fail(`no evidence bundle at ${file}: resume names the --out DIR of the run`);
710	  const bundle = JSON.parse(readFileSync(file, "utf8"));
711	  if (bundle.schema !== BUNDLE_SCHEMA) fail(`${file} is not a ${BUNDLE_SCHEMA} bundle`);
712	  if (item !== null && bundle.item !== item) fail(`the bundle at ${dir} is for "${bundle.item}", not "${item}"`);
713	  if (!bundle.run.shipped || !bundle.commit) fail("the run did not ship: there is no change to review, and a resume does not run the item again");
