716	  const rec = sys.recorder();
717	  const last = rec.lastCycle(bundle.review.scope);
718	  if (last?.hash !== bundle.review.cycle) fail(`the bundle's cycle ${bundle.review.cycle.slice(0, 19)} is not the last cycle of ${bundle.review.scope} on the run ledger`);
719	  const state = rec.cycleState(bundle.review.cycle);
720	  // A cycle opened on fewer than three labs (a run before this was enforced) is not continued: its review cannot be
