730	    if (chosen.pending) fail(`${chosen.pending.code}: ${chosen.pending.why}`);
731	    if ([...chosen.author_labs].sort().join() !== [...bundle.review.author_labs].sort().join()) fail("the run's author labs do not re-derive the bundle's");
