751	    writeFileSync(file, JSON.stringify(bundle, null, 2) + "\n");
752	    progress({ event: "resumed", cycle: r.cycle, reviews: r.reviews.length, retained: r.retained.length, attempted: r.attempted.length, failed: r.failed.length });
