765	 */
766	export function proposeFromBundle({ dir, statusRoot, anchor = null, acceptUnverified = undefined, sys = null, practice = null }) {
767	  const file = join(dir, "evidence.json");
768	  const bundle = JSON.parse(readFileSync(file, "utf8"));
769	  if (bundle.schema !== BUNDLE_SCHEMA) fail(`${file} is not a ${BUNDLE_SCHEMA} bundle`);
770	  const save = () => writeFileSync(file, JSON.stringify(bundle, null, 2) + "\n");
771	  if (!bundle.run.shipped) return { bundle, why: "the run did not ship: there is nothing to propose" };
772	  if (!bundle.review) return { bundle, why: "the change has not been reviewed" };
773	  sys ??= openPantheonLedger({ root: bundle.review.ledger, anchor: bundle.review.ledger_anchor, board: openBoard(bundle.board) });
774	  const rec = sys.recorder();
775	  if (!rec.cycleState(bundle.review.cycle).close) {
776	    recordPractice(rec, bundle.review.cycle, practice);
777	    const auto = recordAutomaticPractice(rec, bundle.review.cycle, storeOf(bundle));
778	    if (auto) bundle.review.evaluation = auto;
779	  }
780	  const state = rec.cycleState(bundle.review.cycle);
781	  bundle.review.practice = state.dispositions.map(d => ({ disposition: d.hash, stage: d.payload.stage, outcome: d.payload.outcome, provisional: d.payload.provisional }));
782	  if (!state.close) {
783	    try { const c = rec.closeCycle(bundle.review.cycle); bundle.review.close = c.hash; bundle.review.outcome = c.outcome; }
784	    catch (e) {
785	      if (e.code !== "CYCLE_OPEN") throw e;
786	      save();
787	      return { bundle, why: e.message };
788	    }
789	  } else {
790	    bundle.review.close = state.close;
791	    bundle.review.outcome = sys.ledger.payloadOf(sys.ledger.read().find(e => sys.ledger.hashOf(e) === state.close)).outcome;
792	  }
793	  bundle.review.resolutions = state.findings.map(f => ({ finding: f.hash, resolution: rec.cycleState(bundle.review.cycle).resolutions.get(f.hash)?.payload ?? null }));
794	  const reviewers = state.reviews.map(x => ({ vendor: x.seat.vendor, lab: x.lab, review: x.hash })).map(x => {
795	    const p = sys.ledger.payloadOf(sys.ledger.read().find(e => sys.ledger.hashOf(e) === x.review));
