797	  });
798	  const evidence = {
799	    run: { ledger_anchor: bundle.run.ledger_anchor, ledger_head: bundle.run.ledger_head, run_json_digest: bundle.run.run_json_digest,
800	      shipped: bundle.run.shipped, gate_entry: bundle.run.gate_entry },

801	    review: { cycle_ledger_anchor: bundle.review.ledger_anchor, cycle: bundle.review.cycle, close_entry: bundle.review.close,
802	      outcome: bundle.review.outcome, reviewers },
803	    commit: bundle.commit, tests: bundle.run.tests,
804	    ticket: { path: bundle.ticket.path, digest: bundle.ticket.digest, slice: bundle.ticket.slice },
805	  };
806	  const f = bundle.review.resolutions.length;
807	  // The basis says what happened in one line; the full record (ticket, commands, ledgers) is the evidence.
808	  const basis = `${bundle.ticket.proposes.basis}. Board run: shipped as ${bundle.commit.slice(0, 12)} (acceptance exit ${bundle.run.tests?.exit})`
809	    + `; review cycle ${bundle.review.cycle.slice(7, 19)} closed ${bundle.review.outcome}`
810	    + ` by ${reviewers.map(x => x.lab).join(", ")} (${f} finding${f === 1 ? "" : "s"})`;
