832	export function checkProposal({ proposal: p, repo }) {
833	  const why = proposalRefusal(p);
834	  if (why) fail(`proposal refused: ${why}`);
835	  const loc = p.locations ?? {};
836	  if (!loc.run_ledger || !existsSync(loc.run_ledger)) fail("the run ledger is not on this machine: the evidence can only be checked structurally");
837	  const sys = openPantheonLedger({ root: loc.run_ledger, anchor: p.evidence.run.ledger_anchor });
838	  const v = sys.ledger.verify();
839	  if (!v.ok) fail(`the run ledger does not verify: ${v.why}`);
840	  const rec = sys.recorder();
841	  const found = [];
842	  if (!sys.ledger.read().some(e => sys.ledger.hashOf(e) === p.evidence.run.ledger_head)) fail("the cited run ledger head is not in the ledger");
843	  found.push(`run ledger verifies against ${p.evidence.run.ledger_anchor.slice(0, 19)} (${v.entries} entries; complete: ${v.complete})`);
844	  const rv = p.evidence.review;
845	  if (rv) {
846	    if (rv.cycle_ledger_anchor !== p.evidence.run.ledger_anchor) fail("this check reads a review cycle on the run's own ledger");
847	    const state = rec.cycleState(rv.cycle);
848	    if (!state.cycle) fail("the cited cycle is not on the run ledger");
849	    if (state.close !== rv.close_entry) fail("the cited close is not the cycle's close");
850	    const claim = sys.ledger.payloadOf(sys.ledger.read().find(e => sys.ledger.hashOf(e) === state.close));
851	    if (claim.outcome !== rv.outcome) fail(`the cycle closed ${claim.outcome}, not ${rv.outcome}`);
852	    const labs = state.reviews.map(r => r.lab).sort();
853	    if (labs.join() !== rv.reviewers.map(r => r.lab).sort().join()) fail("the reviewers' labs differ from the recorded reviews");
854	    found.push(`cycle ${rv.cycle.slice(0, 19)} closed ${claim.outcome}: ${state.reviews.length} reviews on ${labs.join(", ")}`);
855	    if (repo && p.evidence.commit) {
856	      const git = gitIn(repo);
857	      try { git(["cat-file", "-e", `${p.evidence.commit}^{commit}`]); } catch { fail(`commit ${p.evidence.commit} is not in ${repo}`); }
858	      if (state.cycle.head !== p.evidence.commit) fail("the commit is not the head the cycle reviewed");
859	      try { git(["merge-base", "--is-ancestor", state.cycle.base, p.evidence.commit]); } catch { fail("the commit does not descend from the cycle's base"); }
860	      const diff = git(["diff", "--no-color", state.cycle.base, p.evidence.commit]);
861	      if (sha256(diff) !== state.cycle.diff_sha) fail("the commit's diff is not the one the reviewers were given");
862	      found.push(`commit ${p.evidence.commit.slice(0, 12)} is the reviewed head; its diff matches the cycle`);
863	    }
864	  }
865	  if (loc.run_json) {
866	    if (sha256(readFileSync(loc.run_json)) !== p.evidence.run.run_json_digest) fail("run.json is not the one the proposal cites");
867	    found.push("run.json matches its digest");
868	  }
869	  return { ok: true, proposal: proposalDigest(p), found };
870	}
