1	// The execution service: the long-running process that keeps the governed lifecycle moving, on the machine where the
2	// provider keys and the controller key are (the owner's). It is `watch` (scheduler.mjs) with what a service needs:
3	//
4	//   config      one validated file (SERVICE_CONFIG_SCHEMA): repository and ledgers, the issue source, the seats, the
5	//               interval and the limits. `limits.total_provider_calls` must be declared: it bounds the provider calls
6	//               the work ledger may ever record (scheduler `spent` counts every stage on the ledger, failed and resumed
7	//               ones included), so a service running for weeks cannot exceed it. Unknown keys are refused.
8	//   one process a lock file (O_EXCL) names the holder's pid and host. A second service on the same work ledger is
9	//               refused (SERVICE_RUNNING). A lock left by a dead process on this host is taken over and the takeover
10	//               recorded; a lock from another host is refused, never guessed at.
11	//   authority   checked before the loop: without the controller key the service stops with NO_AUTHORITY (exit 3) and
12	//               records nothing; it does not idle pretending to work.
13	//   visibility  after every tick: <state>/service-status.json (state, heartbeat, last tick summary, the next retry due,
14	//               spend against the cap) and one line in <state>/service.jsonl. The public record (ophanim/public)
15	//               projects the work ledger itself.
16	//   stop        SIGTERM/SIGINT stop the loop between ticks. A stage in flight finishes or, if the process is killed,
17	//               its claim's lease expires and the next start releases it as expired and resumes from the last
18	//               recorded stage (scheduler.mjs): no work is repeated or lost.
19	//   errors      a tick that throws is logged with its reason and retried after the interval, at most
20	//               `max_consecutive_errors` times in a row; then the service stops with the error recorded.
21	//
22	// Inputs: the config file, an optional injected `executors` (tests) or seats from the config. Outputs: the status
23	// file, the log, and the exit code (0 stopped, 1 refused, 3 NO_AUTHORITY). Must never: run without a declared total,
24	// run twice on one work ledger, or continue past missing authority.
25	import fs from 'node:fs';
26	import os from 'node:os';
27	import path from 'node:path';
28	import {watch} from './scheduler.mjs';
29	import {spent} from './scheduler.mjs';
30	import {openWorkLedger} from './work-ledger.mjs';
31	import {prepareDispatch, loadIssues, tickSummary, limitsOf} from './cli.mjs';
32	
33	export const SERVICE_CONFIG_SCHEMA = 'ophanim.operate-service/v1';
34	const refuse = (why, code = 'SERVICE_REFUSED') => { throw Object.assign(new Error(why), {code}); };
35	const KEYS = ['schema', 'repo', 'status_ledger', 'work_ledger', 'bundles', 'state_dir', 'issues', 'seats', 'interval_s', 'limits', 'holder', 'max_consecutive_errors'];
36	const LIMIT_KEYS = {total_provider_calls: 'total-provider-calls', stage_provider_calls: 'stage-provider-calls', iterations: 'iterations', concurrency: 'concurrency',
37	  elapsed_ms: 'elapsed-ms', lease_ms: 'lease-ms', stage_attempts: 'stage-attempts'};
