39	/** Read and validate a service config. Relative paths resolve against the config file's directory. */
40	export function readServiceConfig(file) {
41	  const at = path.dirname(path.resolve(file));
42	  let c;
43	  try { c = JSON.parse(fs.readFileSync(file, 'utf8')); } catch (e) { refuse(`the service config ${file} is not readable JSON: ${e.message}`); }
44	  if (c?.schema !== SERVICE_CONFIG_SCHEMA) refuse(`the service config is an ${SERVICE_CONFIG_SCHEMA} object`);
45	  const unknown = Object.keys(c).filter(k => !KEYS.includes(k));
46	  if (unknown.length) refuse(`unknown service config key(s): ${unknown.join(', ')}`);
47	  const abs = p => (p == null ? null : path.resolve(at, p));
48	  if (!c.limits || !Number.isInteger(c.limits.total_provider_calls) || c.limits.total_provider_calls < 0) {
49	    refuse('limits.total_provider_calls must be declared (a non-negative integer): it caps every provider call the work ledger records');
50	  }
51	  const unknownLimits = Object.keys(c.limits).filter(k => !Object.hasOwn(LIMIT_KEYS, k));
52	  if (unknownLimits.length) refuse(`unknown limit(s): ${unknownLimits.join(', ')}`);
53	  for (const [k, v] of Object.entries(c.limits)) if (!(Number.isInteger(v) && v >= 0)) refuse(`limits.${k} is a non-negative integer`);
54	  if (!(Number.isInteger(c.interval_s) && c.interval_s >= 10)) refuse('interval_s is a whole number of seconds, at least 10');
55	  const issues = c.issues ?? {source: 'none'};
56	  if (!['github', 'file', 'none'].includes(issues.source)) refuse('issues.source is github, file or none');
