73	/** Take the single-instance lock, or refuse. Returns {release, takeover}. */
74	export function acquireLock(file, {pid = process.pid, host = os.hostname(), now = Date.now()} = {}) {
75	  fs.mkdirSync(path.dirname(file), {recursive: true});
76	  const mine = {pid, host, started: new Date(now).toISOString()};
77	  let takeover = null;
78	  for (let tries = 0; tries < 2; tries++) {
79	    try {
80	      const fd = fs.openSync(file, 'wx');
81	      fs.writeSync(fd, JSON.stringify(mine) + '\n');
82	      fs.closeSync(fd);
83	      return {takeover, release: () => {
84	        try { if (JSON.parse(fs.readFileSync(file, 'utf8')).pid === pid) fs.rmSync(file); } catch { /* already gone */ }
85	      }};
86	    } catch (e) {
87	      if (e.code !== 'EEXIST') throw e;
88	      let held = null;
89	      try { held = JSON.parse(fs.readFileSync(file, 'utf8')); } catch { held = null; }
90	      if (held && held.host !== host) refuse(`the work ledger is served from ${held.host} (pid ${held.pid}, since ${held.started}); stop it there first`, 'SERVICE_RUNNING');
91	      if (held && alive(held.pid)) refuse(`a service is already running on this work ledger (pid ${held.pid}, since ${held.started})`, 'SERVICE_RUNNING');
92	      takeover = {previous: held, why: held ? `pid ${held.pid} is not running: its lock is stale` : 'the lock file was unreadable'};
93	      fs.rmSync(file, {force: true});
94	    }
95	  }
96	  refuse('could not take the service lock');
97	}
