99	/**
100	 * Run the service until `signal` aborts (or, with `maxTicks`, after that many loop turns: tests and bounded runs).
101	 * Returns {code, ticks, stopped}.
102	 */
103	export async function runService({config, executors = null, signal = null, maxTicks = null, fetchImpl, env = process.env, clock = Date.now,
104	  sleep = (ms, sig) => new Promise(r => { const t = setTimeout(r, ms); sig?.addEventListener('abort', () => { clearTimeout(t); r(); }, {once: true}); })}) {
105	  const c = config;
106	  fs.mkdirSync(c.stateDir, {recursive: true});
107	  const statusFile = path.join(c.stateDir, 'service-status.json'), logFile = path.join(c.stateDir, 'service.jsonl');
108	  const write = s => fs.writeFileSync(statusFile, JSON.stringify({schema: 'ophanim.operate-service-status/v1', holder: c.holder, pid: process.pid, ...s}, null, 2) + '\n');
109	  const event = e => fs.appendFileSync(logFile, JSON.stringify({at: new Date(clock()).toISOString(), ...e}) + '\n');
110	  const paths = {repo: c.repo, statusRoot: c.statusRoot, workRoot: c.workRoot, bundlesDir: c.bundlesDir};
111	
112	  let lock;
113	  try { lock = acquireLock(path.join(c.stateDir, 'service.lock'), {now: clock()}); }
114	  catch (e) { event({event: 'refused', code: e.code, why: e.message}); return {code: 1, refused: e.message, ticks: []}; }
115	  if (lock.takeover) event({event: 'lock-takeover', ...lock.takeover});
116	  const ticks = [];
117	  try {
118	    let exec = executors;
119	    if (!exec) {
120	      const prep = await prepareDispatch({paths, opts: {...(c.seats.turn ? {turn: c.seats.turn} : {}), ...(c.seats.clients ? {clients: c.seats.clients} : {})}, limits: c.limits,
121	        progress: e => event({event: 'progress', ...e})});
122	      if (prep.blocked) {
123	        write({state: 'blocked', at: new Date(clock()).toISOString(), block: prep.blocked});
124	        event({event: 'blocked', block: prep.blocked});
125	        return {code: 3, blocked: prep.blocked, ticks};
126	      }
127	      exec = prep.executors;
128	    }
129	    const opts = c.issues.source === 'github' ? {github: true} : c.issues.source === 'file' ? {issues: c.issues.path} : {};
130	    const issueEnv = c.issues.source === 'github' ? {...env, GITHUB_REPOSITORY: c.issues.repository} : env;
131	    const fetchIssues = async () => (await loadIssues(opts, {fetchImpl, env: issueEnv})).issues;
132	    const state = {last: null, due: null};
133	    event({event: 'started', limits: c.limits, interval_ms: c.interval_ms, issues: c.issues.source});
134	    let errors = 0, turns = 0, stopped = 'signal';
135	    while (!signal?.aborted) {
136	      if (maxTicks !== null && turns >= maxTicks) { stopped = 'max-ticks'; break; }
137	      turns++;
138	      try {
139	        const ran = await watch({repo: c.repo, statusRoot: c.statusRoot, workRoot: c.workRoot, bundlesDir: c.bundlesDir, executors: exec, limits: c.limits,
140	          holder: c.holder, fetchIssues, once: true, state, clock, progress: e => event({event: 'progress', ...e})});
141	        errors = 0;
142	        const t = ran.at(-1) ?? null;
143	        if (t) { ticks.push(t); event({event: 'tick', summary: tickSummary(t, c.limits)}); }
144	        const used = spent(openWorkLedger({root: c.workRoot})).calls;
145	        write({state: 'running', heartbeat: new Date(clock()).toISOString(), last_tick: t ? tickSummary(t, c.limits) : 'no input changed; nothing due',
146	          next_retry_due: state.due ? new Date(state.due).toISOString() : null,
147	          provider_calls: {spent: used, cap: c.limits.total_provider_calls, left: Math.max(0, c.limits.total_provider_calls - used)}});
148	      } catch (e) {
149	        if (e.code === 'NO_AUTHORITY') { event({event: 'blocked', code: e.code, why: e.message}); write({state: 'blocked', why: e.message}); return {code: 3, ticks}; }
150	        errors++;
151	        event({event: 'tick-error', attempt: errors, why: e.message});
152	        write({state: 'error', heartbeat: new Date(clock()).toISOString(), error: e.message, consecutive_errors: errors});
153	        if (errors >= c.max_consecutive_errors) { stopped = `${errors} consecutive tick errors`; break; }
154	      }
155	      if (signal?.aborted || (maxTicks !== null && turns >= maxTicks)) continue;
156	      await sleep(c.interval_ms, signal);
157	    }
158	    write({state: 'stopped', at: new Date(clock()).toISOString(), why: stopped, ticks: ticks.length});
159	    event({event: 'stopped', why: stopped});
160	    return {code: stopped.includes('error') ? 1 : 0, ticks, stopped};
161	  } finally {
162	    lock.release();
163	  }
164	}
