13	function fixture(items) {
14	  const repo = fs.mkdtempSync(path.join(os.tmpdir(), 'operate-'));
15	  const statusRoot = path.join(repo, 'status', 'ledger'), workRoot = path.join(repo, 'status', 'work');
16	  const S = openStatusLedger({root: statusRoot});
17	  for (const i of items) S.set({checked: '2026-11-17', basis: `the requirement of ${i.item}`, ...i});
18	  fs.mkdirSync(path.join(repo, 'tickets'));
19	  return {repo, statusRoot, workRoot, S, done: () => fs.rmSync(repo, {recursive: true, force: true})};
20	}
21	const LIMITS = {total_provider_calls: 1000, stage_provider_calls: 10};
22	// Scripted executors: each passes and records what it was handed. `plan` writes the ticket, as planning must.
23	function scripted(f, overrides = {}) {
24	  const seen = [];
25	  const pass = stage => async ctx => {
26	    seen.push({stage, item: ctx.item, from: ctx.upstream?.stage ?? null, mode: ctx.gate.mode ?? null});
27	    if (stage === 'plan') {
28	      const ticket = {schema: 'ophanim.ticket/v1', item: ctx.item, slice: 'all', proposes: {state: 'Resolved', basis: 'done'}, title: ctx.gate.requirement.title,
29	        goal: 'g', question: 'q', repo_root: '.', slot: 'a', path: 'a.mjs', copy: [], acceptance_cmd: 'true'};
30	      fs.writeFileSync(path.join(f.repo, 'tickets', `${ctx.item}.json`), JSON.stringify(ticket));
31	      const {readTicket} = await import('../../pantheon/src/board/operate.mjs');
32	      const t = readTicket({repo: f.repo, item: ctx.item});
33	      // A revised plan differs from the one it revises (it answers the returned findings).
34	      return {status: 'passed', identity: {ticket: {path: t.path, digest: t.digest}}, outputs: {plan_version: seen.length, ticket: {path: t.path, digest: t.digest}, deps: {}, evidence: []},
35	        team: [{role: 'planner', lab: 'anthropic'}], contributions: [], findings: [], usage: {provider_calls: 3}, next: {stage: 'implement', why: 'approved'}};
36	    }
37	    // Each run produces its own output (a real revision is a different commit).
38	    return {status: 'passed', outputs: {[`${stage}_done`]: true, run: seen.length}, team: [{role: stage}], contributions: [], findings: [], usage: {provider_calls: 2}, next: {stage: null, why: 'ok'}};
39	  };
40	  const ex = Object.fromEntries(['plan', 'implement', 'review', 'validate', 'outcome'].map(s => [s, overrides[s] ?? pass(s)]));
41	  return {ex, seen};
42	}
