29	const seq = (w, item) => w.stages(item).map(s => `${s.stage}:${s.status}`);
30	const idOf = t => resolveModel(t.vendor, t.model).id;
31	const named = t => `${t.vendor}/${t.model}`;
32	const recordOf = rec => JSON.parse(fs.readFileSync(rec.outputs.run.record, 'utf8'));
33	const DONE = ['plan:passed', 'implement:passed', 'review:passed', 'validate:passed', 'outcome:passed'];
34	const ITEMS = ['fresh', 'ticketed'];
35	// Stage 1's tier per item: the fixture ticket declares difficulty `easy`; an item without a ticket declares none.
36	const PLAN_TIER = {fresh: 'medium', ticketed: 'easy'};
