41	// THREE WORK UNITS: `a` (easy) and `c` (hard) are disjoint and share a wave; `b` (medium) builds on `a`.
42	//   a  alpha.mjs exports ok = true                               verified by the fixture's verify.mjs
43	//   b  beta.mjs imports alpha.mjs: passes only on top of `a`     a multi-unit dependency
44	//   c  gamma/**: a module AND its test, one owner; it may consult one subagent
45	const UNITS = [
46	  UNIT('a'),
47	  UNIT('b', {depends_on: ['a'], owned_paths: ['beta.mjs'], difficulty: 'medium', verify_cmd: 'node -e "import(\'./beta.mjs\').then(m => process.exit(m.both === true ? 0 : 1))"', invariants: ['beta.mjs exports both === true, computed from alpha.mjs']}),
48	  UNIT('c', {owned_paths: ['gamma/**'], difficulty: 'hard', allowed_subagents: ['api-designer'], verify_cmd: 'node gamma/gamma.test.mjs', invariants: ['gamma/gamma.mjs exports g === 3 and its test proves it']}),
49	];
50	const THREE = {work_units: UNITS, slices: [{id: 's1', title: 'alpha.mjs exports ok = true', slot: 'alpha', path: 'alpha.mjs'}, {id: 's2', title: 'beta.mjs', slot: 'beta', path: 'beta.mjs'}, {id: 's3', title: 'gamma.mjs', slot: 'gamma', path: 'gamma/gamma.mjs'}]};
51	// The fake agy CLI's worker for those units (sourced with $dir = the unit's worktree, $unit, $model, $prompt): it
52	// writes the unit's files, logs when it started and ended, and unit c asks its subagent one question over A2A.
53	const SPAN = 'printf \'%s %s %s %s\\n\' "$dir" "$unit" "$1" "$(date +%s%N)" >> "$FAKE_AGY_LOG.spans"';
54	// Unit c asks its subagent one question through the stdio MCP server over the unit's Unix socket (the fake CLI's agy_ask).
55	const WORKER = `span() { ${SPAN}; }
56	span start
57	case "$unit" in
58	  a) sleep 0.3; printf 'export const ok = true;\\n' > "$dir/alpha.mjs" ;;
59	  b) printf 'import {ok} from "./alpha.mjs";\\nexport const both = ok === true;\\n' > "$dir/beta.mjs" ;;
60	  c) sleep 0.3; agy_ask api-designer "what should g be?" >/dev/null || exit 1; mkdir -p "$dir/gamma"; printf 'export const g = 3;\\n' > "$dir/gamma/gamma.mjs"; printf 'import {g} from "./gamma.mjs"; if (g !== 3) process.exit(1);\\n' > "$dir/gamma/gamma.test.mjs" ;;
61	esac
62	span end
63	`;
