176	test('LIFECYCLE, default routing (fit): a Stage 5 rejection raises the implementer\'s thinking level first; after repeated rejections the reviewer escalates inside OpenAI only; the reviewer whose finding fed a revision is excluded from the three-lab review, the one that only approved is not', async () => {
177	  await withDispatch(async ctx => {
178	    const {dir: repo, makeClientFor, calls} = ctx;
179	    const f = fixture(repo, ITEMS.map(item => ({item})), {tickets: ['ticketed']});
180	    // The worker revises when it is given the finding (and says so); the pinned reviewer (gpt-6-luna) rejects every
181	    // revision it sees, so after two rejections the reviewer is raised; the next rung approves passing work.
182	    ctx.agyWorker(`case "$prompt" in *"${FINDING}"*) printf '%s %s\\n' "$dir" "$model" >> "$FAKE_AGY_LOG.told"; printf '// frozen: the importer reads it lazily\\nexport const ok = true;\\n' > "$dir/alpha.mjs" ;; *) printf 'export const ok = true;\\n' > "$dir/alpha.mjs" ;; esac\n`);
183	    const turn = scriptedTurn({'unit-review': ({model, rubric, passed}) => JSON.stringify(model === 'gpt-6-luna' || !passed ? unitReject(rubric, [FINDING]) : unitApprove(rubric))});
184	    const ex = makeExecutors({repo, makeClientFor, turn, stateDir: f.stateDir, independence: 'model'});
185	    const r = await tick({repo, statusRoot: f.statusRoot, workRoot: f.workRoot, executors: ex, limits: LIMITS});
186	    const w = openWorkLedger({root: f.workRoot});
187	    assert.equal(w.verify().ok, true);
188	    for (const item of ITEMS) {
189	      // The rejection is answered INSIDE the run (a revision by the same unit owner), not by a failed stage.
190	      assert.deepEqual(seq(w, item), DONE, JSON.stringify(r.dispatched.map(d => [d.item, d.stage, d.status, d.next?.why])));
191	      const [, impl, rev, val] = w.stages(item);
192	      const u = recordOf(impl).units.alpha;
193	      // hydrogen-medium -> hydrogen-high -> hydrogen-xhigh: the same base model, one thinking level up per rejection.
194	      assert.deepEqual(u.attempts.map(a => [a.model, a.status, a.findings_in]), [['gemini-4-hydrogen-medium', 'written', 0], ['gemini-4-hydrogen-high', 'written', 2], ['gemini-4-hydrogen-xhigh', 'written', 2]]);
195	      assert.equal(new Set(u.attempts.map(idOf)).size, 1, 'one model identity: a thinking level is not another model');
196	      // The reviewer: pinned gpt-6-luna twice, then raised one rung, inside OpenAI.
197	      assert.deepEqual(u.reviews.map(v => [named(v), v.level, v.pinned_to_dispatcher, v.status, v.fed_revision]),
198	        [['openai/gpt-6-luna', 0, true, 'request_changes', true], ['openai/gpt-6-luna', 0, true, 'request_changes', true], ['openai/gpt-6.1-sol', 1, false, 'approved', false]]);
199	      assert.deepEqual(u.escalations.map(e => [e.after_attempt, e.kind, e.from.model, e.to.model]), [[1, 'implementer', 'gemini-4-hydrogen-medium', 'gemini-4-hydrogen-high'],
200	        [2, 'implementer', 'gemini-4-hydrogen-high', 'gemini-4-hydrogen-xhigh'], [2, 'reviewer', 'gpt-6-luna', 'gpt-6.1-sol']]);
201	      assert.ok(u.escalations.filter(e => e.kind === 'reviewer').every(e => e.from.vendor === 'openai' && e.to.vendor === 'openai'));
202	      assert.equal(u.reviewer_fed_revision, true);
203	      // The findings are kept on the stage record with the reviewer that made them.
204	      assert.deepEqual(impl.findings.map(x => [x.cause, x.vendor, x.model, x.unit, x.text]).filter(x => x[4] === FINDING), Array(2).fill(['in-run-review', 'openai', 'gpt-6-luna', 'alpha', FINDING]));
205	      // CONTRIBUTIONS: gpt-6-luna's finding fed a revision, so it IS a critique contributor; gpt-6.1-sol only approved
206	      // and is not. The dispatcher (gpt-6-luna as an arbiter) is listed apart.
207	      assert.deepEqual(impl.contributions.map(c => [c.purpose, named(c)]).sort(), [['critique', 'openai/gpt-6-luna'], ['plan', `anthropic/${PLANNER[item]}`],
208	        ['work', 'agy_google/gemini-4-hydrogen-high'], ['work', 'agy_google/gemini-4-hydrogen-medium'], ['work', 'agy_google/gemini-4-hydrogen-xhigh']]);
209	      assert.deepEqual(impl.outputs.arbiters.map(named), ['openai/gpt-6-luna']);
210	      const keys = contributorKeys(impl.contributions);
211	      assert.ok(keys.models.includes('openai/gpt-6-luna') && !keys.models.includes('openai/gpt-6.1-sol'));
212	      // The later three-lab review and the validator exclude the contributing reviewer, by model.
213	      const panel = rev.team.filter(t => t.role === 'cycle-reviewer');
214	      assert.equal(new Set(panel.map(t => t.lab)).size, 3);
215	      for (const t of panel) assert.ok(!keys.models.includes(idOf(t)), `${idOf(t)} contributed and reviewed`);
216	      assert.ok(rev.outputs.author_models.includes('openai/gpt-6-luna'));
217	      assert.ok(!panel.some(t => idOf(t) === 'openai/gpt-6-luna') && idOf(val.outputs.validator) !== 'openai/gpt-6-luna');
218	      assert.match(git(repo, 'show', `${impl.outputs.commit}:alpha.mjs`), /^\/\/ frozen/);
219	    }
220	    assert.deepEqual(lines(path.join(repo, 'agy.log.told')).map(l => l.split(' ')[1]), ITEMS.flatMap(() => ['gemini-4-hydrogen-high', 'gemini-4-hydrogen-xhigh']), 'the finding reached the worker on each raised lane');
221	    assert.equal(calls.length, 0, 'the metered Gemini API wrote nothing');
