1	// The system ledger's core (K1, docs/ledger-provenance-evaluation.md).
2	//
3	// TELOS's proposal ledger is the model: one signed, hash-chained line, verified before every append,
4	// forks refused. This generalizes it without touching the pinned TELOS:
5	//   - one chain, MANY kinds, from a CLOSED registry; each kind names who may author it, validates its
6	//     payload, and RE-DERIVES the entry from the entries it cites (TELOS's verify() re-runs the test;
7	//     here every kind re-derives);
8	//   - every entry is signed by its OWN author's key (not one controller key, not a shared secret), and
9	//     the orderer co-signs only its place in the chain;
10	//   - payloads are content-addressed objects; an entry carries their digest, never a copy;
11	//   - signed checkpoints commit to every earlier entry hash, so verification resumes from the last
12	//     checkpoint and re-derives only the frontier (OPHANIM P6/P8), while the prefix is still re-hashed.
13	//
14	// Strict reading: a torn or unparseable line anywhere is an error, never skipped. Nothing here trusts a
15	// record it has not re-derived.
16	//
17	// Domains (docs/ledger-provenance-evaluation.md, "Shared ledgers and the run-path gate"). One ledger can
18	// hold the kinds of several domains (Pantheon's, OPHANIM's). The authority DECLARES them: genesis, or a
19	// later operator-signed authority entry, names each domain and its kinds (`domains: {name: [kind]}`).
20	// A reader whose registry supplies a domain re-derives its entries. An entry of a declared domain the
21	// reader does not supply is checked structurally only (chain linkage, order and author signatures, a
22	// keyring author, an intact payload): never re-derived, never appended by that reader, and reported in
23	// `verify().foreign`. An entry of a kind no domain declared before it is refused, as before, so the
24	// registry stays closed: what a reader passes over is exactly what the ledger's authority named.
25	import fs from 'node:fs';
26	import os from 'node:os';
27	import path from 'node:path';
28	import {sign as edSign, verify as edVerify, createPrivateKey, createPublicKey, generateKeyPairSync, createHash, randomBytes} from 'node:crypto';
29	import {canonical, digest} from './canonical.mjs';
30	
31	export const LEDGER_SCHEMA = 'ophanim.ledger/v1';
32	export const CHECKPOINT = 'checkpoint';
33	// K2: the ledger's authority is its own first entry. `genesis` names the keyring, the orderer and the
34	// operators (and any pins the caller wants bound, e.g. TELOS's). Readers pin the genesis HASH, so a
35	// ledger that names its own authority is refused unless that authority is the one they pinned.
36	// `authority` entries, signed by a current operator, add or revoke keys and change roles from then on.
37	export const GENESIS = 'genesis';
38	export const AUTHORITY = 'authority';
39	const RESERVED = new Set([CHECKPOINT, GENESIS, AUTHORITY]);
40	const KIND_NAME = /^[a-z][a-z0-9.-]{0,63}$/, DOMAIN_NAME = /^[a-z][a-z0-9-]{0,31}$/;
41	const H = value => 'sha256:' + digest(value);
42	const fail = why => { throw Object.assign(new Error(why), {code: 'LEDGER_REFUSED'}); };
43	
44	export function generateSigner(key_id) {
45	  const {publicKey, privateKey} = generateKeyPairSync('ed25519');
46	  return {key_id, privatePem: privateKey.export({type: 'pkcs8', format: 'pem'}), publicJwk: publicKey.export({format: 'jwk'})};
47	}
48	const signBytes = (value, privatePem) => edSign(null, Buffer.from(canonical(value)), createPrivateKey(privatePem)).toString('base64');
49	const verifyBytes = (value, sig, publicJwk) => {
50	  try { return edVerify(null, Buffer.from(canonical(value)), createPublicKey({key: publicJwk, format: 'jwk'}), Buffer.from(sig, 'base64')); }
51	  catch { return false; }
52	};
53	
54	/**
55	 * A closed kind registry. Each kind: { authors(author) -> bool, validate(payload) -> why|null,
56	 * rederive(entry, view) -> why|null }. `checkpoint` is reserved for the orderer.
57	 */
58	export function defineKinds(spec) {
59	  for (const r of RESERVED) if (Object.hasOwn(spec, r)) fail(`kind "${r}" is reserved`);
60	  for (const [kind, k] of Object.entries(spec)) {
61	    if (!KIND_NAME.test(kind)) fail(`kind name "${kind}" is not an identifier`);
62	    for (const fn of ['authors', 'validate', 'rederive']) if (typeof k[fn] !== 'function') fail(`kind "${kind}" lacks ${fn}()`);
63	  }
64	  return Object.freeze({...spec});
65	}
66	
67	// The body an author signs: everything about the entry except its place in the chain and the signatures.
68	const bodyOf = e => ({schema: e.schema, kind: e.kind, author: e.author, derived_from: e.derived_from, payload_ref: e.payload_ref});
69	const orderOf = e => ({seq: e.seq, parent: e.parent, body: H(bodyOf(e))});
70	const hashOf = e => H(e);
71	// A checkpoint commits to the ordered list of every entry hash before it.
72	const rootOf = hashes => H({hashes});
73	
74	const validAuthority = p => p && typeof p === 'object' && p.keyring && typeof p.keyring === 'object'
75	  && typeof p.orderer === 'string' && Array.isArray(p.operators) && p.operators.length > 0;
76	
77	/** A domain declaration: {name: [kind, ...]}, names and kinds identifiers, no reserved kind. */
78	const validDomains = d => d === undefined || d === null || (typeof d === 'object' && !Array.isArray(d)
79	  && Object.entries(d).every(([name, ks]) => DOMAIN_NAME.test(name) && Array.isArray(ks)
80	    && ks.every(k => typeof k === 'string' && KIND_NAME.test(k) && !RESERVED.has(k))));
81	/** Declarations only grow: a domain's kinds are unioned. */
82	function mergeDomains(current, add) {
83	  const out = Object.fromEntries(Object.entries(current ?? {}).map(([d, ks]) => [d, [...ks]]));
84	  for (const [d, ks] of Object.entries(add ?? {})) out[d] = [...new Set([...(out[d] ?? []), ...ks])].sort();
85	  return out;
86	}
87	// A kind belongs to one domain only.
88	const domainsDisjoint = d => {
89	  const seen = new Set();
90	  for (const ks of Object.values(d)) for (const k of ks) { if (seen.has(k)) return false; seen.add(k); }
91	  return true;
92	};
93	/** The declared domain a kind belongs to, or null. */
94	export const domainOf = (domains, kind) => Object.entries(domains ?? {}).find(([, ks]) => ks.includes(kind))?.[0] ?? null;
95	
96	// The authority as of a point in the chain: genesis, then each authority entry applied in order.
97	function applyAuthority(auth, payload) {
98	  const keys = {...auth.keys, ...(payload.add ?? {})};
99	  for (const id of payload.revoke ?? []) delete keys[id];
100	  return {keys, orderer: payload.orderer ?? auth.orderer, operators: payload.operators ?? auth.operators, pins: auth.pins,
101	    domains: mergeDomains(auth.domains, payload.domains)};
102	}
103	const authorityValid = a => Object.hasOwn(a.keys, a.orderer) && a.operators.length > 0 && a.operators.every(o => Object.hasOwn(a.keys, o))
104	  && domainsDisjoint(a.domains ?? {});
105	
106	/**
107	 * Open a ledger. `anchor` is the genesis hash the reader trusts; it is required, so a ledger is never
108	 * trusted on the strength of the authority it names for itself.
109	 *
110	 * `domains` (optional) names the declared domains this registry supplies. Without it, a reader supplies
111	 * every declared domain its registry holds at least one kind of. A domain is supplied whole or not at
112	 * all: a registry missing one kind of a domain it supplies is refused, not passed over.
113	 */
114	export function openLedger({dir, kinds, anchor, checkpointEvery = 64, domains = null,
115	  lockTimeoutMs = 10_000, lockStaleMs = 600_000, log = msg => process.emitWarning(msg, {code: 'LEDGER_LOCK'})}) {
116	  if (!dir || !path.isAbsolute(dir)) fail('an absolute ledger directory is required');
117	  if (typeof anchor !== 'string' || !/^sha256:[0-9a-f]{64}$/.test(anchor)) fail('a pinned genesis hash (anchor) is required');
118	  const file = path.join(dir, 'chain.jsonl');
119	  const objects = path.join(dir, 'objects');
120	  fs.mkdirSync(objects, {recursive: true});
121	  const objectPath = ref => path.join(objects, ref.slice('sha256:'.length) + '.json');
122	
123	  function putObject(value) {
124	    const ref = H(value), p = objectPath(ref), bytes = canonical(value);
125	    if (fs.existsSync(p)) { if ('sha256:' + digest(JSON.parse(fs.readFileSync(p, 'utf8'))) !== ref) fail(`object collision at ${ref}`); }
126	    else fs.writeFileSync(p, bytes);
127	    return ref;
128	  }
129	  function getObject(ref) {
130	    if (typeof ref !== 'string' || !/^sha256:[0-9a-f]{64}$/.test(ref)) return null;
131	    const p = objectPath(ref);
132	    if (!fs.existsSync(p)) return null;
133	    let value; try { value = JSON.parse(fs.readFileSync(p, 'utf8')); } catch { return null; }
134	    return H(value) === ref ? value : null;           // tampered object: refused, never repaired
135	  }
136	
137	  function read() {
138	    if (!fs.existsSync(file)) return [];
139	    const lines = fs.readFileSync(file, 'utf8').split('\n');
140	    if (lines.at(-1) !== '') fail('ledger ends mid-line (torn append)');
141	    return lines.slice(0, -1).map((line, i) => { try { return JSON.parse(line); } catch { return fail(`line ${i} is not JSON`); } });
142	  }
143	
144	  const supplies = (declared, d) => (domains ? domains.includes(d) : (declared[d] ?? []).some(k => Object.hasOwn(kinds, k)));
145	  // A kind this registry does not hold, given the domains declared so far: {foreign: domain} when it
146	  // belongs to a declared domain this reader does not supply, else {why} (refused).
147	  function unknownKind(kind, auth) {
148	    const d = domainOf(auth?.domains, kind);
149	    if (d === null) return {why: `kind "${kind}" is not in the registry, and no domain declared before it names it`};
150	    if (supplies(auth.domains, d)) return {why: `kind "${kind}" of domain "${d}" is not in the registry, which supplies that domain: the composition is incomplete`};
151	    return {foreign: d};
152	  }
153	
154	  // One entry against everything before it. Returns the reason it is refused, or null. `notes` collects
155	  // what was accepted without full re-derivation: foreign-domain entries, and the parts a kind reports
156	  // it could not re-derive (view.note).
157	  function check(e, i, prev, byHash, auth, {rederive, notes = null}) {
158	    const keyOf = id => (typeof id === 'string' && auth && Object.hasOwn(auth.keys, id) ? auth.keys[id] : null);
159	    if (i === 0) return checkGenesis(e);
160	    if (e?.kind === GENESIS) return `entry ${i}: only the first entry is a genesis`;
161	    if (e?.schema !== LEDGER_SCHEMA) return `entry ${i}: unknown schema`;
162	    if (e.seq !== i + 1) return `entry ${i}: sequence ${e.seq} does not continue the chain`;
163	    if (e.parent !== (prev ? hashOf(prev) : null)) return `entry ${i}: parent is not the previous entry (fork, reorder or deletion)`;
164	    if (!Array.isArray(e.derived_from) || e.derived_from.some(h => !byHash.has(h))) return `entry ${i}: cites an entry that is not earlier in the chain`;
165	    const orderKey = keyOf(auth.orderer);
166	    if (!e.order_sig || !verifyBytes(orderOf(e), e.order_sig, orderKey)) return `entry ${i}: order signature invalid`;
167	    const authorKey = keyOf(e.author?.key_id);
168	    if (!authorKey) return `entry ${i}: author key "${e.author?.key_id}" is not in the keyring`;
169	    if (!e.author_sig || !verifyBytes(bodyOf(e), e.author_sig, authorKey)) return `entry ${i}: author signature invalid`;
170	    const payload = getObject(e.payload_ref);
171	    if (payload === null) return `entry ${i}: payload object missing or altered`;
172	    if (e.kind === AUTHORITY) {
173	      if (!auth.operators.includes(e.author.key_id)) return `entry ${i}: only an operator changes the authority`;
174	      if (!validDomains(payload.domains)) return `entry ${i}: a domain declaration names {domain: [kind]}`;
175	      const next = applyAuthority(auth, payload);
176	      return authorityValid(next) ? null : `entry ${i}: the resulting authority has no valid orderer or operator, or declares a kind in two domains`;
177	    }
178	    if (e.kind === CHECKPOINT) {
179	      if (e.author.key_id !== auth.orderer) return `entry ${i}: only the orderer writes checkpoints`;
180	      const before = [...byHash.keys()];
181	      if (payload.through !== i || payload.root !== rootOf(before)) return `entry ${i}: checkpoint does not commit to the chain before it`;
182	      return null;
183	    }
184	    if (!Object.hasOwn(kinds, e.kind)) {
185	      const u = unknownKind(e.kind, auth);
186	      if (u.why) return `entry ${i}: ${u.why}`;
187	      notes?.foreign.push({seq: e.seq, kind: e.kind, domain: u.foreign});
188	      return null;
189	    }
190	    const k = kinds[e.kind];
191	    if (!k.authors(e.author)) return `entry ${i}: ${e.author.key_id} may not author "${e.kind}"`;
192	    const bad = k.validate(payload);
193	    if (bad) return `entry ${i}: ${bad}`;
194	    if (rederive) {
195	      // entries(): the hashes of every earlier entry, in chain order, for kinds that count what came before.
196	      // note(why): a part of this entry the kind could not re-derive because its input is not available
197	      // (a board that is gone, say). The rest was re-derived; verify() reports the note in `partial`.
198	      const partial = [];
199	      const view = {entry: h => byHash.get(h) ?? null, payload: h => (byHash.has(h) ? getObject(byHash.get(h).payload_ref) : null),
200	        entries: () => [...byHash.keys()], note: why => { partial.push(String(why)); }};
201	      const why = k.rederive({...e, payload}, view);
202	      if (why) return `entry ${i}: does not re-derive: ${why}`;
203	      for (const p of partial) notes?.partial.push({seq: e.seq, kind: e.kind, why: p});
204	    }
205	    return null;
206	  }
207	
208	  function checkGenesis(e) {
209	    if (e?.schema !== LEDGER_SCHEMA || e.kind !== GENESIS || e.seq !== 1 || e.parent !== null) return 'entry 0: the chain must open with a genesis';
210	    if (hashOf(e) !== anchor) return 'entry 0: genesis is not the pinned anchor (a ledger may not name its own authority)';
211	    const payload = getObject(e.payload_ref);
212	    if (!validAuthority(payload) || !validDomains(payload.domains)) return 'entry 0: genesis payload is not an authority';
213	    const a = {keys: payload.keyring, orderer: payload.orderer, operators: payload.operators, domains: mergeDomains({}, payload.domains)};
214	    if (!authorityValid(a) || !a.operators.includes(e.author?.key_id)) return 'entry 0: genesis is not signed by one of its operators';
215	    if (!verifyBytes(bodyOf(e), e.author_sig, a.keys[e.author.key_id]) || !verifyBytes(orderOf(e), e.order_sig, a.keys[a.orderer])) return 'entry 0: genesis signatures invalid';
216	    return null;
217	  }
218	  const authorityAfter = (auth, e) => {
219	    if (e.kind === GENESIS) { const p = getObject(e.payload_ref); return {keys: p.keyring, orderer: p.orderer, operators: p.operators, pins: p.pins ?? null, domains: mergeDomains({}, p.domains)}; }
220	    if (e.kind === AUTHORITY) return applyAuthority(auth, getObject(e.payload_ref));
221	    return auth;
222	  };
223	
224	  /**
225	   * Verify the chain. mode "full" re-derives every entry; "frontier" re-hashes the whole prefix
226	   * (so any edit is caught) but re-checks signatures and re-derives only after the last checkpoint.
227	   * Over the entries it checked, the result says what was accepted without full re-derivation:
228	   * `foreign` (domain -> count of entries checked structurally only), `partial` ([{seq, kind, why}]),
229	   * and `complete`, true only when both are empty.
230	   */
231	  function verify({mode = 'full'} = {}) {
232	    const entries = read();
233	    const byHash = new Map();
234	    let lastCheckpoint = -1;
235	    if (mode === 'frontier') {
236	      for (let i = entries.length - 1; i >= 0; i--) if (entries[i]?.kind === CHECKPOINT) { lastCheckpoint = i; break; }
237	    }
238	    if (!entries.length) return {ok: false, why: 'empty ledger: no genesis'};
239	    let rederived = 0, auth = null;
240	    const notes = {foreign: [], partial: []};
241	    for (const [i, e] of entries.entries()) {
242	      const prev = entries[i - 1] ?? null;
243	      // Authority entries are ALWAYS fully verified, before a checkpoint too. A checkpoint is trusted
244	      // because the orderer signed it, and who the orderer is comes from the authority entries; letting an
245	      // unverified authority entry name the orderer lets a forger name itself and sign its own checkpoint
246	      // (independent review 2026-11-16, RU2). Only ordinary entries may rest on a checkpoint.
247	      if (i > 0 && i < lastCheckpoint && e?.kind !== AUTHORITY) {
248	        // Covered by the checkpoint: linkage is re-hashed here, its commitment is checked at the checkpoint.
249	        if (e?.seq !== i + 1 || e.parent !== (prev ? hashOf(prev) : null)) return {ok: false, why: `entry ${i}: chain linkage broken before the checkpoint`};
250	      } else {
251	        const before = notes.foreign.length;
252	        const why = check(e, i, prev, byHash, auth, {rederive: true, notes});
253	        if (why) return {ok: false, why};
254	        if (!RESERVED.has(e.kind) && notes.foreign.length === before) rederived++;
255	      }
256	      auth = authorityAfter(auth, e);
257	      byHash.set(hashOf(e), e);
258	    }
259	    const foreign = {};
260	    for (const f of notes.foreign) foreign[f.domain] = (foreign[f.domain] ?? 0) + 1;
261	    return {ok: true, entries: entries.length, rederived, head: hashOf(entries.at(-1)), authority: auth,
262	      foreign, partial: notes.partial, complete: notes.foreign.length === 0 && notes.partial.length === 0};
263	  }
264	
265	  // Single writer: an exclusive lock file, then verify-before-append under it. The lock records who
266	  // holds it ({pid, host, time, nonce}). A waiter backs off with jitter for up to `lockTimeoutMs`, and
267	  // breaks, and logs, a lock whose holder is a dead process on this host or that is older than
268	  // `lockStaleMs` (independent review 2026-11-16, SY5: 200 immediate retries, and a crash under the lock
269	  // blocked every later append). A holder removes only its own lock.
270	  function locked(fn) {
271	    const lock = file + '.lock';
272	    const token = JSON.stringify({pid: process.pid, host: LOCK_HOST, time: Date.now(), nonce: randomBytes(8).toString('hex')});
273	    const deadline = Date.now() + lockTimeoutMs;
274	    let fd = null, wait = 1;
275	    for (;;) {
276	      try {
277	        fd = fs.openSync(lock, 'wx');
278	        try { fs.writeSync(fd, token); fs.fsyncSync(fd); }
279	        catch (e) { fs.closeSync(fd); fs.rmSync(lock, {force: true}); throw e; }
280	        break;
281	      } catch (e) { if (e.code !== 'EEXIST') throw e; }
282	      const stale = staleLock(lock, lockStaleMs);
283	      if (stale && breakLock(lock, stale)) { log(`ledger lock ${lock} broken: ${stale.why}`); continue; }
284	      const left = deadline - Date.now();
285	      if (left <= 0) fail('ledger lock held: one writer at a time');
286	      sleepSync(Math.min(left, wait / 2 + Math.random() * wait));
287	      wait = Math.min(wait * 2, 100);
288	    }
289	    try { return fn(); }
290	    finally {
291	      fs.closeSync(fd);
292	      let held = null; try { held = fs.readFileSync(lock, 'utf8'); } catch {}
293	      if (held === token) fs.rmSync(lock, {force: true});
294	      else log(`ledger lock ${lock} was broken while this writer held it`);
295	    }
296	  }
297	
298	  function seal({kind, author, derived_from, payload_ref}, signer, order, entries) {
299	    const prev = entries.at(-1) ?? null;
300	    const e = {schema: LEDGER_SCHEMA, seq: entries.length + 1, parent: prev ? hashOf(prev) : null, kind, author, derived_from, payload_ref};
301	    e.author_sig = signBytes(bodyOf(e), signer.privatePem);
302	    e.order_sig = signBytes(orderOf(e), order.privatePem);
303	    return e;
304	  }
305	
306	  // The verified head (SY5). Append used to re-read and re-hash the whole chain each time, so its cost
307	  // grew with the chain. This instance remembers the chain as it last verified or wrote it (the entries
308	  // and their hashes in order, the authority, the last checkpoint) with the file's identity (device,
309	  // inode, size, mtime, ctime) and a digest of its last line. On the next append, if the file is still
310	  // that file, the prefix is not re-read or re-hashed. What frontier verification checks against things
311	  // OUTSIDE the chain file is still checked every time: the payload objects of the genesis, of every
312	  // authority entry (RU2: authority is never taken on trust) and of the frontier, and the frontier's
313	  // re-derivation. Any difference (an external edit, another writer's append, a replaced file) drops the
314	  // cache, and the append runs full frontier verification as before.
315	  let head = null;
316	  const fileId = fd => {
317	    try { const s = fd === undefined ? fs.statSync(file, {bigint: true}) : fs.fstatSync(fd, {bigint: true}); return {dev: s.dev, ino: s.ino, size: s.size, mtimeNs: s.mtimeNs, ctimeNs: s.ctimeNs}; }
318	    catch { return null; }
319	  };
320	  const sameId = (a, b) => Boolean(a && b) && a.dev === b.dev && a.ino === b.ino && a.size === b.size && a.mtimeNs === b.mtimeNs && a.ctimeNs === b.ctimeNs;
321	  const lineDigest = bytes => createHash('sha256').update(bytes).digest('hex');
322	  function tailMatches(id, tailLen, tail) {
323	    const size = Number(id.size), len = Math.min(size, tailLen + 1);
324	    const buf = Buffer.alloc(len);
325	    const fd = fs.openSync(file, 'r');
326	    try { if (fs.readSync(fd, buf, 0, len, size - len) !== len) return false; } finally { fs.closeSync(fd); }
327	    if (len > tailLen && buf[0] !== 0x0a) return false;              // the line before it still ends there
328	    return lineDigest(buf.subarray(len - tailLen)) === tail;
329	  }
330	
331	  // Full frontier verification, then a fresh head. The file must not change while it is read.
332	  function verifyAndRemember() {
333	    const before = fileId();
334	    const state = verify({mode: 'frontier'});
335	    if (!state.ok) fail(`ledger does not verify, refusing to append: ${state.why}`);
336	    const raw = fs.readFileSync(file);
337	    if (!sameId(before, fileId())) fail('ledger changed while it was verified, refusing to append');
338	    const entries = raw.toString('utf8').split('\n').slice(0, -1).map(line => JSON.parse(line));
339	    const hashes = entries.map(hashOf), last = raw.subarray(raw.lastIndexOf(0x0a, raw.length - 2) + 1);
340	    return {id: before, tailLen: last.length, tail: lineDigest(last), entries, hashes, index: new Map(hashes.map((x, i) => [x, i])),
341	      authority: state.authority, lastCheckpoint: entries.findLastIndex(e => e.kind === CHECKPOINT),
342	      authorityAt: entries.flatMap((e, i) => (i === 0 || e.kind === AUTHORITY ? [i] : []))};
343	  }
344	
345	  // The cached head, re-checked against everything outside the chain file; null when the file changed.
346	  function cachedHead() {
347	    const h = head;
348	    if (!h) return null;
349	    const id = fileId();
350	    if (!sameId(id, h.id) || !tailMatches(id, h.tailLen, h.tail)) return null;
351	    const from = Math.max(h.lastCheckpoint, 0);
352	    for (const i of [...h.authorityAt, ...h.entries.keys().drop(from)]) {
353	      if (getObject(h.entries[i].payload_ref) === null) fail(`ledger does not verify, refusing to append: entry ${i}: payload object missing or altered`);
354	    }
355	    // Re-derive the frontier as verify({mode: 'frontier'}) does: each entry sees only what came before it.
356	    for (let i = from; i < h.entries.length; i++) {
357	      const e = h.entries[i];
358	      if (RESERVED.has(e.kind) || !Object.hasOwn(kinds, e.kind)) continue;
359	      const earlier = x => (h.index.has(x) && h.index.get(x) < i ? h.entries[h.index.get(x)] : null);
360	      const view = {entry: earlier, payload: x => (earlier(x) ? getObject(earlier(x).payload_ref) : null),
361	        entries: () => h.hashes.slice(0, i), note: () => {}};
362	      const why = kinds[e.kind].rederive({...e, payload: getObject(e.payload_ref)}, view);
363	      if (why) fail(`ledger does not verify, refusing to append: entry ${i}: does not re-derive: ${why}`);
364	    }
365	    return h;
366	  }
367	
368	  /**
369	   * Append one entry. `signer` is the author's own key; `order` is the orderer's. The entry is checked,
370	   * including re-derivation, BEFORE it is written; a refused entry leaves the ledger unchanged.
371	   */
372	  function append({kind, payload, author, derivedFrom = [], signer, order}) {
373	    if (kind === CHECKPOINT || kind === GENESIS) fail(`a ${kind} is not appended`);
374	    if (!signer || signer.key_id !== author?.key_id) fail('an entry is signed by its own author');
375	    return locked(() => {
376	      let h;
377	      try { h = cachedHead() ?? verifyAndRemember(); } catch (err) { head = null; throw err; }
378	      head = h;
379	      const {entries, authority} = h;
380	      // A reader appends only what it re-derives: never an entry of a domain it passes over.
381	      if (kind !== AUTHORITY && !Object.hasOwn(kinds, kind)) {
382	        const u = unknownKind(kind, authority);
383	        fail(u.why ?? `kind "${kind}" belongs to domain "${u.foreign}", which this registry does not supply; only a composition that re-derives it may record it`);
384	      }
385	      if (!order || order.key_id !== authority.orderer) fail('the orderer co-signs every entry');
386	      const byHash = {has: x => h.index.has(x), get: x => (h.index.has(x) ? entries[h.index.get(x)] : undefined), keys: () => h.hashes.values()};
387	      const payload_ref = putObject(payload);
388	      const e = seal({kind, author, derived_from: [...derivedFrom], payload_ref}, signer, order, entries);
389	      const notes = {foreign: [], partial: []};
390	      const why = check(e, entries.length, entries.at(-1) ?? null, byHash, authority, {rederive: true, notes});
391	      if (why) fail(why);
392	      const written = [e];
393	      if ((entries.length + 1) % checkpointEvery === 0) {
394	        const all = [...h.hashes, hashOf(e)];
395	        const cp = seal({kind: CHECKPOINT, author: {key_id: order.key_id}, derived_from: [], payload_ref: putObject({through: all.length, root: rootOf(all)})}, order, order, [...entries, e]);
396	        written.push(cp);
397	      }
398	      const lines = written.map(x => JSON.stringify(x) + '\n');
399	      head = null;                                       // a failed or partial write leaves no cache behind
400	      const fd = fs.openSync(file, 'a');
401	      let id;
402	      try { fs.writeSync(fd, lines.join('')); fs.fsyncSync(fd); id = fileId(fd); } finally { fs.closeSync(fd); }
403	      // Extend the head with what was just written: the entry was checked above, the checkpoint is ours.
404	      let auth = authority;
405	      for (const x of written) {
406	        auth = authorityAfter(auth, x);
407	        h.index.set(hashOf(x), entries.length); h.hashes.push(hashOf(x)); entries.push(x);
408	        if (x.kind === CHECKPOINT) h.lastCheckpoint = entries.length - 1;
409	        if (x.kind === AUTHORITY) h.authorityAt.push(entries.length - 1);
410	      }
411	      const last = Buffer.from(lines.at(-1));
412	      Object.assign(h, {id, tailLen: last.length, tail: lineDigest(last), authority: auth});
413	      head = h;
414	      return {hash: hashOf(e), seq: e.seq, checkpoint: written.length > 1 ? hashOf(written[1]) : null, ...(notes.partial.length ? {partial: notes.partial} : {})};
415	    });
416	  }
417	
418	  return {append, verify, read, payloadOf: e => getObject(e.payload_ref), hashOf};
419	}
