421	// The lock holder's host: the hostname and, on Linux, the pid namespace, so a pid is judged dead only
422	// where it was recorded.
423	const LOCK_HOST = (() => { let ns = ''; try { ns = fs.readlinkSync('/proc/self/ns/pid'); } catch {} return os.hostname() + (ns ? ' ' + ns : ''); })();
424	const sleepSync = ms => { if (ms > 0) Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, ms); };
425	const pidAlive = pid => { try { process.kill(pid, 0); return true; } catch (e) { return e.code === 'EPERM'; } };
426	
427	/** Why the ledger lock at `lock` is stale ({raw, why}, with the bytes judged), or null: live, or gone. */
428	export function staleLock(lock, staleMs) {
429	  let raw, st;
430	  try { st = fs.statSync(lock); raw = fs.readFileSync(lock, 'utf8'); } catch { return null; }
431	  let rec = null; try { rec = JSON.parse(raw); } catch {}
432	  if (rec && rec.host === LOCK_HOST && Number.isInteger(rec.pid) && rec.pid > 0 && rec.pid !== process.pid && !pidAlive(rec.pid)) {
433	    return {raw, why: `its holder, pid ${rec.pid} on this host, is not running`};
434	  }
435	  const age = Date.now() - (Number.isFinite(rec?.time) ? rec.time : st.mtimeMs);
436	  if (age > staleMs) return {raw, why: `it has been held for ${Math.round(age)} ms, longer than the ${staleMs} ms bound${rec ? ` (pid ${rec.pid} on ${rec.host})` : ' (unreadable record)'}`};
437	  return null;
438	}
439	// Break a stale lock: move it aside and remove it only if it is still the lock judged stale; a lock
440	// taken in between is put back. True when the stale lock was removed.
441	function breakLock(lock, stale) {
442	  const aside = `${lock}.stale-${process.pid}-${randomBytes(4).toString('hex')}`;
443	  try { fs.renameSync(lock, aside); } catch { return false; }
444	  let raw = null; try { raw = fs.readFileSync(aside, 'utf8'); } catch {}
445	  if (raw !== stale.raw) { try { fs.linkSync(aside, lock); } catch {} fs.rmSync(aside, {force: true}); return false; }
446	  fs.rmSync(aside, {force: true});
447	  return true;
448	}
