450	/**
451	 * Create a ledger: write its genesis, signed by an operator and co-signed by the orderer, and return
452	 * the genesis hash for readers to pin. `authority` is {keyring, orderer, operators, pins?, domains?};
453	 * `domains` declares the kind sets the ledger is created for ({name: [kind]}).
454	 */
455	export function createLedger({dir, authority, operator, order}) {
456	  if (!dir || !path.isAbsolute(dir)) fail('an absolute ledger directory is required');
457	  if (!validAuthority(authority)) fail('genesis needs {keyring, orderer, operators}');
458	  if (!validDomains(authority.domains)) fail('genesis domains are {domain: [kind]}');
459	  const a = {keys: authority.keyring, orderer: authority.orderer, operators: authority.operators, domains: mergeDomains({}, authority.domains)};
460	  if (!authorityValid(a)) fail('genesis orderer and operators must be in its keyring, and a kind is in one domain only');
461	  if (!operator || !authority.operators.includes(operator.key_id)) fail('genesis is signed by one of its operators');
462	  if (!order || order.key_id !== authority.orderer) fail('genesis is co-signed by its orderer');
463	  const file = path.join(dir, 'chain.jsonl');
464	  if (fs.existsSync(file) && fs.statSync(file).size > 0) fail('a ledger already exists here');
465	  fs.mkdirSync(path.join(dir, 'objects'), {recursive: true});
466	  const payload = {keyring: authority.keyring, orderer: authority.orderer, operators: authority.operators, pins: authority.pins ?? null,
467	    ...(authority.domains ? {domains: mergeDomains({}, authority.domains)} : {})};
468	  const bytes = canonical(payload), ref = 'sha256:' + digest(payload);
469	  fs.writeFileSync(path.join(dir, 'objects', ref.slice(7) + '.json'), bytes);
470	  const e = {schema: LEDGER_SCHEMA, seq: 1, parent: null, kind: GENESIS, author: {key_id: operator.key_id}, derived_from: [], payload_ref: ref};
471	  e.author_sig = signBytes(bodyOf(e), operator.privatePem);
472	  e.order_sig = signBytes(orderOf(e), order.privatePem);
473	  fs.writeFileSync(file, JSON.stringify(e) + '\n');
474	  return hashOf(e);
475	}
