1	// The issues intake snapshot: the repository's GitHub issues as DATA for reconciliation (reconcile.mjs), never as
2	// authority. Each issue becomes {number, title, body, state, labels}; reconciliation links an issue to a status item
3	// only by the `<!-- ophanim:item=ID -->` marker the public record writes, and an issue without one is an intake
4	// candidate (recorded by the scheduler through work.intake, never executed). Nothing an issue says changes a gate.
5	//
6	// Inputs: a GitHub token (GITHUB_TOKEN, read-only use) and an owner/name repository, through the public record's
7	// REST client (ophanim/public/github.mjs restClient); or a snapshot file. Outputs: the normalized array.
8	// Must never: write to GitHub, read comments, or treat issue text, labels or state as a decision.
9	import fs from 'node:fs';
10	import {restClient} from '../public/github.mjs';
11	
12	/** One issue, normalized. Pull requests (which the issues endpoint also lists) are dropped (null). */
13	export function normalizeIssue(raw) {
14	  if (!raw || typeof raw !== 'object' || raw.pull_request) return null;
15	  if (!Number.isInteger(raw.number)) throw Object.assign(new Error('an issue in the snapshot has no number'), {code: 'ISSUES_REFUSED'});
16	  return {
17	    number: raw.number,
18	    title: String(raw.title ?? ''),
19	    body: String(raw.body ?? ''),
20	    state: String(raw.state ?? 'open').toLowerCase(),
21	    labels: (raw.labels ?? []).map(l => (typeof l === 'string' ? l : l?.name)).filter(l => typeof l === 'string').sort(),
22	  };
23	}
24	
25	/** Normalize a list (or a {issues: [...]} envelope, as a GitHub MCP listing returns it), sorted by number. */
26	export function normalizeIssues(data) {
27	  const list = Array.isArray(data) ? data : Array.isArray(data?.issues) ? data.issues : null;
28	  if (!list) throw Object.assign(new Error('an issues snapshot is an array of issues or {issues: [...]}'), {code: 'ISSUES_REFUSED'});
29	  return list.map(normalizeIssue).filter(Boolean).sort((a, b) => a.number - b.number);
30	}
31	
32	/** A snapshot file written earlier (by `fetchIssues` or a GitHub listing). */
33	export function readIssuesFile(file) {
34	  return normalizeIssues(JSON.parse(fs.readFileSync(file, 'utf8')));
35	}
36	
37	/** Every issue of `repo` (owner/name), open and closed, read through the public record's REST client. GET only. */
38	export async function fetchIssues({repo = process.env.GITHUB_REPOSITORY, token = process.env.GITHUB_TOKEN, fetchImpl, api} = {}) {
39	  if (!/^[\w.-]+\/[\w.-]+$/.test(repo ?? '')) throw Object.assign(new Error('GITHUB_REPOSITORY (owner/name) is required to read the issues'), {code: 'ISSUES_REFUSED'});
40	  if (!token) throw Object.assign(new Error('GITHUB_TOKEN is required to read the issues'), {code: 'ISSUES_REFUSED'});
41	  const gh = restClient({token, fetchImpl, ...(api ? {api} : {}), log: () => {}});
42	  return normalizeIssues(await gh.paginate(`/repos/${repo}/issues?state=all&per_page=100`));
43	}
