1	// Evidence before judgment (context.mjs, stages.mjs), verified by BEHAVIOUR: each scripted seat reads the prompt it is
2	// actually given and answers from what is in it, so a different answer shows that the evidence reached the seat (or
3	// did not). These are scripted seats, not model judgment: they show delivery, retrieval and routing, never that a
4	// model reasons well. Items without a ticket and with an existing ticket are both covered.
5	import {test} from 'node:test';
6	import assert from 'node:assert/strict';
7	import fs from 'node:fs';
8	import path from 'node:path';
9	import {openWorkLedger} from './work-ledger.mjs';
10	import {tick} from './scheduler.mjs';
11	import {makeExecutors} from './stages.mjs';
12	import {buildDossier, renderDossier, makeRetriever, investigate} from './context.mjs';
13	import {SEATING} from '../../pantheon/src/role/seating.mjs';
14	import {SEAT_FACTS} from '../../pantheon/src/route/router.mjs';
15	import {withDispatch} from '../../pantheon/tests/fixtures/dispatch.mjs';
16	import {git, fixture, APPROVE, json, planFor, ACCEPT, scriptedTurn, LIMITS, stagesOf} from './test-fixtures.mjs';
17	
18	// SYNTHETIC reviewer labs, test-only (none is configured): repeated review cycles consume a lab per contribution.
19	const labs = k => {
20	  const extra = Array.from({length: k}, (_, i) => ({vendor: `synthlab${i + 1}`, model: `synthetic-reviewer-${i + 1}`, band: 'medium', basis: 'SYNTHETIC', why: 'test-only'}));
21	  return {seating: {...SEATING, reviewer: [...SEATING.reviewer, ...extra]},
22	    facts: {...SEAT_FACTS, ...Object.fromEntries(extra.map(x => [x.vendor, {vendor: x.vendor, quota_pool: x.vendor, models: {}}]))}};
23	};
24	const commit = (repo, files, msg) => { for (const [f, c] of Object.entries(files)) { fs.mkdirSync(path.dirname(path.join(repo, f)), {recursive: true}); fs.writeFileSync(path.join(repo, f), c); } git(repo, 'add', '-A'); git(repo, 'commit', '-q', '-m', msg); };
25	const requests = reqs => json({requests: reqs});
26	const plansOf = (f, item) => openWorkLedger({root: f.workRoot}).stages(item).filter(s => s.stage === 'plan');
27	/** A planner that records every prompt it is given and answers with `decide(prompt, item)`. */
28	const planner = (seen, decide) => ({prompt, item}) => { (seen[item] ??= []).push(prompt); return decide(prompt, item); };
29	const run = (repo, f, ex, extra = {}) => tick({repo, statusRoot: f.statusRoot, workRoot: f.workRoot, executors: ex, limits: LIMITS, ...extra});
