1	// A task profile: independent dimensions of a ticket, each driving its OWN dial (the `fit` routing
2	// profile, docs/routing-task-profile.md). `fit` is the lifecycle's default since 2026-11-17 (owner direction);
3	// `argo` is still what the selector uses when no profile is named. A ticket that names only `difficulty` still
4	// runs -- the legacy label maps to a default profile here, and under `fit` it also names the matrix column
5	// (fit-matrix.mjs), which the floors below can raise and never lower.
6	//
7	//   depth      none|light|standard|deep|max  -> the effort rung, mapped proportionally onto the chosen
8	//                                               model's OWN documented ladder (capability-facts.json)
9	//   output     xs|s|m|l|xl                   -> output tier (config/tiers.mjs), capped at the documented ceiling
10	//   context    measured estimate only        -> admission (M7: an unrecorded window is excluded with its reason)
11	//   stakes     low|normal|high|critical      -> minimum model class AND the number of independent review labs
12	//   ambiguity  settled|open|contested        -> planner class floor and an explorer width (distinct labs)
13	//   latency    interactive|batch             -> tie-break toward the faster class (how far fallbacks may climb)
14	//   kind       code|analysis|prose|review    -> capability filter where facts support it, else recorded unfiltered
15	//
16	// Every dimension is {value, basis}; basis is `ticket` (the ticket's own field), `derived:<signal>`, or
17	// `legacy-difficulty`. Every mapping below is PROVISIONAL: a routing judgment, not a measurement.
18	import { documentedEfforts, carriesEffort } from "./protocol.mjs";
19	
20	export const TASK_PROFILE = "pantheon.task-profile/v1";
21	export const DIMENSIONS = Object.freeze({
22	  depth: Object.freeze(["none", "light", "standard", "deep", "max"]),
23	  output: Object.freeze(["xs", "s", "m", "l", "xl"]),
24	  stakes: Object.freeze(["low", "normal", "high", "critical"]),
25	  ambiguity: Object.freeze(["settled", "open", "contested"]),
26	  latency: Object.freeze(["interactive", "batch"]),
27	  kind: Object.freeze(["code", "analysis", "prose", "review"]),
28	});
29	const DECLARED = ["depth", "output", "stakes", "ambiguity", "latency", "kind"];
30	
31	/** The default profile for an old ticket's single label. Explicit dimension fields win over it. */
32	export const LEGACY_PROFILE = Object.freeze({
33	  // `easy` carries LOW stakes (owner direction 2026-11-17, the fit matrix): with normal stakes its class floor was
34	  // `standard`, so no easy ticket could reach the easy column (gpt-6-luna and its peers). Stated stakes still raise it.
35	  easy: Object.freeze({ depth: "light", output: "s", stakes: "low", ambiguity: "settled" }),
36	  medium: Object.freeze({ depth: "standard", output: "m", stakes: "normal", ambiguity: "open" }),
37	  hard: Object.freeze({ depth: "deep", output: "l", stakes: "high", ambiguity: "open" }),
38	});
39	
40	// Dimension -> requirement tables. PROVISIONAL (2026-11-17), unmeasured.
41	export const STAKES_FLOOR = Object.freeze({ low: "fast", normal: "standard", high: "frontier", critical: "frontier" });
42	export const REVIEW_LABS = Object.freeze({ low: 1, normal: 1, high: 2, critical: 3 });
43	export const AMBIGUITY_FLOOR = Object.freeze({ settled: "fast", open: "standard", contested: "frontier" });
44	export const EXPLORER_WIDTH = Object.freeze({ settled: 0, open: 1, contested: 3 });
45	// Roles whose class floor the ambiguity dimension also sets (the planner owns resolving it).
46	export const AMBIGUITY_ROLES = Object.freeze(["planner"]);
47	// How many classes above the floor fallbacks may climb: interactive work prefers the faster class.
48	export const LATENCY_CLIMB = Object.freeze({ interactive: 1, batch: 2 });
49	
50	// Paths: a touched path naming ledger/governance/authority/key/security material is critical; a change
51	// that touches only tests or docs is low. Matched on path segments, so "monkey.mjs" is not a key.
52	const CRITICAL = /(^|[/._-])(ledgers?|governance|authority|authorities|keys?|security|secrets?|signing)([/._-]|$)/i;
53	const LOW = p => /(^|\/)(tests?|docs?)\//i.test(p) || /\.test\.[cm]?[jt]s$/i.test(p) || /\.md$/i.test(p);
54	
55	export function stakesFromPaths(paths = []) {
56	  const list = paths.filter(p => typeof p === "string" && p);
57	  if (!list.length) return null;
58	  const hit = list.find(p => CRITICAL.test(p));
59	  if (hit) return { value: "critical", why: `${hit} names ledger/governance/authority/key/security material` };
60	  if (list.every(LOW)) return { value: "low", why: "every touched path is tests or docs" };
61	  return null;
62	}
63	
64	/** The mapping the profile applies, as data: what selectionPolicy('fit') hashes. */
65	export const PROFILE_MAPPING = Object.freeze({ schema: TASK_PROFILE, dimensions: DIMENSIONS, legacy: LEGACY_PROFILE,
66	  stakes_floor: STAKES_FLOOR, review_labs: REVIEW_LABS, ambiguity_floor: AMBIGUITY_FLOOR, ambiguity_roles: AMBIGUITY_ROLES,
67	  explorer_width: EXPLORER_WIDTH, latency_climb: LATENCY_CLIMB, depth_to_effort: "round(depth_index * (ladder_length - 1) / 4)",
68	  stakes_paths: { critical: CRITICAL.source, low: "tests/ or docs/ segment, *.test.*, *.md" } });
69	
70	/**
71	 * The profile for a ticket. `signals`: {paths} (the files the ticket touches), {context_tokens} (a measured
72	 * estimate, when one exists at this point), {mode} (`batch` for the board dispatcher). Throws on a value
73	 * outside a dimension's set, and on a declared `context`: context is measured, never declared.
74	 */
75	export function taskProfile(spec = {}, signals = {}) {
76	  if (spec.context !== undefined) throw new Error("ticket field \"context\" is not accepted: context is measured (an estimate from the prompt), never declared");
77	  const difficulty = spec.difficulty ?? "medium";
78	  const legacy = LEGACY_PROFILE[difficulty];
79	  if (!legacy) throw new Error(`unknown ticket difficulty "${difficulty}" (known: ${Object.keys(LEGACY_PROFILE).join(", ")})`);
80	  for (const k of DECLARED) if (spec[k] !== undefined && !DIMENSIONS[k].includes(spec[k])) {
81	    throw new Error(`unknown ${k} "${spec[k]}" (known: ${DIMENSIONS[k].join(", ")})`);
82	  }
83	  const ticket = k => spec[k] !== undefined ? { value: spec[k], basis: "ticket" } : null;
84	  const fromLegacy = k => ({ value: legacy[k], basis: "legacy-difficulty" });
85	  const paths = stakesFromPaths(signals.paths);
86	  const docsOnly = paths?.value === "low";
87	  return {
88	    schema: TASK_PROFILE,
89	    difficulty: { value: difficulty, basis: spec.difficulty === undefined ? "legacy-difficulty" : "ticket" },
90	    depth: ticket("depth") ?? fromLegacy("depth"),
91	    output: ticket("output") ?? fromLegacy("output"),
92	    context: Number.isFinite(signals.context_tokens) ? { value: signals.context_tokens, basis: "derived:prompt-chars" } : { value: null, basis: "derived:prompt-chars" },
93	    stakes: ticket("stakes") ?? (paths ? { value: paths.value, basis: "derived:paths" } : (signals.paths?.length
94	      ? (legacy.stakes === "normal" ? { value: "normal", basis: "derived:paths" } : fromLegacy("stakes")) : fromLegacy("stakes"))),
95	    ambiguity: ticket("ambiguity") ?? fromLegacy("ambiguity"),
96	    latency: ticket("latency") ?? { value: signals.mode === "interactive" ? "interactive" : "batch", basis: "derived:dispatch-mode" },
97	    kind: ticket("kind") ?? { value: docsOnly ? "prose" : "code", basis: "derived:paths" },
98	  };
99	}
100	
101	/** The minimum model class for a role under a profile, and why. */
102	export function classFloor(task, role, order = ["fast", "standard", "frontier"]) {
103	  const why = [`stakes ${task.stakes.value} (${task.stakes.basis}) -> ${STAKES_FLOOR[task.stakes.value]}`];
104	  let floor = STAKES_FLOOR[task.stakes.value];
105	  if (AMBIGUITY_ROLES.includes(role)) {
106	    const a = AMBIGUITY_FLOOR[task.ambiguity.value];
107	    why.push(`ambiguity ${task.ambiguity.value} (${task.ambiguity.basis}) -> ${a} for the ${role}`);
108	    if (order.indexOf(a) > order.indexOf(floor)) floor = a;
109	  }
110	  return { value: floor, why: why.join("; ") };
111	}
