26	export const FIT_MATRIX_SCHEMA = "pantheon.fit-matrix/v1";
27	export const FIT_DIFFICULTIES = Object.freeze(["easy", "medium", "hard"]);
28	export const THINKING_LEVELS = Object.freeze(["low", "medium", "high", "xhigh"]);
