41	const freeze = table => Object.freeze(Object.fromEntries(Object.entries(table).map(([k, v]) => [k, Object.freeze(v)])));
42	export const FIT_MATRIX = freeze({
43	  planner: { easy: api("anthropic", "sonnet"), medium: OPUS, hard: api("anthropic", "fable") },
44	  dispatcher: { easy: api("openai", "luna"), medium: api("openai", "sol-6.1"), hard: api("openai", "astra") },
45	  implementer: { easy: lane("gemini-4-hydrogen-medium"), medium: lane("gemini-4-hydrogen-high"), hard: lane("gemini-4-carbon-high") },
46	  subagent: { easy: api("xai", "grok-4.6"), medium: api("xai", "grok-4.6"), hard: api("xai", "grok-4.7") },
