48	/** The implementer's failover ladder per difficulty: Antigravity lanes only, the matrix pick first. */
49	export const IMPLEMENTER_LADDERS = freeze({
50	  easy: [lane("gemini-4-hydrogen-medium"), lane("gemini-3.8-flash-high")],
51	  medium: [lane("gemini-4-hydrogen-high"), lane("gemini-4-argon-high")],
