64	/**
65	 * The reviewer for a unit: the EXACT seat its dispatcher ran on, pinned. Only a matrix dispatcher seat can be pinned;
66	 * anything else throws (a reviewer is never quietly moved to another model or lab).
67	 */
68	export function pinnedReviewer(dispatcherSeat) {
69	  const hit = REVIEWER_ESCALATION.find(s => same(s, dispatcherSeat));
70	  if (!hit) throw new Error(`fit matrix: the reviewer is pinned to the unit's dispatcher, and ${dispatcherSeat?.vendor ?? "?"}/${dispatcherSeat?.model ?? "?"} is not a dispatcher seat (${REVIEWER_ESCALATION.map(s => s.model).join(", ")})`);
