81	/** The seat `fit` starts a role on at a difficulty. `reviewer` is the pinned dispatcher seat of the same difficulty. */
82	export function fitMatrix(role, difficulty) {
83	  const d = level(difficulty);
84	  if (role === "reviewer") return pinnedReviewer(FIT_MATRIX.dispatcher[d]);
85	  const row = FIT_MATRIX[role];
86	  if (!row) throw new Error(`fit matrix: no row for role "${role}" (known: ${FIT_ROLES.join(", ")})`);
87	  return { ...row[d] };
88	}
89	/** The ordered seats of a role at a difficulty: the implementer's lane ladder; every other role, its one pick. */
90	export function fitLadder(role, difficulty) {
91	  const d = level(difficulty);
92	  return role === "implementer" ? IMPLEMENTER_LADDERS[d].map(s => ({ ...s })) : [fitMatrix(role, d)];
93	}
