95	// ---------------------------------------------------------------- Antigravity lanes and their metered API ids
96	/** {base, thinking} of a live Antigravity lane name, or null for anything else. */
97	export function laneParts(model) {
98	  const l = LANES.agy_cli?.[model];
99	  return l && !l.retired && l.base && l.thinking ? { base: l.base, thinking: l.thinking } : null;
100	}
101	/** The thinking levels Antigravity offers for a base model, lowest first. */
102	export function laneLevels(base) {
103	  const have = Object.values(LANES.agy_cli ?? {}).filter(l => !l.retired && l.base === base).map(l => l.thinking);
104	  return THINKING_LEVELS.filter(t => have.includes(t));
105	}
106	/**
107	 * The Antigravity lane for a base Gemini model at an effort: the level asked for, else the highest offered level at
108	 * or below it, else (nothing at or below) the lowest offered. No effort means `high`. Null when the base has no lane.
109	 */
110	export function laneFor(base, effort = null) {
111	  const levels = laneLevels(base);
112	  if (!levels.length) return null;
113	  const want = THINKING_LEVELS.indexOf(effort ?? "high");
114	  const at = want === -1 ? THINKING_LEVELS.indexOf("high") : want;
115	  const pick = [...levels].reverse().find(t => THINKING_LEVELS.indexOf(t) <= at) ?? levels[0];
116	  return lane(`${base}-${pick}`);
117	}
118	/** The metered Gemini API seat of a lane's base model (its quota failover), or null when the registry has no id for it. */
119	export function quotaFailoverFor(laneModel) {
120	  const p = laneParts(laneModel);
121	  if (!p || !Object.values(MODELS.google ?? {}).includes(p.base)) return null;
122	  return { vendor: AGY, model: p.base, effort: p.thinking };
123	}
