125	/**
126	 * The implementer's next seat after a REJECTION, on `ladder` (lane model names, in order): the same base model's next
127	 * thinking level first; at its top, the next rung (the first later entry of another base). Null when the ladder is
128	 * spent or the seat is not a lane. Pure: the record of a decision carries the ladder it was decided on.
129	 */
130	export function implementerEscalation(seat, ladder) {
131	  const here = laneParts(seat?.model);
132	  if (!here || !Array.isArray(ladder)) return null;
133	  const levels = laneLevels(here.base), i = levels.indexOf(here.thinking);
134	  if (i !== -1 && i + 1 < levels.length) return { action: "raise_thinking", vendor: AGY, model: `${here.base}-${levels[i + 1]}`, from: here.thinking, to: levels[i + 1] };
135	  const at = ladder.findIndex(m => laneParts(m)?.base === here.base);
136	  const next = ladder.slice(at + 1).find(m => { const p = laneParts(m); return p && p.base !== here.base; });
137	  return next ? { action: "step_rung", vendor: AGY, model: next } : null;
138	}
