1	// STAGE 1 OUTPUT: the plan's `work_units` — its JSON schema, its validator and the planner's specialist prompt.
2	//
3	// Inputs: a parsed plan object (or the planner's answer text). Outputs: {ok: true, units} with the units in
4	// unit_id order, or {ok: false, refusals: [{code, unit_id, message}]} naming EVERY rule broken.
5	//
6	// A work unit is a COHESIVE multi-file change with one owner: coupled types, implementation and tests stay in ONE
7	// unit, so that no unit can pass its verify_cmd only because another unit will later make it true.
8	//
9	// RESERVED PATHS. The agent transport is configured inside the worktree under names a unit may never own:
10	// `.agents` (Antigravity workspace config, e.g. .agents/mcp_config.json), `.gemini` and `.git`. An owned path that
11	// COULD match one of them at the repository root (`.agents`, `.agents/**`, `*`, `**`, `.*/x`, ...) is refused with
12	// code RESERVED_PATH, and so is any pattern with a literal `.agents`, `.gemini` or `.git` segment at any depth. The
13	// post-turn write jail (implement.mjs) stays the second line: it still judges every changed path from disk.
14	//
15	// Must never: accept a plan with an unknown key, a dangling or cyclic dependency, a path that leaves the
16	// repository or a reserved path; reorder, default or repair a field. A broken plan is refused whole, with each reason named.
17	import { keysRefusal, isObject, str, strictJson } from "./util.mjs";
18	import { pathRefusal, overlapsReserved } from "./paths.mjs";
19	
20	/** Transport configuration lives under these names; no unit may own a path that could match them. */
21	export const RESERVED_NAMES = Object.freeze([".agents", ".gemini", ".git"]);
22	const RESERVED_PATTERNS = Object.freeze(RESERVED_NAMES.flatMap(n => [n, `${n}/**`]));
23	
24	/** Why owned-path pattern `p` could match a reserved path, or null. Assumes pathRefusal(p) is null. */
25	export function reservedPathRefusal(p) {
26	  const hit = RESERVED_PATTERNS.find(r => overlapsReserved(p, r));
27	  if (hit) return `"${p}" could match ${hit}, which is reserved for transport configuration`;
28	  const seg = p.split("/").find(s => RESERVED_NAMES.includes(s.toLowerCase()));
29	  if (seg) return `"${p}" names a ${seg} directory, which is reserved for transport configuration`;
30	  return null;
31	}
32	
33	export const DIFFICULTIES = Object.freeze(["easy", "medium", "hard"]);
34	export const UNIT_KEYS = Object.freeze(["unit_id", "depends_on", "owned_paths", "difficulty", "specialist_role", "allowed_subagents", "verify_cmd", "invariants"]);
35	const UNIT_ID = /^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$/;
36	
37	/** The strict JSON schema of a plan's work units (handed to a transport that supports structured output). */
38	export const WORK_UNITS_SCHEMA = Object.freeze({
39	  $id: "pantheon.pipeline.work-units/v1",
40	  type: "object",
41	  additionalProperties: false,
42	  required: ["work_units"],
43	  properties: {
44	    work_units: {
45	      type: "array",
46	      minItems: 1,
47	      items: {
48	        type: "object",
49	        additionalProperties: false,
50	        required: [...UNIT_KEYS],
51	        properties: {
52	          unit_id: { type: "string", pattern: UNIT_ID.source },
53	          depends_on: { type: "array", items: { type: "string" }, uniqueItems: true },
54	          owned_paths: { type: "array", minItems: 1, items: { type: "string", minLength: 1 }, uniqueItems: true },
55	          difficulty: { enum: [...DIFFICULTIES] },
56	          specialist_role: { type: "string", minLength: 1 },
57	          allowed_subagents: { type: "array", items: { type: "string", minLength: 1 }, uniqueItems: true },
58	          verify_cmd: { type: "string", minLength: 1 },
59	          invariants: { type: "array", minItems: 1, items: { type: "string", minLength: 1 } },
60	        },
61	      },
62	    },
63	  },
64	});
65	
66	const strings = v => Array.isArray(v) && v.every(str);
67	
68	/** Validate a plan. Every broken rule is one named refusal; nothing is repaired. */
69	export function validateWorkUnits(plan) {
70	  const refusals = [];
71	  const no = (code, unit_id, message) => refusals.push({ code, unit_id, message });
72	  const top = keysRefusal(plan, ["work_units"]);
73	  if (top) return { ok: false, refusals: [{ code: "PLAN_SHAPE", unit_id: null, message: `the plan is ${top}; it is {"work_units": [...]}` }] };
74	  if (!Array.isArray(plan.work_units) || !plan.work_units.length) return { ok: false, refusals: [{ code: "PLAN_EMPTY", unit_id: null, message: "work_units is a non-empty array" }] };
75	
76	  const ids = new Map();
77	  plan.work_units.forEach((u, i) => {
78	    const at = isObject(u) && typeof u.unit_id === "string" && u.unit_id !== "" ? u.unit_id : `#${i}`;
79	    if (!isObject(u)) return no("UNIT_SHAPE", at, `work_units[${i}] is not an object`);
80	    const keys = keysRefusal(u, [...UNIT_KEYS]);
81	    if (keys) no(keys.startsWith("unknown") ? "UNKNOWN_KEY" : "MISSING_KEY", at, `unit ${at}: ${keys}`);
82	    if (typeof u.unit_id !== "string" || !UNIT_ID.test(u.unit_id)) no("UNIT_ID", at, `unit ${at}: unit_id is a non-empty string of letters, digits, ".", "_" or "-" (at most 64, starting with a letter or digit)`);
83	    else if (ids.has(u.unit_id)) no("DUPLICATE_UNIT_ID", at, `unit_id "${u.unit_id}" is used by more than one unit`);
84	    else ids.set(u.unit_id, u);
85	    if (!Array.isArray(u.owned_paths) || !u.owned_paths.length) no("OWNED_PATHS_EMPTY", at, `unit ${at}: owned_paths is a non-empty array`);
86	    else {
87	      for (const p of u.owned_paths) {
88	        const why = pathRefusal(p);
89	        if (why) { no("OWNED_PATH", at, `unit ${at}: ${why}`); continue; }
90	        const reserved = reservedPathRefusal(p);
91	        if (reserved) no("RESERVED_PATH", at, `unit ${at}: ${reserved}`);
92	      }
93	      if (new Set(u.owned_paths).size !== u.owned_paths.length) no("OWNED_PATH", at, `unit ${at}: owned_paths repeats a path`);
94	    }
95	    if (!DIFFICULTIES.includes(u.difficulty)) no("DIFFICULTY", at, `unit ${at}: difficulty is one of ${DIFFICULTIES.join(", ")}`);
96	    if (!str(u.specialist_role)) no("SPECIALIST_ROLE", at, `unit ${at}: specialist_role is a non-empty string`);
97	    if (!str(u.verify_cmd)) no("VERIFY_CMD", at, `unit ${at}: verify_cmd is a non-empty string`);
98	    if (!strings(u.invariants) || !u.invariants.length) no("INVARIANTS", at, `unit ${at}: invariants is a non-empty array of non-empty strings`);
99	    if (!strings(u.allowed_subagents)) no("ALLOWED_SUBAGENTS", at, `unit ${at}: allowed_subagents is an array of non-empty strings (it may be empty)`);
100	    else if (new Set(u.allowed_subagents).size !== u.allowed_subagents.length) no("ALLOWED_SUBAGENTS", at, `unit ${at}: allowed_subagents repeats a role`);
101	    if (!Array.isArray(u.depends_on) || !u.depends_on.every(d => typeof d === "string")) no("DEPENDS_ON", at, `unit ${at}: depends_on is an array of unit ids`);
102	  });
103	
104	  // Dependencies are judged over the units that have a usable id, so one bad unit does not hide another's error.
105	  for (const [id, u] of ids) {
106	    if (!Array.isArray(u.depends_on)) continue;
107	    if (new Set(u.depends_on).size !== u.depends_on.length) no("DEPENDS_ON", id, `unit ${id}: depends_on repeats a unit`);
108	    for (const d of u.depends_on) {
109	      if (d === id) no("DEPENDENCY_CYCLE", id, `unit ${id} depends on itself`);
110	      else if (!ids.has(d)) no("UNKNOWN_DEPENDENCY", id, `unit ${id} depends on "${d}", which is not a unit of this plan`);
111	    }
112	  }
113	  const cyc = cycleOf([...ids.values()]);
114	  if (cyc) no("DEPENDENCY_CYCLE", cyc[0], `dependency cycle: ${cyc.join(" -> ")}`);
115	
116	  if (refusals.length) return { ok: false, refusals };
117	  return { ok: true, units: [...ids.values()].sort((a, b) => (a.unit_id < b.unit_id ? -1 : 1)) };
118	}
119	
120	/** A dependency cycle among `units` as [a, b, ..., a], or null. Unknown and self dependencies are ignored here. */
121	export function cycleOf(units) {
122	  const by = new Map(units.map(u => [u.unit_id, u]));
123	  const state = new Map();   // 1 = on the stack, 2 = done
124	  const stack = [];
125	  const visit = id => {
126	    state.set(id, 1); stack.push(id);
127	    for (const d of [...(Array.isArray(by.get(id).depends_on) ? by.get(id).depends_on : [])].sort()) {
128	      if (d === id || !by.has(d)) continue;
129	      if (state.get(d) === 1) return [...stack.slice(stack.indexOf(d)), d];
130	      if (!state.has(d)) { const c = visit(d); if (c) return c; }
131	    }
132	    stack.pop(); state.set(id, 2);
133	    return null;
134	  };
135	  for (const id of [...by.keys()].sort()) if (!state.has(id)) { const c = visit(id); if (c) return c; }
136	  return null;
137	}
