139	/** Parse and validate the planner's ANSWER: the whole text must be the plan object. */
140	export function parseWorkUnits(text) {
141	  const parsed = strictJson(text);
142	  if (!parsed.ok) return { ok: false, refusals: [{ code: "NOT_JSON", unit_id: null, message: parsed.why }] };
143	  return validateWorkUnits(parsed.value);
144	}
