29	export function readPools({rows,env=process.env}={}){
30	  rows??=env.PANTHEON_POOLS_FILE?JSON.parse(readFileSync(env.PANTHEON_POOLS_FILE,'utf8')):[];
31	  if(!Array.isArray(rows))throw new Error('Pool configuration must be an array');
32	  const ids=new Set(),credentials=new Set();
33	  return rows.map(row=>{
34	    if(!/^[A-Za-z0-9_-]+$/.test(row.id??'')||ids.has(row.id)||!['anthropic','openai','xai','agy_google'].includes(row.vendor)||
35	      !['oauth','key'].includes(row.auth)||!/^[A-Z][A-Z0-9_]*$/.test(row.credential_env??''))throw new Error('Invalid or duplicate pool configuration');
36	    if(row.auth==='oauth'&&row.vendor!=='anthropic')throw new Error('This API transport supports configured OAuth only for Anthropic');
37	    const credential=env[row.credential_env];
38	    if(!credential)throw new Error(`Missing credential environment binding for pool ${row.id}`);
39	    const fingerprint=createHash('sha256').update(credential).digest('hex');
40	    if(credentials.has(fingerprint))throw new Error('Two pool IDs use the same credential');
41	    ids.add(row.id);credentials.add(fingerprint);
42	    return {id:row.id,vendor:row.vendor,auth:row.auth,credential_env:row.credential_env};
43	  });
44	}
