70	// GEMINI GOES THROUGH ANTIGRAVITY FIRST (owner direction 2026-11-17), under `argo` and `fit`. In a policy order, a
71	// Google seat that names a metered Gemini API id is served by that model's Antigravity lane first (the lane at the
72	// seat's effort; `high` when the seat carries none; an effort Antigravity does not offer maps to the highest offered
73	// level at or below it). The API id stays in the order ONLY as that lane's QUOTA FAILOVER: it carries
74	// `quota_failover` {base, lanes}, and the dispatcher reaches it only after one of those lanes was refused for quota
75	// (HTTP 429 / quota exhausted, packages/model-client classifyFailure). Any other lane failure never reaches it
76	// (route/quota-failover.mjs walks the order). An API id whose model has no lane is left as it is.
77	export const QUOTA_FAILOVER_RULE='used only after an Antigravity lane of the same base model was refused for quota (HTTP 429 / quota exhausted); never on any other failure';
78	export function antigravityFirst(list,effortOf=c=>c.effort??null){
79	  const out=[];
80	  const has=c=>out.some(o=>o.vendor===c.vendor&&o.model===c.model&&Boolean(o.quota_failover)===Boolean(c.quota_failover));
81	  for(const c of list){
82	    if(c.quota_failover||!(c.vendor==='agy_google'&&seatTransport(c.vendor,c.model)==='api'&&laneLevels(c.model).length)){if(!has(c))out.push(c);continue;}
83	    let lanes=out.filter(o=>!o.quota_failover&&laneParts(o.model)?.base===c.model).map(o=>o.model);
84	    if(!lanes.length){
85	      const {effort:_e,...rest}=c;
86	      const lane=laneFor(c.model,effortOf(c));
87	      out.push({...rest,vendor:lane.vendor,model:lane.model,antigravity_first:c.model});
88	      lanes=[lane.model];
89	    }
90	    const spare={...c,quota_failover:{base:c.model,lanes}};
91	    if(!has(spare))out.push(spare);
92	  }
93	  return out;
94	}
