102	 * The credential pools a seat may be served from. An API seat that names a pool (other than its bare
103	 * vendor) is served from exactly that configured pool, with its configuration, and is never re-resolved to
104	 * the first pool of its vendor (audit M3). A seat naming no pool walks its vendor's configured pools in
105	 * order. A lane/agy seat spends from the vendor's own login, not from an API credential pool.
106	 */
107	export function seatPools(vendor,{pools=[],pool=null,transport='api'}={}){
108	  const named=pool&&pool!==vendor?pool:null;
109	  if(transport!=='api'){
110	    if(named)throw new Error(`seat names API credential pool "${named}", but ${vendor} is served by ${transport}`);
111	    return [{id:vendor,vendor}];
112	  }
113	  const configured=pools.filter(p=>p.vendor===vendor);
114	  if(named){
115	    const exact=configured.find(p=>p.id===named);
116	    if(!exact)throw new Error(`seat names credential pool "${named}", which is not a configured ${vendor} pool`);
117	    return [exact];
118	  }
119	  return configured.length?configured:[{id:vendor,vendor}];
120	}
