136	// ---------------------------------------------------------------- the effective role-selection policy
137	//
138	// ONE policy for the initial seat of planning, implementation and review (owner audit 2026-11-16, M1).
139	// It ADMITS first and chooses second:
140	//
141	//   admit   role capability (the role's own table); context fit (the work's estimated context needs a
142	//           known bound: a documented window smaller than it, or no recorded window at all, is excluded
143	//           with its reason -- audit M7; a lane's bound is its own cited lanes.json `window`); lab independence (avoided vendors AND avoided labs, by
144	//           labOf, so a Claude lane served by agy is the anthropic lab); approved pool (seatPools).
145	//   choose  `legacy`: the ticket's difficulty band (routeFor -> selectFor over the banded SEATING table).
146	//           `argo`:   the approved static ARGO order. That profile IS the operator's approved policy where it
147	//                     applies, so it is recorded as a profile override with its reason and is never silently
148	//                     replaced by a difficulty ranking nobody has measured. Difficulty still sets the output tier.
149	//
150	// Explicit choices outrank the policy, in this order, and each is recorded as what it is:
151	//
152	//   1. escalation        a recorded protocol decision (step_rung) for this slot
153	//   2. slot-override     the operator's per-slot seat (`implementer.<index>` or `implementer.<slot>`)
154	//   3. ticket-pin        the ticket's own slot `model`. A role-wide override naming the SAME model is used as
155	//                        that seat, pool included; otherwise the fallbacks after the pin are the role-wide
156	//                        override if there is one, else the admitted policy order
157	//   4. operator-override the operator's role-wide seat (`--seat role=vendor/model`)
158	//   5. policy | profile  the admitted choice above
159	//
160	// An explicit seat is its chair's only occupant; its pools, in order, are the only transport failover. On
161	// resume the RECORDED seat continues; only a per-slot override given at resume replaces it (run-item.mjs).
162	// Every turn records the selection's source, reason, policy version and policy hash.
163	// CLAIMS (owner audit CS1). A selection separates what made a seat ELIGIBLE (constraints: the admission checks,
164	// and a constraint tag such as SURFACE or ISOLATION with its stated meaning) from why it is ORDERED where it is
165	// (preference). A constraint tag establishes eligibility only; it never orders candidates. No candidate ordering
166	// in this repository has matched evidence, so every preference is `unqualified` with no evidence reference; a
167	// preference may claim `qualified` only with one. Recorded beside the existing reason, which is left as written.
168	export const CONSTRAINT_TAGS=Object.freeze(['SURFACE','ISOLATION','QUOTA','CONTEXT','CONTINUITY']);
169	export function claimsOf(c,selection){
170	  const tag=c.basis??null;
171	  const constraints=[{check:'role',why:`a candidate in the ${selection.role} role's tables`},
172	    ...(selection.context?[{check:'context',why:`documented window admits the estimated ${selection.context.estimate_tokens} tokens`}]:[]),
173	    ...((selection.excluded??[]).some(e=>/lab is avoided|vendor .* is avoided/.test(e.why))?[{check:'independence',why:'avoided vendors and labs excluded'}]:[]),
174	    ...(CONSTRAINT_TAGS.includes(tag)?[{check:'tag',tag,why:BASIS[tag]}]:[])];
175	  const explicit=['slot-override','ticket-pin','operator-override','escalation'].includes(selection.source);
176	  return {constraints,preference:{source:selection.source,
177	    basis:CONSTRAINT_TAGS.includes(tag)?null:tag,
178	    kind:explicit?'operator or recorded decision (an authorization, not a ranking)':'declared order (not a measured ranking)',
179	    status:'unqualified',evidence:null,
180	    ...(CONSTRAINT_TAGS.includes(tag)?{note:`${tag} establishes eligibility only; it does not order this seat above its alternatives`}:{})}};
181	}
