194	  const table=profile==='argo'?seats
195	    :{...Object.fromEntries(['planner','implementer','reviewer'].map(r=>[r,(SEATING[r]??[]).map(row)])),scout:INTAKE.scout.map(row)};
196	  // `fit` also hashes what it applies beyond the role tables: the class table, the dimension mapping, the
197	  // registry it draws candidates from and each role's allowed labs. The argo and legacy bodies are unchanged.
198	  const fit=profile==='fit'?{classes:CLASSES,mapping:PROFILE_MAPPING,registry:registryModels().map(c=>`${c.vendor}/${c.model}`),
199	    eligibility:Object.fromEntries(Object.keys(roleTables()).sort().map(r=>[r,roleLabs(r)])),matrix:FIT_MATRIX_BODY}:{};
200	  // `argo` hashes how its Google seats are served (owner direction 2026-11-17): the Antigravity lane each one starts
