215	export function selectSeat(role,{profile='argo',difficulty='medium',needsContext=null,avoid=[],avoidLabs=[],pools=[],
216	  pin=null,slotOverride=null,roleOverride=null,explicit=null,task=null}={}){
217	  if(!PROFILES.includes(profile))throw new Error(`unknown routing profile "${profile}" (known: ${PROFILES.join(', ')})`);
218	  const id=selectionPolicy(profile,{pools});
219	  // Under `fit` every selection, explicit seats included, records the task profile it ran under.
220	  const profiled=profile==='fit'?{...(task??taskProfile({difficulty})),context:{value:needsContext,basis:'derived:prompt-chars'}}:null;
221	  const base={policy:id.policy,policy_hash:id.hash,profile,role,difficulty,
222	    context:needsContext===null?null:{estimate_tokens:needsContext,method:'prompt chars / 4'},...(profiled?{task:profiled}:{})};
223	  const rows=(c,selection)=>{
224	    const transport=seatTransport(c.vendor,c.model);
