226	    return seatPools(c.vendor,{pools,pool:c.pool??null,transport}).map(pool=>({vendor:c.vendor,model:c.model,transport,
227	      pool:pool.id,poolConfig:pool.credential_env?pool:null,poolNamed,basis:c.basis??'OPERATOR',band:c.band??null,why:c.why??null,
228	      ...(c.effort!==undefined?{effort:c.effort}:{}),...(c.quota_failover?{quota_failover:c.quota_failover}:{}),selection}));
229	  };
230	  const finish=groups=>{
231	    const candidates=groups.flatMap(([c,selection])=>rows(c,selection)).map((c,rank)=>({...c,rank,
232	      selection:{...c.selection,rank,...(rank?{fallback:true}:{}),
233	        ...(c.quota_failover?{quota_failover:{...c.quota_failover,used:false,rule:QUOTA_FAILOVER_RULE}}:{}),claims:claimsOf(c,c.selection)}}));
