235	    return {seat:candidates[0],candidates,selection:candidates[0].selection};
236	  };
237	  const as=(c,source,reason)=>[c,{...base,source,band:c.band??null,reason}];
238	  const why=o=>o.why??'operator reseat';
239	  // A recorded escalation to an Antigravity lane keeps that lane's quota failover (argo and fit): the decision chose
240	  // the model, and its metered API id is the same model. Every other explicit seat is its chair's only occupant.
241	  if(explicit&&explicit.source==='escalation'&&profile!=='legacy'){
