257	function policyCandidates(role,{profile,difficulty,needsContext,avoid,avoidLabs,base}){
258	  if(profile==='fit')return fitCandidates(role,{needsContext,avoid,avoidLabs,base});
259	  const excluded=[];
260	  const admit=c=>{
261	    if(avoid.includes(c.vendor)){excluded.push({model:c.model,why:`vendor ${c.vendor} is avoided`});return false;}
262	    const lab=labOf(c.vendor,c.model);
263	    if(avoidLabs.includes(lab)){excluded.push({model:c.model,why:`the ${lab} lab is avoided (independence)`});return false;}
264	    const w=windowOf(c.model);
265	    // M7: an estimate is admitted only against a known bound. An unrecorded window is excluded with its
266	    // reason, never treated as unlimited -- the same rule routeFor applies on the legacy path.
267	    if(needsContext!==null&&w===null){excluded.push({model:c.model,why:`window unrecorded; cannot admit an estimated ${needsContext}`});return false;}
268	    if(needsContext!==null&&w<needsContext){excluded.push({model:c.model,why:`documented window ${w} < estimated ${needsContext}`});return false;}
269	    return true;
270	  };
271	  if(profile==='argo'){
272	    const order=[...new Map(frontierCandidates(role).map(c=>[`${c.vendor}/${c.model}`,c])).values()].filter(admit);
273	    // A quota failover is kept only with a lane it stands behind.
274	    for(let i=order.length-1;i>=0;i--)if(order[i].quota_failover&&!order.some(o=>order[i].quota_failover.lanes.includes(o.model)))order.splice(i,1);
275	    return order.map((c,i)=>[{vendor:c.vendor,model:c.model,basis:'OPERATOR',why:'ARGO November model policy',...(c.quota_failover?{quota_failover:c.quota_failover}:{})},{...base,source:'profile',band:null,excluded,
276	      reason:`ARGO November model policy: the approved static ${role} order (operator profile); ${c.model} is ${c.quota_failover?`the quota failover of ${c.quota_failover.lanes.join(', ')} (${QUOTA_FAILOVER_RULE})`:i?`admitted fallback ${i}`:'the first admitted seat'}. `+
277	        (c.antigravity_first?`Gemini goes through Antigravity first (owner direction 2026-11-17): this lane serves ${c.antigravity_first}. `:'')+
278	        `Ticket difficulty "${difficulty}" does not choose the model under this profile, and no unmeasured ranking replaces the order. Output caps: a frontier seat keeps the frontier client's long-decode default whatever the difficulty, and the difficulty tier is sent only where the request needs a cap of its own (Anthropic Messages without a frontier default); neither cap is measured`}]);
279	  }
280	  const seating={...SEATING,[role]:(SEATING[role]??[]).filter(c=>admit({vendor:c.vendor,model:modelOf(c)}))};
281	  const pick=routeFor(role,{difficulty,needsContext,seating});
282	  if(!pick.ok)return [];
283	  const usable=candidatesFor(role,{seating}).filter(c=>!pick.skipped.some(s=>s.model===c.model));
284	  const ordered=[usable.find(c=>c.model===pick.model)??pick,...usable.filter(c=>c.model!==pick.model)];
285	  const skipped=[...excluded,...pick.skipped];
286	  return ordered.map((c,i)=>[{vendor:c.vendor,model:c.model,basis:c.basis,band:c.band??null,why:c.why},{...base,source:'policy',band:c.band??null,excluded:skipped,
287	    reason:i?`admitted fallback ${i} after ${pick.model} (${c.basis}${c.band?`, ${c.band} band`:''})`
288	      :`difficulty band: ${pick.why_rung}; ${c.basis}: ${c.why}`}]);
289	}
