382	  /** Write an approved unit's checkpoint. A failure to write is recorded; it does not change the unit's verdict. */
383	  async function keep(u, { patch, unit_base_commit, upstream }) {
384	    const rv = u.reviews.at(-1);
385	    try {
386	      const rec = await writeCheckpoint({ dir: run.checkpoints.dir, patch, record: {
387	        unit_key: u.unit_key, unit_id: u.unit_id, rubric_hash: u.dispatch.rubric_hash, base_commit: run.base.commit, unit_base_commit, upstream,
388	        commit: u.commit, tree: u.tree, reviewer: { vendor: rv.vendor, model: rv.model, served_model: rv.served_model },
389	        verify: { cmd: rv.verify.cmd, exit_code: rv.verify.exit_code, digest: rv.verify.digest }, review_digest: digestOf(clone(rv)) } });
390	      u.checkpoint = { written: true, file: checkpointFile(run.checkpoints.dir, u.unit_key), recorded_at: rec.recorded_at };
391	      run.checkpoints.written.push(u.unit_id);
392	    } catch (e) { u.checkpoint = { written: false, why: String(e?.message ?? e) }; }
393	  }
