395	  /**
396	   * Resume `u` from its checkpoint if it still holds (see checkpoint.mjs): true when the unit is now approved.
397	   * The patch is applied on the unit's freshly bound base (base + upstream patches) and must yield the recorded tree.
398	   */
399	  async function resume(u, upstream, upstreamNow, path) {
400	    const got = await readCheckpoint({ dir: run.checkpoints.dir, unit_key: u.unit_key });
401	    if (!got.found) return false;
402	    const reject = why => { u.checkpoint_rejected = { unit_key: u.unit_key, why, at: now() }; run.checkpoints.rejected.push(u.unit_id); return false; };
403	    if (got.why) return reject(got.why);
404	    const planned = byId.get(u.unit_id);
405	    const why = checkpointRefusal(got, { unit_key: u.unit_key, unit_id: u.unit_id, base_commit: run.base.commit, upstream: upstreamNow, verify_cmd: planned.verify_cmd });
406	    if (why) return reject(why);
407	    let bound = false, ok = false;
408	    try {
409	      const wt = await bindWorktree({ repo, base: run.base.commit, path, upstream, lock });
410	      bound = true;
411	      if (got.patch) {
412	        const r = await git(path, ["apply", "--index", "--whitespace=nowarn", "-"], { input: got.patch, allowFail: true });
413	        if (r.code !== 0) return reject(`the checkpoint's patch does not apply on the unit's base: ${r.stderr.trim().slice(0, 500)}`);
414	      }
415	      const tree = (await git(path, ["write-tree"])).trim();
416	      if (tree !== got.record.tree) return reject(`the checkpoint's patch applied on the unit's base yields tree ${tree}, not the recorded ${got.record.tree}`);
417	      // Ground truth, re-run: the unit's own verify_cmd on the rebuilt tree. A checkpoint is evidence to re-check.
418	      const verify = await runVerify({ worktree: path, verify_cmd: planned.verify_cmd, timeout_ms: lim.verify_timeout_ms, max_output_bytes: lim.verify_output_bytes });
419	      u.resume_verify = { cmd: verify.cmd, exit_code: verify.exit_code, timed_out: verify.timed_out, digest: verify.digest, duration_ms: verify.duration_ms };
420	      if (!verify.passed) return reject(`the unit's verify_cmd fails on the checkpoint's tree (exit ${verify.exit_code}${verify.timed_out ? ", timed out" : ""}): ground truth wins over the recorded approval`);
421	      patches.set(u.unit_id, got.patch);
422	      await writeFile(join(dir, "units", `${u.unit_id}.patch`), got.patch);
423	      Object.assign(u, { resumed: true, base_commit: wt.base_commit, commit: got.record.commit, tree, patch_digest: got.record.patch_digest,
424	        checkpoint: { resumed_from: checkpointFile(run.checkpoints.dir, u.unit_key), recorded_at: got.record.recorded_at, rubric_hash: got.record.rubric_hash, review_digest: got.record.review_digest, reviewer: clone(got.record.reviewer ?? null), verify: clone(got.record.verify ?? null), reverified: clone(u.resume_verify) } });
425	      run.checkpoints.resumed.push(u.unit_id);
426	      finish(u, "approved");
427	      ok = true;
428	      return true;
429	    } finally {
430	      if (bound) { const removed = await releaseWorktree({ repo, path, lock }).catch(() => false); if (ok) u.worktree_removed = removed; }
431	    }
432	  }
433	}
