435	/** Run `fn` over `items` with at most `width` in flight. */
436	async function pool(items, width, fn) {
437	  const queue = [...items];
438	  const worker = async () => { while (queue.length) await fn(queue.shift()); };
439	  await Promise.all(Array.from({ length: Math.max(1, Math.min(width, queue.length)) }, worker));
440	}
