134	  const file = f.file ?? null, line = f.line ?? null;
135	  if (file !== null && !str(file)) return null;
136	  if (line !== null && !(Number.isInteger(line) && line > 0)) return null;
137	  let reproduction = f.reproduction ?? null;
138	  if (typeof reproduction === 'string') reproduction = str(reproduction) ? {kind: 'command', run: reproduction} : null;
139	  if (reproduction !== null && !(['command', 'test'].includes(reproduction.kind) && str(reproduction.run))) return null;
