143	 * A reviewer's reply, read deterministically: {verdict, findings, parsed}. A reply that is not the
144	 * required JSON fails closed (request_changes, one unreproduced blocking finding), and so does a request
145	 * for changes with no finding. The ledger re-runs this on the signed reply to re-derive each finding.
146	 */
147	export function parseReview(reply) {
148	  const fenced = /```json\s*([\s\S]*?)```/.exec(reply ?? '');
149	  const raw = fenced ? fenced[1] : (reply ?? '').slice((reply ?? '').indexOf('{'), (reply ?? '').lastIndexOf('}') + 1);
150	  let j = null;
151	  try { j = JSON.parse(raw); } catch { j = null; }
152	  const findings = Array.isArray(j?.findings) ? j.findings.map(normalFinding) : null;
153	  if (!j || !['approve', 'request_changes'].includes(j.verdict) || !findings || findings.includes(null)) {
154	    return {verdict: 'request_changes', findings: [UNANSWERED], parsed: false};
155	  }
156	  if (j.verdict === 'request_changes' && !findings.length) return {verdict: 'request_changes', findings: [NO_FINDING], parsed: true};
157	  return {verdict: j.verdict, findings, parsed: true};
