598	  let n = 0;
599	  const answer = (prompt, who = {}) => {
600	    if (/VERDICT/i.test(prompt)) return review({ ...who, prompt }) ?? (/exited 1\b/.test(prompt) ? "VERDICT: request_changes" : "VERDICT: approve");
601	    if (/TITLE:/i.test(prompt)) return "TITLE: fixture change";
602	    if (/RAN: nothing/i.test(prompt)) return "RAN: nothing";
603	    return implement(prompt);
604	  };
605	  const makeClientFor = (vendor, { pool = null, poolConfig = null } = {}) => {
606	    const note = (req, prompt) => {
607	      const row = { vendor, model: req.model, pool, poolConfig, prompt, effort: req.reasoning?.effort ?? req.output_config?.effort ?? req.config?.thinkingConfig?.thinkingLevel?.toLowerCase() ?? null,
608	        max_output_tokens: req.max_output_tokens ?? req.max_tokens ?? req.config?.maxOutputTokens ?? null };
609	      const f = fault({ vendor, model: req.model, pool, prompt });
610	      if (f?.error) { calls.push({ ...row, failed: true }); throw f.error; }
611	      calls.push(f?.incomplete ? { ...row, incomplete: true } : row);
612	      return { text: answer(prompt, { vendor, model: req.model, pool }), incomplete: Boolean(f?.incomplete) };
613	    };
614	    return {
615	      responses: { inputTokens: { count: async () => ({ input_tokens: 1000 }) }, create: async req => {
616	        const { text, incomplete } = note(req, typeof req.input === "string" ? req.input : req.input?.at(-1)?.content ?? ""), id = `fixture_${++n}`;
617	        return { async *[Symbol.asyncIterator]() {
618	          const m = served(vendor, req.model);
619	          yield { type: "response.created", response: { id, ...(m ? { model: m } : {}) } };
620	          yield { type: "response.output_text.delta", delta: text };

121	  const add = (mode, p, ro_wins = false, src = null) => {
122	    const r = real(p), at = binds.findIndex(b => b.path === r);
123	    const b = src && real(src) !== r ? { mode, path: r, src: real(src) } : { mode, path: r };
124	    if (at < 0) { binds.push(b); return; }
125	    if (src || (ro_wins ? mode === "ro" : mode === "rw")) { binds.splice(at, 1); binds.push(b); }
126	  };
127	  for (const p of extra_ro) add("ro", p);
128	  for (const p of agy_state_dirs) add("rw", p);
129	  if (gemini_state?.enabled) {
130	    add(gemini_state.mode === "rw" ? "rw" : "ro", gemini_state.gemini_dir);
131	    for (const m of gemini_state.mounts ?? []) add(m.mode === "ro" ? "ro" : "rw", m.dest, false, m.src);
132	  }
133	  add("rw", wt);
134	  add("ro", ctl);
135	  add("rw", run);
136	  // Stable sort by depth: a parent bind first, then what overrides inside it.
137	  binds.sort((a, b) => depth(a.path) - depth(b.path));
138	  const git = repoGitDirs(wt);
139	  if (git) { add("ro", git.common_dir, true); if (!inside(git.common_dir, git.git_dir)) add("ro", git.git_dir, true); }
140	  // The .git read-only binds go last (add() appended them after the sort).
141	  const argv = [bwrap, "--die-with-parent", "--ro-bind", "/", "/", "--dev", "/dev", "--proc", "/proc", "--tmpfs", "/tmp"];
142	  for (const b of binds) argv.push(b.mode === "rw" ? "--bind" : "--ro-bind", b.src ?? b.path, b.path);
143	  argv.push("--chdir", ctl, "--");
144	  return { argv, binds, git };
145	}
146	
147	const probes = new Map();
148	/**
149	 * Is bwrap usable here? Runs `bwrap --ro-bind / / true` once per binary (cached). Returns {ok, why?}.
150	 * Async; never throws.
151	 */
152	export function sandboxAvailable(bwrap = "bwrap") {
153	  if (!probes.has(bwrap)) {
154	    probes.set(bwrap, (async () => {
155	      try {
156	        if (bwrap.includes("/") && !existsSync(bwrap)) return { ok: false, why: `${bwrap} does not exist` };
157	        const r = await spawnPromise(bwrap, ["--ro-bind", "/", "/", "true"], { timeout: 10000 });
158	        return r.status === 0 ? { ok: true } : { ok: false, why: `the bwrap probe exited ${r.status ?? r.killedFor}: ${String(r.stderr ?? "").trim().slice(0, 200)}` };
159	      } catch (e) {
160	        return { ok: false, why: `bwrap could not be started: ${e?.code ?? e?.message ?? e}` };
161	      }
162	    })());
163	  }
164	  return probes.get(bwrap);
165	}
166	
167	/**
168	 * EXPLICIT writable agy state dirs, used only when the caller injects none: PANTHEON_AGY_STATE_DIRS (":"-separated)
169	 * when set, else NONE. (The earlier default bound ~/.gemini read-write; ~/.gemini is now covered by the state layout,
170	 * see geminiState: read-only, with a per-run writable scratch copy over antigravity-cli/.) Only existing directories
171	 * are returned (bwrap cannot bind a missing source).
172	 */
173	export function defaultAgyStateDirs(env = process.env) {
174	  const listed = env.PANTHEON_AGY_STATE_DIRS != null ? String(env.PANTHEON_AGY_STATE_DIRS).split(":") : [];
175	  return listed.filter(Boolean).filter(p => { try { return statSync(p).isDirectory(); } catch { return false; } });
176	}
177	
178	/** The CLI's state directory, relative to ~/.gemini (observed on agy 1.5.10, owner's probe 2026-11-18). */
179	export const GEMINI_CLI_DIR = "antigravity-cli";
180	/**
181	 * The subdirectories of ~/.gemini/antigravity-cli the CLI WRITES (observed on agy 1.5.10, owner's probe 2026-11-18:
182	 * each one failed "read-only file system"; `log` observed in the probe of 5893432: `agy agents` failed writing
183	 * ~/.gemini/antigravity-cli/log/...). They start EMPTY in the scratch; the host's copies stay hidden.
184	 */
185	export const GEMINI_STATE_SUBDIRS = Object.freeze(["conversations", "brain", "presence", "cache", "implicit", "crashes", "mcp", "log"]);
186	/**
187	 * The ONLY top-level files of ~/.gemini/antigravity-cli copied into the scratch (mode kept). Every other top-level file
188	 * (observed on the owner's host 2026-11-18: history.jsonl, conversation_summaries.db, jetbox_summaries_proto.pb) is
189	 * withheld: history, summaries and databases never leave the host directory.
190	 */
191	export const GEMINI_CLI_COPY = Object.freeze(["settings.json", "antigravity-oauth-token", "installation_id", "jetski_state.pbtxt", "last_check.timestamp"]);
192	/**
193	 * Directories under ~/.gemini (relative) that get a per-run writable scratch copy when they are plain directories on
194	 * the host (observed, owner's probe of 5893432, 2026-11-18: `agy agents` in the jail failed "read-only file system"
195	 * writing ~/.gemini/config/projects/default-cli-project.json.<rand>.tmp). Absent ones are not created.
196	 */
197	export const GEMINI_WRITABLE_COPIES = Object.freeze(["config/projects"]);
198	/**
199	 * Subdirectories of ~/.gemini/antigravity-cli that get a per-run WRITABLE COPY inside the scratch (regular files copied
200	 * with their mode, symlinks recreated, subdirs ro-bound). Observed on agy 1.5.10 (owner's machine, first real worker
201	 * turn, 2026-11-18): run_command writes its helper script bin/agentapi before running anything, and failed
202	 * "open ~/.gemini/antigravity-cli/bin/agentapi: read-only file system" while bin/ was ro-bound from the host.
203	 */
204	export const GEMINI_WRITABLE_SUBDIR_COPIES = Object.freeze(["bin"]);
205	const layoutError = (message, more = {}) => Object.assign(new Error(message), { code: "AGY_STATE_LAYOUT", ...more });
206	const byName = (a, b) => a.name.localeCompare(b.name);
207	
208	/**
209	 * Copy the regular files of host dir `from` into the (existing) scratch dir `to` (mode kept) when `want(name)`; for each
210	 * host subdir not in `emptySubdirs` or `copySubdirs`, create a mount point in the scratch and ro-bind the host subdir
211	 * over it; each subdir in `copySubdirs` becomes a writable copy (recursively: files, symlinks recreated, subdirs
212	 * ro-bound). `symlinks` "skip" (default: recorded in skipped) | "recreate". Returns {copied: [names], withheld: [{name,
213	 * size}], skipped: [{name, kind}], readonly: [names], mounts, symlinks: [{name, target}], writable_subdirs: [{name, src,
214	 * dest, copied, symlinks, skipped, readonly_subdirs}]}.
215	 */
216	export async function copyLevel(from, to, { want = () => true, emptySubdirs = [], copySubdirs = [], symlinks = "skip" } = {}) {
217	  const out = { copied: [], withheld: [], skipped: [], readonly: [], mounts: [], symlinks: [], writable_subdirs: [] };
218	  for (const e of (await readdir(from, { withFileTypes: true })).sort(byName)) {
219	    const host = join(from, e.name), dst = join(to, e.name);
220	    if (e.isSymbolicLink()) {
221	      if (symlinks !== "recreate") { out.skipped.push({ name: e.name, kind: "symlink" }); continue; }
222	      const target = await readlink(host);
223	      await symlink(target, dst);   // the same target: a relative one resolves inside the copy, an absolute one to the (read-only) host
224	      out.symlinks.push({ name: e.name, target });
225	      continue;
226	    }
227	    if (e.isDirectory() && copySubdirs.includes(e.name)) {
228	      // A per-run writable copy of this subdir (GEMINI_WRITABLE_SUBDIR_COPIES): files and symlinks copied, subdirs ro-bound.
229	      await mkdir(dst, { mode: 0o700 });
230	      const lvl = await copyLevel(host, dst, { symlinks: "recreate" });
231	      await chmod(dst, (await stat(host)).mode & 0o7777);   // the host dir's mode, set after the copy filled it
232	      out.mounts.push(...lvl.mounts);
233	      out.writable_subdirs.push({ name: e.name, src: host, dest: dst, copied: lvl.copied, symlinks: lvl.symlinks, skipped: lvl.skipped, readonly_subdirs: lvl.readonly });
234	      continue;
235	    }
236	    if (e.isFile()) {
237	      const st = await stat(host);
238	      if (!want(e.name)) { out.withheld.push({ name: e.name, size: st.size }); continue; }
239	      await copyFile(host, dst);
240	      await chmod(dst, st.mode & 0o7777);
241	      out.copied.push(e.name);
242	    } else if (e.isDirectory()) {
243	      if (emptySubdirs.includes(e.name)) continue;   // created empty by the caller
244	      await mkdir(dst);                                 // the mount point, inside the scratch
245	      out.mounts.push({ dest: host, src: host, mode: "ro" });
246	      out.readonly.push(e.name);
247	    } else out.skipped.push({ name: e.name, kind: "other" });
248	  }
249	  return out;
250	}

