    let implCalls = 0, valCalls = 0;
    const ex = {
      plan: async ctx => {
        const tf = path.join(repo, 'tickets', `${ctx.item}.json`);
        const tk = {schema: 'ophanim.ticket/v1', item: ctx.item, slice: 's', proposes: {state: 'Resolved', basis: 'b'},
