    // The approved plan document inside outputs.plan still has the OLD requirement, while identity.requirement was stamped with the NEW requirement!
    assert.match(passedPlan.outputs.plan.requirement.basis, /OLD REQUIREMENT/);
    const gateAfter = reconcile({repo, statusRoot: f.statusRoot, workLedger: w}).items[0].gate;
    // And later stages ran on it all the way to awaiting-owner!
    assert.equal(gateAfter.gate, 'awaiting-owner');
  });
});

